INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位老人在树下坐了久。", "corrected_sentence": "那位老人在树下坐了很久。", "error_description": "时量补语前缺少程度副词：表示动作持续时间的“久”前要加“很”，应为“坐了很久”，不能说“坐了久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
