INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21868, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人有困难，你去帮助他。", "primary_collocate": null, "pronunciation": "bāng máng", "ipa": "paŋ˥ maŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我搬家的时候，朋友来帮忙了。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "需要帮忙的话，请告诉我。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你昨天帮忙。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学有困难，我们应该去帮忙。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做饭的时候，我去厨房帮忙。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很爱帮忙，大家都喜欢他。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事太难了，请你帮忙吧。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们来帮忙，一会儿就搬完了。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要不要我帮忙？", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人需要帮忙，你快去看看。", "target_word": "帮忙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "帮帮忙", "label": "重叠"}, {"form": "帮了忙", "label": "体标"}, {"form": "幫忙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别人有困难时去帮助他（离合词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7aa7a4f-1236-4805-b7d4-46fc3a94a1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帮忙", "is_correct": true, "explanation": "正确：表示朋友来给搬家的人提供帮助，与“搬家”的语境相符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：上课指在学校学习，与“搬家的时候”的场景不相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，与搬家时朋友的行动无关。"}, {"text": "罚款", "is_correct": false, "explanation": "搭配：罚款一般由执法者施行，“朋友来罚款”与搬家语境不搭配。"}], "explanations": {"帮忙": "正确：表示朋友来给搬家的人提供帮助，与“搬家”的语境相符。", "上课": "语义：上课指在学校学习，与“搬家的时候”的场景不相符。", "考试": "语义：考试是测验，与搬家时朋友的行动无关。", "罚款": "搭配：罚款一般由执法者施行，“朋友来罚款”与搬家语境不搭配。"}, "sentence_index": 0, "correct_answer": "帮忙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班找到了一个帮忙。", "explanation": "这里应用〈帮手〉。“帮忙”是动词，不能表示能帮忙的人，应说〈帮手〉。"}, {"text": "这个问题很帮忙，大家都没听懂。", "explanation": "这里应用〈难〉。“帮忙”不能形容问题，说问题难应用〈难〉。"}, {"text": "他在饭店里是个帮忙，一直很忙。", "explanation": "这里应用〈服务员〉。“帮忙”是动词，不能表示职业身份，应说“服务员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "帮忙", "is_correct": true, "explanation": "正确：请求别人提供帮助，与“这件事太难了”的语境相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是休闲活动，与“这件事太难了”的请求语境不符。"}, {"text": "上学", "is_correct": false, "explanation": "语义：上学指去学校学习，与“请你……吧”的求助语境不符。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“请你游泳吧”与“这件事太难了”的语境不搭配，无法表示求助。"}], "explanations": {"帮忙": "正确：请求别人提供帮助，与“这件事太难了”的语境相符。", "散步": "语义：散步是休闲活动，与“这件事太难了”的请求语境不符。", "上学": "语义：上学指去学校学习，与“请你……吧”的求助语境不符。", "游泳": "搭配：“请你游泳吧”与“这件事太难了”的语境不搭配，无法表示求助。"}, "sentence_index": 6, "correct_answer": "帮忙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜很帮忙，我每天都想吃。", "explanation": "这里应用〈好吃〉。“帮忙”不能形容食物的味道，说味道好应用〈好吃〉。"}, {"text": "他的帮忙在银行上班，每天都很忙。", "explanation": "这里应用〈职员〉。“帮忙”不能表示职业身份，说在银行工作的人应用〈职员〉。"}, {"text": "这家店的帮忙在门口卖菜，我经常来买东西。", "explanation": "这里应用〈店员〉。“帮忙”是动词，不能指做事的人，也不能作主语卖菜，应说“店员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天去帮忙我吧。", "corrected_sentence": "我们明天去帮忙吧。", "error_description": "离合错误：“帮忙”是离合词，后面不能直接带宾语“我”。正确形式：我们明天去帮忙吧。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "邻居帮了我很大的帮忙。", "corrected_sentence": "邻居帮了我很大的忙。", "error_description": "离合错误：“帮忙”是离合词，拆开用时说“帮了我很大的忙”，后面只用“忙”，不能再重复“帮忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21870, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最晚", "is_correct": true, "explanation": "最晚指时间上排在最后，与“最早”构成反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮指外貌好看，与“最早”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音或喧闹，与“最早”没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "高大指身材或体积大，与“最早”没有反义关系。"}], "correct_answer": "最晚", "explanations": {"最晚": "最晚指时间上排在最后，与“最早”构成反义关系。", "漂亮": "漂亮指外貌好看，与“最早”没有反义关系。", "安静": "安静指没有声音或喧闹，与“最早”没有反义关系。", "高大": "高大指身材或体积大，与“最早”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21870, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最晚", "is_correct": true, "explanation": "最晚指时间上排在最后，与“最早”构成反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明指脑子反应快、会思考，与“最早”没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "寒冷指温度很低，与“最早”没有反义关系。"}, {"text": "辛苦", "is_correct": false, "explanation": "辛苦指费力、劳累，与“最早”没有反义关系。"}], "correct_answer": "最晚", "explanations": {"最晚": "最晚指时间上排在最后，与“最早”构成反义关系。", "聪明": "聪明指脑子反应快、会思考，与“最早”没有反义关系。", "寒冷": "寒冷指温度很低，与“最早”没有反义关系。", "辛苦": "辛苦指费力、劳累，与“最早”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21870, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示在时间上排在最前面，比如第一个到的。", "primary_collocate": null, "pronunciation": "zuì zǎo", "ipa": "tswei˥˩ tsau˨˩", "syllable_count": 2, "sentences": [{"text": "他是今天最早到学校的人。", "target_word": "最早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我最早学会的歌。", "target_word": "最早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最早的火车早上五点开。", "target_word": "最早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班她来得最早。", "target_word": "最早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最早知道这个好消息。", "target_word": "最早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店九点开门，我是最早的客人。", "target_word": "最早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天最早开的花是梅花。", "target_word": "最早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最早的时候，这里什么都没有。", "target_word": "最早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我最早的一班飞机是几点。", "target_word": "最早", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最早什么时候能到？", "target_word": "最早", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "最早的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "在时间上排在最前面的，最先的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e7fa8c-7e28-4a9f-9f73-de782ccd99f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最早", "is_correct": true, "explanation": "“最早”表示时间上最先，修饰“到学校”，符合句意。"}, {"text": "最漂亮", "is_correct": false, "explanation": "语义：“漂亮”说的是外貌，不表示时间先后，与“到学校”不搭。"}, {"text": "最甜", "is_correct": false, "explanation": "语义：“甜”说的是味道，不表示时间先后，与“到学校”不搭。"}, {"text": "最硬", "is_correct": false, "explanation": "搭配：“硬”不能修饰“到学校”这样的动作。"}], "explanations": {"最早": "“最早”表示时间上最先，修饰“到学校”，符合句意。", "最漂亮": "语义：“漂亮”说的是外貌，不表示时间先后，与“到学校”不搭。", "最甜": "语义：“甜”说的是味道，不表示时间先后，与“到学校”不搭。", "最硬": "搭配：“硬”不能修饰“到学校”这样的动作。"}, "sentence_index": 0, "correct_answer": "最早"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天早上我最早吃了早饭，然后去上学。", "explanation": "这里应该用〈先〉。表示两个动作的先后顺序要用先；最早指时间上排在最前面，不用来连接前后动作。"}, {"text": "进入实验室前，我们最早要戴上手套。", "explanation": "这里应该用〈首先〉。首先用于引出步骤中的第一步，最早只表示时间上排在最前，不能用来表示先做什么。"}, {"text": "我们三个人都最早到了教室。", "explanation": "这里应该用〈很早〉。最早只能指排第一的人，三个人不能都是最早，描述到得早要用很早。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最早", "is_correct": true, "explanation": "“最早”表示时间上最先开，修饰“开的花”，句意通顺。"}, {"text": "最强", "is_correct": false, "explanation": "语义：“强”说的是强弱，与花开的时间先后无关。"}, {"text": "最轻", "is_correct": false, "explanation": "语义：“轻”说的是重量，与花开的时间无关。"}, {"text": "最冷", "is_correct": false, "explanation": "语义：“冷”说的是温度，与花开的时间先后无关。"}], "explanations": {"最早": "“最早”表示时间上最先开，修饰“开的花”，句意通顺。", "最强": "语义：“强”说的是强弱，与花开的时间先后无关。", "最轻": "语义：“轻”说的是重量，与花开的时间无关。", "最冷": "语义：“冷”说的是温度，与花开的时间先后无关。"}, "sentence_index": 6, "correct_answer": "最早"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班每个同学都最早交了作业。", "explanation": "这里应该用〈很早〉。最早只能说排第一的一个，全班每个人都最早不成立，描述交作业的时间要用很早。"}, {"text": "大家都最早到了会场。", "explanation": "这里应该用〈很早〉。最早表示排第一，大家都最早到不成立，描述到达的时间早要用很早。"}, {"text": "我每天早上最早刷牙，然后洗脸。", "explanation": "这里应该用〈先〉。表示动作的先后顺序要用先；最早指时间上排在最前面，不用来连接前后动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是最早的到办公室的人。", "corrected_sentence": "她是最早到办公室的人。", "error_description": "错误在多加了“的”。“最早”在这里修饰动词“到”，作状语，不加“的”，正确形式是“最早到办公室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她比我最早到办公室。", "corrected_sentence": "她最早到办公室。", "error_description": "错误在于“最早”是最高级，不能与“比我”同用。正确形式是“她最早到办公室”；要比较时应说“她比我早到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "记得", "is_correct": true, "explanation": "正确：“记得”与“忘记”构成反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "旅行", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}], "correct_answer": "记得", "explanations": {"记得": "正确：“记得”与“忘记”构成反义关系。", "思考": "与“忘记”无反义关系，二者语义无对立。", "旅行": "与“忘记”无反义关系，二者语义无对立。", "唱歌": "与“忘记”无反义关系，二者语义无对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "记得", "is_correct": true, "explanation": "正确：“记得”与“忘记”构成反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "写字", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“忘记”无反义关系，二者语义无对立。"}], "correct_answer": "记得", "explanations": {"记得": "正确：“记得”与“忘记”构成反义关系。", "游泳": "与“忘记”无反义关系，二者语义无对立。", "写字": "与“忘记”无反义关系，二者语义无对立。", "吃饭": "与“忘记”无反义关系，二者语义无对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不记得了。", "primary_collocate": null, "pronunciation": "wàng jì", "ipa": "wɑŋ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "我忘记今天是妈妈的生日。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对不起，我忘记带钱包了。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别忘记带伞，下午会下雨。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他忘记关灯就出门了。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘记了你昨天说的话。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的名字我忘记了，能再说一次吗？", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她忘记锁门，家里进了小偷。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘记把作业放在哪儿了。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要忘记明天的会。", "target_word": "忘记", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一着急，就忘记了该说什么。", "target_word": "忘记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忘记了", "label": "体标"}, {"form": "忘记过", "label": "体标"}], "register": "中性", "sense_fingerprint": "没有记得要做的事或该记的事，不记得了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71661477-2f15-4858-bb22-282f8f8aa695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忘记", "is_correct": true, "explanation": "正确：没有记得“今天是生日”这件事，可以填入空格。"}, {"text": "举办", "is_correct": false, "explanation": "语义：“今天是妈妈的生日”不能被举办，句子语义不通。"}, {"text": "进行", "is_correct": false, "explanation": "搭配：“进行”后接动作性名词，“今天是妈妈的生日”不是动作。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“今天是妈妈的生日”不能被唱，句子语义不通。"}], "explanations": {"忘记": "正确：没有记得“今天是生日”这件事，可以填入空格。", "举办": "语义：“今天是妈妈的生日”不能被举办，句子语义不通。", "进行": "搭配：“进行”后接动作性名词，“今天是妈妈的生日”不是动作。", "唱": "语义：“今天是妈妈的生日”不能被唱，句子语义不通。"}, "sentence_index": 0, "correct_answer": "忘记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的左手忘记了，拿不住东西。", "explanation": "这里应该用〈麻木〉。“忘记”指不记得，主语应是人，不能说手“忘记”了。"}, {"text": "他的信心忘记了，所以不想再努力。", "explanation": "这里应该用〈失去〉。“忘记”指没记得，不用于信心消失。"}, {"text": "他的视力忘记了，看不清黑板上的字。", "explanation": "这里应该用〈下降〉。“忘记”指不记得，不能用于视力变差。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忘记", "is_correct": true, "explanation": "正确：没记得要锁门，可以填入空格。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱锁门”说不通，句子语义不通。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”的对象是纸类等薄物，不能撕“锁门”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：锁门不能被吃，句子语义不通。"}], "explanations": {"忘记": "正确：没记得要锁门，可以填入空格。", "唱": "语义：“唱锁门”说不通，句子语义不通。", "撕": "搭配：“撕”的对象是纸类等薄物，不能撕“锁门”。", "吃": "语义：锁门不能被吃，句子语义不通。"}, "sentence_index": 6, "correct_answer": "忘记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杯子忘记了，我们只好用碗。", "explanation": "这里应该用〈打碎〉。“忘记”指不记得，不能用于杯子破碎。"}, {"text": "他的护照忘记了，只好回国重办。", "explanation": "这里应该用〈丢〉。“忘记”不用于证件遗失。"}, {"text": "他的爱好忘记了，整天不开心。", "explanation": "这里应该用〈失去〉。“忘记”指没记得，不用于爱好消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天忘记着锁门了。", "corrected_sentence": "我昨天忘记锁门了。", "error_description": "体标错误：“忘记”后接动作时不用“着”，应说「忘记锁门了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这件事忘记。", "corrected_sentence": "我把这件事忘记了。", "error_description": "把字句：动词后要带“了”等成分，应说「我把这件事忘记了」，不能说「我把这件事忘记」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
