INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "音符是表示音乐声音高低的符号。", "primary_collocate": null, "pronunciation": "yīn fú", "ipa": "in˥ fu˧˥", "syllable_count": 2, "sentences": [{"text": "音符在线上的位置高，声音就高。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐谱上的音符越往上，声音越高。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在五线谱上写了几个音符。", "target_word": "音符", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些音符连起来，就是一首好听的歌。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个音符。", "target_word": "音符", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们学着唱每个音符的名字。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕上跳出一个小音符。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个音符太低了，我唱不出来。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手链上有一个音符的小图案。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写错一个音符，整首歌就不好听了。", "target_word": "音符", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "表示音乐声音高低的符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71661477-2f15-4858-bb22-282f8f8aa695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音符", "is_correct": true, "explanation": "正确。音符标示音高，线上位置越高，音高就越高。"}, {"text": "水位", "is_correct": false, "explanation": "语义：水位指水面的高度，与乐谱上线的位置无关，句意不通。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温与声音的高低没有关系，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的外形特征，不会决定声音的高低，句意不通。"}], "explanations": {"音符": "正确。音符标示音高，线上位置越高，音高就越高。", "水位": "语义：水位指水面的高度，与乐谱上线的位置无关，句意不通。", "气温": "语义：气温与声音的高低没有关系，句意不通。", "身高": "体貌：身高是人的外形特征，不会决定声音的高低，句意不通。"}, "sentence_index": 0, "correct_answer": "音符"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章里的每个音符我都认识。", "explanation": "这里应该用〈字〉。音符是表示音乐声音高低的符号，文章里写的是字，不是音符。"}, {"text": "这句话的最后要加一个音符。", "explanation": "这里应该用〈标点符号〉。音符只用于乐谱，句子末尾要加的是标点符号。"}, {"text": "地图上的这个音符表示学校。", "explanation": "这里应该用〈符号〉。音符只表示音乐声音的高低，地图上表示地点的是符号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音符", "is_correct": true, "explanation": "正确。这里指屏幕上跳出的乐谱符号，符合句意。"}, {"text": "音节", "is_correct": false, "explanation": "搭配：“跳出”的对象一般是图像、图标，不说“跳出一个音节”。"}, {"text": "叹息", "is_correct": false, "explanation": "语义：叹息是叹气的声音或情绪，不是屏幕上能跳出的东西，句意不通。"}, {"text": "道理", "is_correct": false, "explanation": "语义：道理是抽象的想法，不是屏幕上会跳出的东西，句意不通。"}], "explanations": {"音符": "正确。这里指屏幕上跳出的乐谱符号，符合句意。", "音节": "搭配：“跳出”的对象一般是图像、图标，不说“跳出一个音节”。", "叹息": "语义：叹息是叹气的声音或情绪，不是屏幕上能跳出的东西，句意不通。", "道理": "语义：道理是抽象的想法，不是屏幕上会跳出的东西，句意不通。"}, "sentence_index": 6, "correct_answer": "音符"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个单词的音符写错了，读音就不对。", "explanation": "这里应该用〈音标〉。音符指乐谱上的符号，单词的读音标记要用音标。"}, {"text": "这个词有三个音符，你数对了吗？", "explanation": "这里应该用〈音节〉。音符指乐谱上的符号，数词的音数要用音节。"}, {"text": "汉语有四个音符。", "explanation": "这里应该用〈声调〉。音符是乐谱上的符号，汉语的音高变化要用声调表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在乐谱上找到了一张音符。", "corrected_sentence": "他在乐谱上找到了一个音符。", "error_description": "量词错误：“音符”应用量词“个”。“张”用于纸张、平面物，不能用于音符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这个音符写很清楚。", "corrected_sentence": "他把这个音符写得很清楚。", "error_description": "补语错误：状态补语前要加“得”，应说“写得很清楚”，不能说“写很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70728649-76e3-4aae-af94-5c6451df50b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21880, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "差", "is_correct": true, "explanation": "反义：“好”与“差”相对，表示玩得不令人满意。"}, {"text": "大", "is_correct": false, "explanation": "无关：“大”表示大小，与“好”没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "无关：“慢”表示速度，与“好”没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "无关：“厚”表示厚度，与“好”没有反义关系。"}], "correct_answer": "差", "explanations": {"差": "反义：“好”与“差”相对，表示玩得不令人满意。", "大": "无关：“大”表示大小，与“好”没有反义关系。", "慢": "无关：“慢”表示速度，与“好”没有反义关系。", "厚": "无关：“厚”表示厚度，与“好”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21880, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "差", "is_correct": true, "explanation": "反义：“好”与“差”相对，表示聚会的状况不令人满意。"}, {"text": "高", "is_correct": false, "explanation": "无关：“高”表示高度，与“好”没有反义关系。"}, {"text": "远", "is_correct": false, "explanation": "无关：“远”表示距离，与“好”没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "无关：“轻”表示重量，与“好”没有反义关系。"}], "correct_answer": "差", "explanations": {"差": "反义：“好”与“差”相对，表示聚会的状况不令人满意。", "高": "无关：“高”表示高度，与“好”没有反义关系。", "远": "无关：“远”表示距离，与“好”没有反义关系。", "轻": "无关：“轻”表示重量，与“好”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21880, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示非常好，让人开心。", "primary_collocate": null, "pronunciation": "hěn hǎo", "ipa": "xən˧˥ xɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "今天我心情很好。", "target_word": "很好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个消息很好，大家都很高兴。", "target_word": "很好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个礼物很好，我很喜欢。", "target_word": "很好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们玩得很好，谢谢你。", "target_word": "很好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试成绩很好，爸爸笑了。", "target_word": "很好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行过得很好，孩子们都很开心。", "target_word": "很好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天能见到你，真的很好，我特别开心。", "target_word": "很好", "complexity_tier": "T3", "furigana": "jīntiān néng jiàndào nǐ, zhēn de hěn hǎo, wǒ tèbié kāixīn.", "sentence_source": "generated"}, {"text": "“你今天怎么样？”“很好，谢谢！”", "target_word": "很好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个想法很好，我们马上试试。", "target_word": "很好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末的聚会很好，大家玩得很开心。", "target_word": "很好", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "好", "label": "基本形式"}, {"form": "更好", "label": "比较形式"}, {"form": "最好", "label": "最高级"}], "register": "口语", "sense_fingerprint": "很好：非常好，让人开心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a269e1a5-c59d-4121-a4c6-6e6ac15ab5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很好", "is_correct": true, "explanation": "正确：“今天我心情很好”表示心情愉快，句意通顺。"}, {"text": "很多", "is_correct": false, "explanation": "搭配：“心情”不与“很多”搭配，句意不通。"}, {"text": "很慢", "is_correct": false, "explanation": "搭配：心情不用“慢”来形容，句意不通。"}, {"text": "很大", "is_correct": false, "explanation": "语义：心情的状态不用大小来描述，句意不通。"}], "explanations": {"很好": "正确：“今天我心情很好”表示心情愉快，句意通顺。", "很多": "搭配：“心情”不与“很多”搭配，句意不通。", "很慢": "搭配：心情不用“慢”来形容，句意不通。", "很大": "语义：心情的状态不用大小来描述，句意不通。"}, "sentence_index": 0, "correct_answer": "很好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座楼很好找，就在火车站旁边。", "explanation": "这里的“很好”表示“容易”（如“好找”），不是“非常好”的意思。"}, {"text": "这辆车很好开，新手也能很快上手。", "explanation": "这里的“很好”表示“容易”（如“好开”），不是“非常好”的意思。"}, {"text": "这块布很好洗，用手搓一下就干净了。", "explanation": "这里的“很好”表示“容易”（如“好洗”），不是“非常好”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很好", "is_correct": true, "explanation": "正确：“真的很好，我特别开心”表示对见到你这件事的满意，句意通顺。"}, {"text": "很远", "is_correct": false, "explanation": "语义：“很远”表示距离，与“能见到你”的喜悦无关，句意不通。"}, {"text": "很贵", "is_correct": false, "explanation": "语义：“很贵”与前文“能见到你”的喜悦冲突，句意不通。"}, {"text": "很晚", "is_correct": false, "explanation": "语义：“很晚”表示时间，与见到你的喜悦无关，句意不通。"}], "explanations": {"很好": "正确：“真的很好，我特别开心”表示对见到你这件事的满意，句意通顺。", "很远": "语义：“很远”表示距离，与“能见到你”的喜悦无关，句意不通。", "很贵": "语义：“很贵”与前文“能见到你”的喜悦冲突，句意不通。", "很晚": "语义：“很晚”表示时间，与见到你的喜悦无关，句意不通。"}, "sentence_index": 6, "correct_answer": "很好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子很好搬，一个人就能抬起来。", "explanation": "这里的“很好”表示“容易”（如“好搬”），不是“非常好”的意思。"}, {"text": "这碗面很好煮，五分钟就好了。", "explanation": "这里的“很好”表示“容易”（如“好煮”），不是“非常好”的意思。"}, {"text": "这台电脑很好修，零件都容易买到。", "explanation": "这里的“很好”表示“容易”（如“好修”），不是“非常好”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次聚会好很，大家都很开心。", "corrected_sentence": "这次聚会很好，大家都很开心。", "error_description": "错误：副词“很”应放在“好”前，“好很”语序错误，正确形式为“很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次周末的郊游玩很得好，孩子们都很开心。", "corrected_sentence": "这次周末的郊游玩得很好，孩子们都很开心。", "error_description": "错误：补语标记“得”应紧跟动词“玩”，再接“很好”，正确形式为“玩得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74ace45c-3452-4966-b173-52fdea0e5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
