INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21882, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从开始到结束都没有停止，动作或状态不间断。", "primary_collocate": null, "pronunciation": "yì zhí", "ipa": "i˥˩ tʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "他一直在家。", "target_word": "一直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我一直喜欢这个城市。", "target_word": "一直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨一直下到晚上。", "target_word": "一直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "从早上到现在，她一直在看书。", "target_word": "一直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天一直很忙。", "target_word": "一直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从小一直住在北京。", "target_word": "一直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天我一直在等你的电话。", "target_word": "一直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子一直哭，妈妈很着急。", "target_word": "一直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师一直说，学习要有耐心。", "target_word": "一直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机一直响，他没有接。", "target_word": "一直", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一直以来", "label": "复合"}], "register": "中性", "sense_fingerprint": "表示动作或状态在一段时间里不间断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e886baf2-6b8e-4ba4-b9ee-b0c12fe6a1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21882, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一直", "is_correct": true, "explanation": "正确：一直（yì zhí），副词，表示动作或状态不间断。"}, {"text": "移植", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，“移植”指把植物或器官从一处移到另一处，意思不符。"}, {"text": "医治", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）、zhì（第四声）与 zhí（第二声）声调都不同，“医治”指治疗疾病，意思不符。"}, {"text": "一只", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，“一只”是数量短语，指一个动物或成对物品中的一个，意思不符。"}], "explanations": {"一直": "正确：一直（yì zhí），副词，表示动作或状态不间断。", "移植": "yí（第二声）与 yì（第四声）声调不同，“移植”指把植物或器官从一处移到另一处，意思不符。", "医治": "yī（第一声）与 yì（第四声）、zhì（第四声）与 zhí（第二声）声调都不同，“医治”指治疗疾病，意思不符。", "一只": "zhī（第一声）与 zhí（第二声）声调不同，“一只”是数量短语，指一个动物或成对物品中的一个，意思不符。"}, "sentence_index": null, "correct_answer": "一直"}, "level_3": {"options": [{"text": "一直", "is_correct": true, "explanation": "正确：“一直”表示状态持续不断，与“在家”搭配，符合句意。"}, {"text": "赶快", "is_correct": false, "explanation": "语义：“赶快”表示催促尽快行动，与“在家”这种静态状态相冲突。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”强调即时发生的动作，与“在家”这种持续状态不相符。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”修饰需要人主动完成的动作，不能用来修饰“在家”。"}], "explanations": {"一直": "正确：“一直”表示状态持续不断，与“在家”搭配，符合句意。", "赶快": "语义：“赶快”表示催促尽快行动，与“在家”这种静态状态相冲突。", "立刻": "语义：“立刻”强调即时发生的动作，与“在家”这种持续状态不相符。", "亲自": "搭配：“亲自”修饰需要人主动完成的动作，不能用来修饰“在家”。"}, "sentence_index": 0, "correct_answer": "一直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到消息，他一直出发了。", "explanation": "这里应该用〈立刻〉。立刻表示马上行动，“出发”是一次性动作，一直强调不间断地进行，不能修饰一次性的动作。"}, {"text": "我们每周都一直去公园散步。", "explanation": "这里应该用〈经常〉。经常表示多次重复，一直表示不间断，句中“每周”说明是间隔重复，不能用“一直”。"}, {"text": "他一直在三秒内跑完了一百米。", "explanation": "这里应该用〈很快〉。一直强调时间长、不间断，三秒钟内完成的动作不能用“一直”；说明动作快应用“很快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21882, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一直", "is_correct": true, "explanation": "正确：一直（yì zhí），副词，表示动作或状态不间断。"}, {"text": "一致", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，“一致”指相同、不矛盾，意思不符。"}, {"text": "以至", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）、zhì（第四声）与 zhí（第二声）声调都不同，“以至”是连词，表示结果，意思不符。"}, {"text": "遗志", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）、zhì（第四声）与 zhí（第二声）声调都不同，“遗志”指死者留下的志愿，意思不符。"}], "explanations": {"一直": "正确：一直（yì zhí），副词，表示动作或状态不间断。", "一致": "zhì（第四声）与 zhí（第二声）声调不同，“一致”指相同、不矛盾，意思不符。", "以至": "yǐ（第三声）与 yì（第四声）、zhì（第四声）与 zhí（第二声）声调都不同，“以至”是连词，表示结果，意思不符。", "遗志": "yí（第二声）与 yì（第四声）、zhì（第四声）与 zhí（第二声）声调都不同，“遗志”指死者留下的志愿，意思不符。"}, "sentence_index": null, "correct_answer": "一直"}, "level_3": {"options": [{"text": "一直", "is_correct": true, "explanation": "正确：“一直”表示动作持续不断，与“昨天……在等”形成过去持续的语境。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即发生，与句中“昨天”的过去时间冲突。"}, {"text": "将要", "is_correct": false, "explanation": "语义：“将要”表示将来，与句中“昨天”的过去时间冲突。"}, {"text": "连忙", "is_correct": false, "explanation": "搭配：“连忙”表示急忙去做某事，与“等你的电话”这种持续的等待不搭配。"}], "explanations": {"一直": "正确：“一直”表示动作持续不断，与“昨天……在等”形成过去持续的语境。", "马上": "语义：“马上”表示立即发生，与句中“昨天”的过去时间冲突。", "将要": "语义：“将要”表示将来，与句中“昨天”的过去时间冲突。", "连忙": "搭配：“连忙”表示急忙去做某事，与“等你的电话”这种持续的等待不搭配。"}, "sentence_index": 6, "correct_answer": "一直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直说了一句话就走了。", "explanation": "这里应该用〈只〉。一直表示不间断地进行，“说了一句话”是短暂的一次行为，不能用“一直”修饰；表示数量少应说“只”。"}, {"text": "他一直来看我一次。", "explanation": "这里应该用〈偶尔〉。一直表示持续不断，“来看我一次”是偶发的一次性行为，两者矛盾。"}, {"text": "经过三年努力，他一直考上了大学。", "explanation": "这里应该用〈终于〉。一直表示持续过程，“考上大学”是结果性的一次完成，不能用“一直”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直的忙，没有时间休息。", "corrected_sentence": "他一直很忙，没有时间休息。", "error_description": "错误：“一直的忙”。副词“一直”后不能直接加“的”来修饰形容词“忙”，应把“的”改为“很”，说“一直很忙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天的雨一直了下个不停，路上很滑。", "corrected_sentence": "今天的雨一直下个不停，路上很滑。", "error_description": "错误：“一直了下个不停”。“了”不能直接加在副词“一直”之后，应去掉，说“一直下个不停”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
