INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21884, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时间就是白天和晚上，还有上午、下午、昨天、今天、明天。", "primary_collocate": null, "pronunciation": "shí jiān", "ipa": "ʂɻ̩˧˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "我今天没有时间，明天再说吧。", "target_word": "时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间过得真快，一年又过去了。", "target_word": "时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每天花多少时间学中文？", "target_word": "时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了很长时间，还没有人来。", "target_word": "时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的时间是明天上午九点。", "target_word": "时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你八点以前到，不要浪费时间。", "target_word": "时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一点空闲时间，可以帮你。", "target_word": "时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做作业花了很长时间。", "target_word": "时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间太晚了，我们回家吧。", "target_word": "时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天花很多时间在手机上。", "target_word": "时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段时间", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，指时间本身、一段时间或某个具体的时刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b19119-d89a-436b-a0df-53ddddc827e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21884, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时间", "is_correct": true, "explanation": "正确：听到的是“时间”shíjiān，指时长或某个时刻。"}, {"text": "实践", "is_correct": false, "explanation": "实践 shíjiàn 与 时间 shíjiān 第二音节声调不同（jiàn 第四声，jiān 第一声），意思是实践。"}, {"text": "事件", "is_correct": false, "explanation": "事件 shìjiàn 与 时间 shíjiān 两个音节的声调都不同，意思是事件。"}, {"text": "世间", "is_correct": false, "explanation": "世间 shìjiān 与 时间 shíjiān 第一音节声调不同（shì 第四声，shí 第二声），意思是人世间。"}], "explanations": {"时间": "正确：听到的是“时间”shíjiān，指时长或某个时刻。", "实践": "实践 shíjiàn 与 时间 shíjiān 第二音节声调不同（jiàn 第四声，jiān 第一声），意思是实践。", "事件": "事件 shìjiàn 与 时间 shíjiān 两个音节的声调都不同，意思是事件。", "世间": "世间 shìjiān 与 时间 shíjiān 第一音节声调不同（shì 第四声，shí 第二声），意思是人世间。"}, "sentence_index": null, "correct_answer": "时间"}, "level_3": {"options": [{"text": "时间", "is_correct": true, "explanation": "正确：“没有时间”指没有空闲，符合句意；“时间”指时长或时刻。"}, {"text": "时代", "is_correct": false, "explanation": "语义：“时代”指较长的历史阶段，“今天没有时代”说不通。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”指春夏秋冬等时令，“今天没有季节”句意不通。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“没有”后面不接“星期”，“星期”是固定的计时单位。"}], "explanations": {"时间": "正确：“没有时间”指没有空闲，符合句意；“时间”指时长或时刻。", "时代": "语义：“时代”指较长的历史阶段，“今天没有时代”说不通。", "季节": "语义：“季节”指春夏秋冬等时令，“今天没有季节”句意不通。", "星期": "搭配：“没有”后面不接“星期”，“星期”是固定的计时单位。"}, "sentence_index": 0, "correct_answer": "时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的时间已经五十岁了。", "explanation": "这里应该用〈年龄〉。说人的岁数要用“年龄”，“时间”不指一个人的年岁。"}, {"text": "这间屋子的时间很大，可以放很多床。", "explanation": "这里应该用〈空间〉。形容房间的大小用“空间”，“时间”指时长或时刻，不指空间大小。"}, {"text": "这座山的时间有三千米高。", "explanation": "这里应该用〈高度〉。说山有多高用“高度”，“时间”不指高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间", "is_correct": true, "explanation": "正确：“空闲时间”指不忙的时段，与“可以帮你”呼应。"}, {"text": "工作", "is_correct": false, "explanation": "搭配：“空闲”修饰时间或人，不修饰“工作”，要说“空闲时间”。"}, {"text": "力气", "is_correct": false, "explanation": "语义：“空闲”形容时间或人，不能修饰“力气”，“有一点空闲力气”句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能被“空闲”修饰，“有一点空闲天气”句意不通。"}], "explanations": {"时间": "正确：“空闲时间”指不忙的时段，与“可以帮你”呼应。", "工作": "搭配：“空闲”修饰时间或人，不修饰“工作”，要说“空闲时间”。", "力气": "语义：“空闲”形容时间或人，不能修饰“力气”，“有一点空闲力气”句意不通。", "天气": "语义：“天气”不能被“空闲”修饰，“有一点空闲天气”句意不通。"}, "sentence_index": 6, "correct_answer": "时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他生活在唐朝时间，那时候交通很不方便。", "explanation": "这里应该用〈时代〉。“唐朝时代”指朝代所属的历史时期，“时间”不用来指朝代。"}, {"text": "这块石头的时间有五公斤重。", "explanation": "这里应该用〈重量〉。说东西有多重用“重量”，“时间”不指轻重。"}, {"text": "作业的时间有五道题。", "explanation": "这里应该用〈题目〉。作业的内容用“题目”计算数量，“时间”指时长或时刻，不指题的数目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天都要花一个时间练习口语。", "corrected_sentence": "我每天都要花一段时间练习口语。", "error_description": "错误：“一个时间”；正确：“一段时间”。表示一段时长的“时间”用量词“段”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天花很多时间学习上。", "corrected_sentence": "我每天花很多时间在学习上。", "error_description": "错误：“花很多时间学习上”；正确：“花很多时间在学习上”。“花……时间”后接处所时要用“在”引出，缺少“在”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
