INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "线是细细长长的东西。", "primary_collocate": null, "pronunciation": "xiàn", "ipa": "ɕjɛn⁵¹", "syllable_count": 1, "sentences": [{"text": "我的衣服上有一根线。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这根线很长，也很细。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶用针和线补衣服。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小猫在玩一团线。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他剪断了手里的线。", "target_word": "线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请帮我把线穿进针里。", "target_word": "线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风筝飞得很高，线也很长。", "target_word": "线", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上放着一卷线。", "target_word": "线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线是用棉做的。", "target_word": "线", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "线太细了，我看不清楚。", "target_word": "线", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "团", "label": "量词"}, {"form": "線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "缝纫等用的细长的线状物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3d1bcd0-f1dc-4fc5-90a2-e7b31f28406a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21886, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "线", "is_correct": true, "explanation": "线 xiàn，指细细长长的线状物，正确。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先后的“先”。"}, {"text": "显", "is_correct": false, "explanation": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是“显示”。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j 与 x），意思是“看见”。"}, {"text": "向", "is_correct": false, "explanation": "xiàng 与 xiàn 韵母不同（-iang 与 -ian），意思是“方向”。"}], "explanations": {"线": "线 xiàn，指细细长长的线状物，正确。", "先": "xiān（第一声）与 xiàn（第四声）声调不同，意思是先后的“先”。", "显": "xiǎn（第三声）与 xiàn（第四声）声调不同，意思是“显示”。", "见": "jiàn 与 xiàn 声母不同（j 与 x），意思是“看见”。", "向": "xiàng 与 xiàn 韵母不同（-iang 与 -ian），意思是“方向”。"}, "sentence_index": null, "correct_answer": "线"}, "level_3": {"options": [{"text": "线", "is_correct": true, "explanation": "正确。“一根线”指细长的线，符合句意。"}, {"text": "扣子", "is_correct": false, "explanation": "搭配：“扣子”的量词是“颗”，不说“一根扣子”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不会挂在衣服上，与“衣服上有”的句意不合。"}, {"text": "纸", "is_correct": false, "explanation": "搭配：“纸”的量词是“张”，不说“一根纸”。"}], "explanations": {"线": "正确。“一根线”指细长的线，符合句意。", "扣子": "搭配：“扣子”的量词是“颗”，不说“一根扣子”。", "太阳": "语义：太阳不会挂在衣服上，与“衣服上有”的句意不合。", "纸": "搭配：“纸”的量词是“张”，不说“一根纸”。"}, "sentence_index": 0, "correct_answer": "线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条地铁线每天都很挤。", "explanation": "这里的线指地铁路线，是另一个意思，不是“细细长长的东西”。"}, {"text": "姐姐买了一只线。", "explanation": "量词用错。「只」多用于动物、手等具体事物，线不用「只」。"}, {"text": "孩子们在操场上跳线。", "explanation": "这里应该用〈绳〉。跳的是绳，线太细，不能说“跳线”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be055fc7-0628-401d-ace4-2535433ba156') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21886, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "线", "is_correct": true, "explanation": "线 xiàn，指细细长长的线状物，正确。"}, {"text": "闲", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是“空闲”。"}, {"text": "咸", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，意思是“咸味”。"}, {"text": "鲜", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，意思是“新鲜”。"}, {"text": "建", "is_correct": false, "explanation": "jiàn 与 xiàn 声母不同（j 与 x），意思是“建设”。"}], "explanations": {"线": "线 xiàn，指细细长长的线状物，正确。", "闲": "xián（第二声）与 xiàn（第四声）声调不同，意思是“空闲”。", "咸": "xián（第二声）与 xiàn（第四声）声调不同，意思是“咸味”。", "鲜": "xiān（第一声）与 xiàn（第四声）声调不同，意思是“新鲜”。", "建": "jiàn 与 xiàn 声母不同（j 与 x），意思是“建设”。"}, "sentence_index": null, "correct_answer": "线"}, "level_3": {"options": [{"text": "线", "is_correct": true, "explanation": "正确。风筝上的线随风筝升高而拉长，符合句意。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不是风筝上的连接物，与“风筝飞得很高”无关。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：形容眼睛不说“很长”，与句子搭配不通。"}, {"text": "纽扣", "is_correct": false, "explanation": "语义：纽扣很小，说不上“很长”，无法与风筝线并列。"}], "explanations": {"线": "正确。风筝上的线随风筝升高而拉长，符合句意。", "树": "语义：树不是风筝上的连接物，与“风筝飞得很高”无关。", "眼睛": "搭配：形容眼睛不说“很长”，与句子搭配不通。", "纽扣": "语义：纽扣很小，说不上“很长”，无法与风筝线并列。"}, "sentence_index": 6, "correct_answer": "线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她腰间系着一条很宽的线。", "explanation": "这里应该用〈带子〉。线是细细长长的，不能说“很宽的线”；系在腰间的宽东西叫“带子”。"}, {"text": "拔河比赛用的线很结实。", "explanation": "这里应该用〈绳〉。拔河要用粗绳，线太细，不能用来拔河。"}, {"text": "奶奶买了一头线。", "explanation": "量词用错。“头”用于牛、猪等大型牲畜，线不用“头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be055fc7-0628-401d-ace4-2535433ba156') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "抽屉里有一个线，颜色是白的。", "corrected_sentence": "抽屉里有一团线，颜色是白的。", "error_description": "错误：“线”的量词用错。“个”不能用于线，应改为“团”（或“根”“卷”）。改为“一团线”即正确。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be055fc7-0628-401d-ace4-2535433ba156') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从抽屉里拿出了一根的线。", "corrected_sentence": "他从抽屉里拿出了一根线。", "error_description": "错误：数量短语后多加了“的”。“一根”后直接接名词，应说“一根线”，不说“一根的线”；原因：“一根线”已是完整的数量名结构，无需“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be055fc7-0628-401d-ace4-2535433ba156') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21888, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旧", "is_correct": true, "explanation": "“旧”与“新”是反义词，指用过或存在久的。"}, {"text": "远", "is_correct": false, "explanation": "“远”指距离大，与“新”没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "“快”指速度高，与“新”不构成反义。"}, {"text": "白", "is_correct": false, "explanation": "“白”指颜色，与“新”不构成反义。"}], "correct_answer": "旧", "explanations": {"旧": "“旧”与“新”是反义词，指用过或存在久的。", "远": "“远”指距离大，与“新”没有反义关系。", "快": "“快”指速度高，与“新”不构成反义。", "白": "“白”指颜色，与“新”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21888, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旧", "is_correct": true, "explanation": "“旧”与“新”是反义词，指用过或存在久的。"}, {"text": "大", "is_correct": false, "explanation": "“大”指体积或范围大，与“新”不构成反义。"}, {"text": "冷", "is_correct": false, "explanation": "“冷”指温度低，与“新”没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "“高”指高度大，与“新”不构成反义。"}], "correct_answer": "旧", "explanations": {"旧": "“旧”与“新”是反义词，指用过或存在久的。", "大": "“大”指体积或范围大，与“新”不构成反义。", "冷": "“冷”指温度低，与“新”没有反义关系。", "高": "“高”指高度大，与“新”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21888, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "新的东西是刚刚出现或者没用过的。", "primary_collocate": null, "pronunciation": "xīn", "ipa": "ɕin˥", "syllable_count": 1, "sentences": [{"text": "我昨天买了一个新书包。", "target_word": "新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是新的，我还没穿过。", "target_word": "新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车是新的，还没人开过。", "target_word": "新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子刚盖好，墙都是新的。", "target_word": "新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是新的，还没人借过。", "target_word": "新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新鞋穿着有点紧。", "target_word": "新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里换了新桌子，旧桌子都搬走了。", "target_word": "新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用新杯子喝了一杯水。", "target_word": "新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西都很新，没有人用过。", "target_word": "新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧电脑坏了，爸爸给我买了新的。", "target_word": "新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "刚出现的、没有用过的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec4c1b08-8b6c-49e8-8306-b34cf5a1cd34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21888, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新", "is_correct": true, "explanation": "新 xīn（第一声），意思是刚出现或没用过的。"}, {"text": "星", "is_correct": false, "explanation": "xīng 与 xīn 韵母不同（-ing / -in），意思是星星。"}, {"text": "信", "is_correct": false, "explanation": "xìn 与 xīn 声调不同（第四声 / 第一声），意思是信件。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 xīn 声母不同（j / x），意思是金子。"}, {"text": "亲", "is_correct": false, "explanation": "qīn 与 xīn 声母不同（q / x），意思是亲人。"}], "explanations": {"新": "新 xīn（第一声），意思是刚出现或没用过的。", "星": "xīng 与 xīn 韵母不同（-ing / -in），意思是星星。", "信": "xìn 与 xīn 声调不同（第四声 / 第一声），意思是信件。", "金": "jīn 与 xīn 声母不同（j / x），意思是金子。", "亲": "qīn 与 xīn 声母不同（q / x），意思是亲人。"}, "sentence_index": null, "correct_answer": "新"}, "level_3": {"options": [{"text": "新", "is_correct": true, "explanation": "新是形容词，表示刚买的、没用过，修饰“书包”，符合句意。"}, {"text": "破", "is_correct": false, "explanation": "语义：昨天刚买的书包不会是破的，与“昨天买”矛盾。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：刚买的东西一般不说“脏”，与句中的“买”搭配不当。"}, {"text": "老", "is_correct": false, "explanation": "语义：“老”说的是存在时间长，与“昨天买”矛盾。"}], "explanations": {"新": "新是形容词，表示刚买的、没用过，修饰“书包”，符合句意。", "破": "语义：昨天刚买的书包不会是破的，与“昨天买”矛盾。", "脏": "搭配：刚买的东西一般不说“脏”，与句中的“买”搭配不当。", "老": "语义：“老”说的是存在时间长，与“昨天买”矛盾。"}, "sentence_index": 0, "correct_answer": "新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山里的空气很新，呼吸起来很舒服。", "explanation": "这里应该用〈新鲜〉。形容空气清爽要说“新鲜”；“新”指没用过或刚出现的东西，不能用来形容空气。"}, {"text": "我新吃了一碗面，还是很饿。", "explanation": "这里应该用〈刚〉。表示不久前做完某事要用“刚”，“新”不能用来修饰“吃”这样的动作。"}, {"text": "我每天早上都看新，了解外面的事。", "explanation": "这里应该用〈新闻〉。了解外面的事要看“新闻”，“新”单用不能指新闻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21888, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "新", "is_correct": true, "explanation": "新 xīn（第一声），意思是刚出现或没用过的。"}, {"text": "兴", "is_correct": false, "explanation": "xīng（第一声）与 xīn 韵尾不同（-ng / -n），仅一处差别，意思是兴起、高兴。"}, {"text": "先", "is_correct": false, "explanation": "xiān（第一声）与 xīn 韵母不同（-ian / -in），仅差一个元音，意思是先后、首先。"}, {"text": "宾", "is_correct": false, "explanation": "bīn（第一声）与 xīn 声母不同（b / x），声调相同，意思是宾客。"}], "explanations": {"新": "新 xīn（第一声），意思是刚出现或没用过的。", "兴": "xīng（第一声）与 xīn 韵尾不同（-ng / -n），仅一处差别，意思是兴起、高兴。", "先": "xiān（第一声）与 xīn 韵母不同（-ian / -in），仅差一个元音，意思是先后、首先。", "宾": "bīn（第一声）与 xīn 声母不同（b / x），声调相同，意思是宾客。"}, "sentence_index": null, "correct_answer": "新"}, "level_3": {"options": [{"text": "新", "is_correct": true, "explanation": "“新”指刚换来的、没用过的桌子，与“旧桌子都搬走了”形成对比，符合句意。"}, {"text": "旧", "is_correct": false, "explanation": "语义：句中说“旧桌子都搬走了”，换上的桌子不能也是旧的，前后矛盾。"}, {"text": "湿", "is_correct": false, "explanation": "语义：换来的桌子是湿的，不是常见的换新情况，与句意不通。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”形容人，不说年轻的桌子。"}], "explanations": {"新": "“新”指刚换来的、没用过的桌子，与“旧桌子都搬走了”形成对比，符合句意。", "旧": "语义：句中说“旧桌子都搬走了”，换上的桌子不能也是旧的，前后矛盾。", "湿": "语义：换来的桌子是湿的，不是常见的换新情况，与句意不通。", "年轻": "搭配：“年轻”形容人，不说年轻的桌子。"}, "sentence_index": 6, "correct_answer": "新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每周新一次软件，效果很好。", "explanation": "这里应该用〈更新〉。“更新”是动词，可以带“软件”这样的宾语；“新”是形容词，不能当动词用。"}, {"text": "这是我新坐飞机，很兴奋。", "explanation": "这里应该用〈第一次〉。表示“头一回”要用“第一次”，“新”不能修饰“坐”这样的动作。"}, {"text": "他比我新一岁，我们是同学。", "explanation": "这里应该用〈小〉。说年龄的大小要用“小”或“大”，“新”不表示年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我换了一个的新手机。", "corrected_sentence": "我换了一个新手机。", "error_description": "错误：“的”用错了位置。数量词“一个”后直接接形容词“新”修饰名词，不加“的”，应为“一个新手机”，不能说“一个的新手机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给我买了一双鞋新。", "corrected_sentence": "妈妈给我买了一双新鞋。", "error_description": "语序错误：形容词“新”修饰名词要放在名词前，“鞋新”只能作谓语，应说“新鞋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25846df6-73b7-41b6-b809-7041c1f55e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
