INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "记住事情的方法。", "primary_collocate": null, "pronunciation": "jì fǎ", "ipa": "tɕi˥˩ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "你有什么好记法，能记住这么多名字？", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的记法很特别，会把数字编成故事。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我一种记路的记法。", "target_word": "记法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个记法太难了，我还是用笔记下来吧。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学一个记生日的好记法。", "target_word": "记法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟的记法是编成歌曲，很快背会了乘法表。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每种记法都有好处，要看哪种适合你。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的记法是每天写一遍，所以不会忘。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人有自己的记法，用绳子打结来记事。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好记法能让你少花时间，多记东西。", "target_word": "记法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "記法", "label": "繁体"}], "register": "中性", "sense_fingerprint": "记住名字、数字、事情的具体做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c37cae-b219-4aee-bb4e-93cb237f46fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21892, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "记法", "is_correct": true, "explanation": "正确。记法读作 jì fǎ，意思是记住事情的方法。"}, {"text": "戏法", "is_correct": false, "explanation": "xì 与 jì 的声母不同（x 与 j），声调相同，意思是戏法（变魔术）。"}, {"text": "寄发", "is_correct": false, "explanation": "fā（第一声）与 fǎ（第三声）声调不同，意思是寄出。"}, {"text": "继发", "is_correct": false, "explanation": "fā（第一声）与 fǎ（第三声）声调不同，意思是继而发生。"}], "explanations": {"记法": "正确。记法读作 jì fǎ，意思是记住事情的方法。", "戏法": "xì 与 jì 的声母不同（x 与 j），声调相同，意思是戏法（变魔术）。", "寄发": "fā（第一声）与 fǎ（第三声）声调不同，意思是寄出。", "继发": "fā（第一声）与 fǎ（第三声）声调不同，意思是继而发生。"}, "sentence_index": null, "correct_answer": "记法"}, "level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "语义：“饼干”是食品，与记住名字的方法无关，句意不通。"}, {"text": "记法", "is_correct": true, "explanation": "正确。“你有什么好记法，能记住这么多名字”问的是记忆方法。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”是穿着用品，与记住名字没有关系。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能与“能记住这么多名字”搭配，语义不通。"}], "explanations": {"饼干": "语义：“饼干”是食品，与记住名字的方法无关，句意不通。", "记法": "正确。“你有什么好记法，能记住这么多名字”问的是记忆方法。", "鞋子": "语义：“鞋子”是穿着用品，与记住名字没有关系。", "天气": "搭配：“天气”不能与“能记住这么多名字”搭配，语义不通。"}, "sentence_index": 0, "correct_answer": "记法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师教了我们一只记法。", "explanation": "这里应该用〈种〉。“只”用于动物等，不用于记法。"}, {"text": "这个箱子的记法很轻。", "explanation": "这里应该用〈重量〉。记法指记住事情的方法，箱子的轻重与记法无关，应说箱子的重量。"}, {"text": "我把记法放进了冰箱。", "explanation": "这里把〈记法〉当作可以放进冰箱的实物，记法指记住事情的方法，是抽象的，不能放进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”是时间词，不能说“每种昨天”，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是可以分类、各有好处的记忆方式，不能用在这里。"}, {"text": "记法", "is_correct": true, "explanation": "正确。“每种记法都有好处，要看哪种适合你”指各种记忆方法各有优点。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不能用“每种……都有好处”来说，不能与“记法”的语境搭配。"}], "explanations": {"昨天": "语义：“昨天”是时间词，不能说“每种昨天”，句意不通。", "天空": "语义：“天空”不是可以分类、各有好处的记忆方式，不能用在这里。", "记法": "正确。“每种记法都有好处，要看哪种适合你”指各种记忆方法各有优点。", "脚步": "搭配：“脚步”不能用“每种……都有好处”来说，不能与“记法”的语境搭配。"}, "sentence_index": 6, "correct_answer": "记法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我讲了一颗记法。", "explanation": "这里应该用〈种〉。“颗”用于颗粒状的东西，不能用于记法。"}, {"text": "这幅画的记法很鲜艳。", "explanation": "这里应该用〈颜色〉。记法指记住事情的方法，不能用“鲜艳”形容。"}, {"text": "他在厨房里煮了记法。", "explanation": "这里把〈记法〉当作可以煮的食物或材料，记法指记住事情的方法，不能用来烹煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想出了一首记电话号码的新记法。", "corrected_sentence": "他想出了一种记电话号码的新记法。", "error_description": "量词错误：“记法”应用“种”计量，“首”只用于诗、歌等，不能用于记法，应说“一种新记法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我记法是每天背十个单词。", "corrected_sentence": "我的记法是每天背十个单词。", "error_description": "漏掉“的”：“我”修饰“记法”时要用“的”，应说“我的记法”，不能说“我记法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
