INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "麻烦", "is_correct": true, "explanation": "“麻烦”与“方便”相对，指做事费事、不省力。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”与“方便”没有反义关系，指人的智力高。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指没有污物，与“方便”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”指心情愉快，与“方便”没有反义关系。"}], "correct_answer": "麻烦", "explanations": {"麻烦": "“麻烦”与“方便”相对，指做事费事、不省力。", "聪明": "“聪明”与“方便”没有反义关系，指人的智力高。", "干净": "“干净”指没有污物，与“方便”没有反义关系。", "高兴": "“高兴”指心情愉快，与“方便”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情很容易，不麻烦。", "primary_collocate": null, "pronunciation": "fāng biàn", "ipa": "faŋ˥ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "住在地铁站旁边很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机用起来很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市二十四小时开门，很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近有超市，买菜很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐出租车去机场比较方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不太方便，我们走那条吧。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机付钱真方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小包带着很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校离家近，上学很方便。", "target_word": "方便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做事省力省事，条件合适，不麻烦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d81d48-6f38-42b1-91d4-5cab678d6582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方便", "is_correct": true, "explanation": "“方便”形容住的地方交通便利、省事，与“地铁站旁边”相符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来说住的地方。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写人或动物的体形，不能用来形容位置。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”是人的情绪，不能用来形容住在某处的情况。"}], "explanations": {"方便": "“方便”形容住的地方交通便利、省事，与“地铁站旁边”相符。", "聪明": "语义：“聪明”形容人的智力，不能用来说住的地方。", "胖": "体貌：“胖”描写人或动物的体形，不能用来形容位置。", "悲伤": "语义：“悲伤”是人的情绪，不能用来形容住在某处的情况。"}, "sentence_index": 0, "correct_answer": "方便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很方便，只要十块钱。", "explanation": "这里应该用〈便宜〉。方便说做事省事，不用来说价格，价格低要说便宜。"}, {"text": "他的身体很方便。", "explanation": "这里应该用〈健康〉。方便指做事省事，形容身体的状况要说健康。"}, {"text": "他的成绩很方便。", "explanation": "这里应该用〈优秀〉。方便指做事省事，成绩的好坏要说优秀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方便", "is_correct": true, "explanation": "“方便”表示这条路走起来不省事，与后半句“我们走那条吧”相符。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：“幽默”形容人说话风趣，不能用来形容道路。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写人或动物的身形，不能用来形容道路。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的待人态度，不能用来形容道路。"}], "explanations": {"方便": "“方便”表示这条路走起来不省事，与后半句“我们走那条吧”相符。", "幽默": "语义：“幽默”形容人说话风趣，不能用来形容道路。", "瘦": "体貌：“瘦”描写人或动物的身形，不能用来形容道路。", "热情": "语义：“热情”形容人的待人态度，不能用来形容道路。"}, "sentence_index": 6, "correct_answer": "方便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的想法很方便。", "explanation": "这里应该用〈灵活〉。方便指做事省力省事，想法的变通要说灵活。"}, {"text": "这本书的内容很方便。", "explanation": "这里应该用〈丰富〉。方便指做事省事，内容的多少要说丰富。"}, {"text": "这种颜色很方便。", "explanation": "这里应该用〈好看〉。方便指做事省事，颜色的美丑要说好看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店晚上开门，对上班族被方便。", "corrected_sentence": "这家店晚上开门，对上班族很方便。", "error_description": "错误在于“方便”前用了“被”。“方便”是形容词，表示状态，不能用“被”；应说“对上班族很方便”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台新电脑用起来没方便。", "corrected_sentence": "这台新电脑用起来不方便。", "error_description": "错误在于用“没”否定形容词。“方便”是形容词，否定时一般用“不”，应说“用起来不方便”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21896, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "模糊：不清楚、不分明，与“清楚”意思相反，构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“清楚”无反义关系：“粗糙”形容表面不光滑，与明白与否无关。"}, {"text": "遥远", "is_correct": false, "explanation": "与“清楚”无反义关系：“遥远”形容距离远，与明白与否无关。"}, {"text": "巨大", "is_correct": false, "explanation": "与“清楚”无反义关系：“巨大”形容体积或数量大，与明白与否无关。"}], "correct_answer": "模糊", "explanations": {"模糊": "模糊：不清楚、不分明，与“清楚”意思相反，构成反义。", "粗糙": "与“清楚”无反义关系：“粗糙”形容表面不光滑，与明白与否无关。", "遥远": "与“清楚”无反义关系：“遥远”形容距离远，与明白与否无关。", "巨大": "与“清楚”无反义关系：“巨大”形容体积或数量大，与明白与否无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21896, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "模糊：不清楚、不分明，与“清楚”意思相反，构成反义。"}, {"text": "宽广", "is_correct": false, "explanation": "与“清楚”无反义关系：“宽广”形容面积大，与明白与否无关。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“清楚”无反义关系：“陡峭”形容坡度大，与明白与否无关。"}, {"text": "轻松", "is_correct": false, "explanation": "与“清楚”无反义关系：“轻松”形容不紧张、不费力，与明白与否无关。"}], "correct_answer": "模糊", "explanations": {"模糊": "模糊：不清楚、不分明，与“清楚”意思相反，构成反义。", "宽广": "与“清楚”无反义关系：“宽广”形容面积大，与明白与否无关。", "陡峭": "与“清楚”无反义关系：“陡峭”形容坡度大，与明白与否无关。", "轻松": "与“清楚”无反义关系：“轻松”形容不紧张、不费力，与明白与否无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21896, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是容易让人明白，不模糊。", "primary_collocate": null, "pronunciation": "qīng chu", "ipa": "tɕʰiŋ˥ ʈʂʰu", "syllable_count": 2, "sentences": [{"text": "他说得很清楚。", "target_word": "清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片很清楚。", "target_word": "清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲得清楚，我们都听懂了。", "target_word": "清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听不清楚你的话。", "target_word": "清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字太小，看不清楚。", "target_word": "清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法很清楚。", "target_word": "清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说清楚一点儿，好吗？", "target_word": "清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路牌上的字写得很清楚。", "target_word": "清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题的答案很清楚。", "target_word": "清楚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的名字写清楚。", "target_word": "清楚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清清楚楚", "label": "重叠"}, {"form": "清楚了", "label": "体标"}], "register": "中性", "sense_fingerprint": "容易明白，不模糊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e21988-a24b-41f5-92fd-a20a131657a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21896, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清楚", "is_correct": true, "explanation": "清楚：容易明白，不模糊，即本词条的意思。"}, {"text": "清除", "is_correct": false, "explanation": "chú（第二声）与轻声 chu 声调不同，意思是除去、消除。"}, {"text": "青春", "is_correct": false, "explanation": "qīngchūn 与 qīngchu 韵母不同（第二音节多一个 n），意思是年轻的时期。"}, {"text": "清初", "is_correct": false, "explanation": "chū（第一声）与轻声 chu 声调不同，意思是清朝初年。"}], "explanations": {"清楚": "清楚：容易明白，不模糊，即本词条的意思。", "清除": "chú（第二声）与轻声 chu 声调不同，意思是除去、消除。", "青春": "qīngchūn 与 qīngchu 韵母不同（第二音节多一个 n），意思是年轻的时期。", "清初": "chū（第一声）与轻声 chu 声调不同，意思是清朝初年。"}, "sentence_index": null, "correct_answer": "清楚"}, "level_3": {"options": [{"text": "清楚", "is_correct": true, "explanation": "清楚：说得明白、不含糊，与“他说得很……”相符。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”多形容排列、外观，“说得很整齐”搭配不当。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不说话，与“说得很……”的评述相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容体形或事物，不能描述说话的样子。"}], "explanations": {"清楚": "清楚：说得明白、不含糊，与“他说得很……”相符。", "整齐": "搭配：“整齐”多形容排列、外观，“说得很整齐”搭配不当。", "沉默": "语义：“沉默”指不说话，与“说得很……”的评述相矛盾。", "高大": "语义：“高大”形容体形或事物，不能描述说话的样子。"}, "sentence_index": 0, "correct_answer": "清楚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把房间打扫得很清楚。", "explanation": "这里应该用〈干净〉。“清楚”指明白、不模糊，不用来说房间打扫得干净。"}, {"text": "法官认定他的确很清楚，所以无罪释放。", "explanation": "这里应该用〈清白〉。“清楚”指明白，不指没有罪过。"}, {"text": "这里很清楚，很适合休息。", "explanation": "这里应该用〈清静〉。“清楚”指明白，不指环境安静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清楚", "is_correct": true, "explanation": "清楚：说明白、不含糊，与“你说……一点儿”搭配。"}, {"text": "结实", "is_correct": false, "explanation": "语义：“结实”形容坚固，不能用来说“说得结实”。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能修饰说话的方式。"}, {"text": "粗壮", "is_correct": false, "explanation": "语义：“粗壮”形容身体或物体粗大，不能描述说话。"}], "explanations": {"清楚": "清楚：说明白、不含糊，与“你说……一点儿”搭配。", "结实": "语义：“结实”形容坚固，不能用来说“说得结实”。", "雪白": "搭配：“雪白”形容颜色，不能修饰说话的方式。", "粗壮": "语义：“粗壮”形容身体或物体粗大，不能描述说话。"}, "sentence_index": 6, "correct_answer": "清楚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天气很清楚，我们去公园散步吧。", "explanation": "这里应该用〈晴朗〉。“清楚”不用来形容天气，天气好应说晴朗。"}, {"text": "这碗汤很清楚，不油也不咸。", "explanation": "这里应该用〈清淡〉。“清楚”不用来形容味道，清淡的汤应说清淡。"}, {"text": "山上的空气很清楚，吸一口很舒服。", "explanation": "这里应该用〈清新〉。“清楚”指明白、不模糊，形容空气应说清新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把步骤讲很清楚。", "corrected_sentence": "老师把步骤讲得很清楚。", "error_description": "程度补语错误：动词后接形容词作程度补语时要用“讲得很清楚”，“得”不能省。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把问题讲地很清楚。", "corrected_sentence": "他把问题讲得很清楚。", "error_description": "结构助词误用：动词“讲”与补语“清楚”之间应用“得”，不能用“地”（“地”修饰动词作状语），应说“讲得很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
