INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21898, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或乐器让音乐响起来。", "primary_collocate": null, "pronunciation": "yǎn zòu", "ipa": "jɛn˨˩˦ tsou̯˥˩", "syllable_count": 2, "sentences": [{"text": "他每天晚上在家演奏钢琴。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在舞台上演奏小提琴。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请你演奏这首曲子。”", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手指演奏着一首轻快的曲子。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有人在演奏吉他。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥演奏过很多种乐器。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，他演奏得很好，大家都鼓掌。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学演奏笛子，可是还没有笛子。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会开始了，乐队先演奏一首欢迎曲。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架老钢琴还可以演奏，声音很好听。", "target_word": "演奏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演奏了", "label": "体标"}, {"form": "演奏过", "label": "体标"}, {"form": "演奏着", "label": "体标"}, {"form": "演奏家", "label": "复合"}, {"form": "演奏会", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手或乐器让音乐响起来：演奏吉他、演奏笛子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4722aed3-9c6c-4f5b-9332-20e838c26bdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演奏", "is_correct": true, "explanation": "“演奏”指用乐器表演，“钢琴”是它的宾语，符合“每天晚上在家”的日常练习。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”针对语言或文字，不能接“钢琴”作宾语。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：“销毁”是毁坏，与“每天晚上在家”的日常行为不符。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：“扔掉”是丢弃，与“在家演奏钢琴”的日常行为冲突。"}], "explanations": {"演奏": "“演奏”指用乐器表演，“钢琴”是它的宾语，符合“每天晚上在家”的日常练习。", "翻译": "搭配：“翻译”针对语言或文字，不能接“钢琴”作宾语。", "销毁": "语义：“销毁”是毁坏，与“每天晚上在家”的日常行为不符。", "扔掉": "语义：“扔掉”是丢弃，与“在家演奏钢琴”的日常行为冲突。"}, "sentence_index": 0, "correct_answer": "演奏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在舞台上演奏了一段轻快的舞蹈。", "explanation": "这里应该用〈跳〉。演奏的对象是乐曲，表演舞蹈要用“跳”。"}, {"text": "他把菜演奏得很香。", "explanation": "这里应该用〈做〉。演奏只用于乐器和乐曲，做菜要用“做”。"}, {"text": "她在纸上演奏了一首诗。", "explanation": "这里应该用〈写〉。演奏指用乐器表现音乐，写诗要用“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演奏", "is_correct": true, "explanation": "“演奏得很好”评价的是乐器表演的表现，符合“比赛时”和“大家都鼓掌”的语境。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”针对书刊作品，不能用来评价比赛中的表现。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不是比赛中会博得大家鼓掌的表现，句子不通。"}, {"text": "宣判", "is_correct": false, "explanation": "语义：“宣判”是法院的判决，与比赛场景不符。"}], "explanations": {"演奏": "“演奏得很好”评价的是乐器表演的表现，符合“比赛时”和“大家都鼓掌”的语境。", "出版": "搭配：“出版”针对书刊作品，不能用来评价比赛中的表现。", "睡觉": "语义：“睡觉”不是比赛中会博得大家鼓掌的表现，句子不通。", "宣判": "语义：“宣判”是法院的判决，与比赛场景不符。"}, "sentence_index": 6, "correct_answer": "演奏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在桌上演奏了一盘棋。", "explanation": "这里应该用〈下〉。演奏指用乐器表演，下棋要说“下”。"}, {"text": "老师在课堂上演奏了一个故事。", "explanation": "这里应该用〈讲〉。演奏用于乐曲，讲故事要说“讲”。"}, {"text": "她用螺丝刀演奏了一台旧电脑。", "explanation": "这里应该用〈修〉。演奏只用于乐器，修电脑要说“修”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候演奏了过笛子。", "corrected_sentence": "他小时候演奏过笛子。", "error_description": "体标重复：“了”和“过”不能同时用在动词后面，表示曾经做过某事只用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹演奏的很好，爸爸很高兴。", "corrected_sentence": "妹妹演奏得很好，爸爸很高兴。", "error_description": "补语标记错误：“演奏”后引出程度补语要用“得”，不能用“的”，应说“演奏得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
