INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21900, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "声音的高低。", "primary_collocate": null, "pronunciation": "yīn gāo", "ipa": "in˥ kɑu̯˥", "syllable_count": 2, "sentences": [{"text": "笛子的音高比大鼓高很多。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请听一听，这两个音的音高一样吗？", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，唱歌时音高要准。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟叫声的音高比大象高。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱歌时音高不稳，听起来不太舒服。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴上，越往右边，音高越高。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里的软件可以测出音高。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "琴弦越短，音高就越高。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子刚学唱歌，还找不到正确的音高。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我分不清这两个声音的音高。", "target_word": "音高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绝对音高", "label": "复合"}, {"form": "相对音高", "label": "复合"}], "register": "中性", "sense_fingerprint": "声音的高低：音高不稳、找准音高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4722aed3-9c6c-4f5b-9332-20e838c26bdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音高", "is_correct": true, "explanation": "“音高”指声音的高低，笛子和大鼓比较的正是声音高低，符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人，不能用于乐器。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与“高很多”的比较不相关，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”一般不用来和“高”比较乐器，句子不自然。"}], "explanations": {"音高": "“音高”指声音的高低，笛子和大鼓比较的正是声音高低，符合语境。", "身高": "搭配：“身高”只用于人，不能用于乐器。", "颜色": "语义：“颜色”与“高很多”的比较不相关，句子不通。", "年龄": "搭配：“年龄”一般不用来和“高”比较乐器，句子不自然。"}, "sentence_index": 0, "correct_answer": "音高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个乐队的音高很大。", "explanation": "这里应该用〈音量〉。音高指声音的高低，声音的大小要用“音量”。"}, {"text": "这支舞曲的音高很快。", "explanation": "这里应该用〈节奏〉。音高指高低，快慢要用“节奏”。"}, {"text": "这把小提琴的音高很温暖。", "explanation": "这里应该用〈音色〉。音高指高低，声音的质地要用“音色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音高", "is_correct": true, "explanation": "“音高”指声音的高低，手机软件可以检测音高，符合语境。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，软件测不出，“测出作业”不通。"}, {"text": "道理", "is_correct": false, "explanation": "语义：“道理”是抽象的思想，无法用软件测量。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”是人际关系，软件测不出，句子不通。"}], "explanations": {"音高": "“音高”指声音的高低，手机软件可以检测音高，符合语境。", "作业": "语义：“作业”是学习任务，软件测不出，“测出作业”不通。", "道理": "语义：“道理”是抽象的思想，无法用软件测量。", "友谊": "语义：“友谊”是人际关系，软件测不出，句子不通。"}, "sentence_index": 6, "correct_answer": "音高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的音高有两千米。", "explanation": "这里应该用〈高度〉。音高指声音的高低，山的高矮要用“高度”。"}, {"text": "今天中午的音高是三十二度。", "explanation": "这里应该用〈温度〉。音高指声音的高低，气温要用“温度”。"}, {"text": "他的音高有一米八。", "explanation": "这里应该用〈身高〉。音高指声音的高低，人的高矮要用“身高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她唱出了三只不同的音高。", "corrected_sentence": "她唱出了三种不同的音高。", "error_description": "量词错误：“音高”的量词应用“种”，“只”不能用于音高。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他听不出这两个音的音高们。", "corrected_sentence": "他听不出这两个音的音高。", "error_description": "错误：“音高们”；正确：“音高”。“们”只用在指人的名词后面，“音高”不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
