INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21904, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西不动。", "primary_collocate": null, "pronunciation": "gù dìng", "ipa": "ku˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "请把桌子固定好，别让它动。", "target_word": "固定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用钉子固定木板。", "target_word": "固定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生用绷带固定了我的腿。", "target_word": "固定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸把梯子固定在墙边，我才敢爬上去。", "target_word": "固定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，帐篷要用绳子固定住。", "target_word": "固定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "摄影师用三脚架固定相机。", "target_word": "固定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "螺丝太松了，要再固定一下。", "target_word": "固定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用夹子固定头发，不让它掉下来。", "target_word": "固定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的架子没有固定好，有点晃。", "target_word": "固定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在固定窗户，免得风把它吹开。", "target_word": "固定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "固定了", "label": "体标"}, {"form": "固定住", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：用钉子、绳子等把东西弄稳，使其不能移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77c37cae-b219-4aee-bb4e-93cb237f46fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21904, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "固定", "is_correct": true, "explanation": "正确。固定读作 gù dìng，意思是用东西使其不能移动。"}, {"text": "注定", "is_correct": false, "explanation": "zhù 与 gù 的声母不同（zh 与 g），声调相同，意思是注定。"}, {"text": "估定", "is_correct": false, "explanation": "gū（第一声）与 gù（第四声）声调不同，意思是估计并确定。"}, {"text": "不定", "is_correct": false, "explanation": "bù 与 gù 的声母不同（b 与 g），声调相同，意思是不确定。"}], "explanations": {"固定": "正确。固定读作 gù dìng，意思是用东西使其不能移动。", "注定": "zhù 与 gù 的声母不同（zh 与 g），声调相同，意思是注定。", "估定": "gū（第一声）与 gù（第四声）声调不同，意思是估计并确定。", "不定": "bù 与 gù 的声母不同（b 与 g），声调相同，意思是不确定。"}, "sentence_index": null, "correct_answer": "固定"}, "level_3": {"options": [{"text": "摇", "is_correct": false, "explanation": "语义：“摇”是晃动，与后文“别让它动”正好相反，不能表示把桌子固定好。"}, {"text": "固定", "is_correct": true, "explanation": "正确。“固定好”指把桌子稳住，使其不动，与“别让它动”一致。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指加热或燃烧，与让桌子稳住的意思无关。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“桌子”搭配，不能说“唱好桌子”。"}], "explanations": {"摇": "语义：“摇”是晃动，与后文“别让它动”正好相反，不能表示把桌子固定好。", "固定": "正确。“固定好”指把桌子稳住，使其不动，与“别让它动”一致。", "烧": "语义：“烧”指加热或燃烧，与让桌子稳住的意思无关。", "唱": "搭配：“唱”不能与“桌子”搭配，不能说“唱好桌子”。"}, "sentence_index": 0, "correct_answer": "固定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把饺子固定进了锅里。", "explanation": "这里应该用〈放〉。固定指使东西不动，把东西放进容器要用放，不能说固定进锅里。"}, {"text": "他固定了自己的心情，不让它再难过。", "explanation": "这里应该用〈稳定〉。固定指使物体不动，心情的平稳要用稳定来说。"}, {"text": "他很快就把饼干固定了。", "explanation": "这里应该用〈吃〉。固定指使东西保持不动，把食物吃掉要用吃，此处的用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳", "is_correct": false, "explanation": "语义：“跳”指身体离地上下运动，与修理螺丝的意思无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“螺丝”搭配，不能说“再洗一下螺丝”。"}, {"text": "固定", "is_correct": true, "explanation": "正确。“螺丝太松了，要再固定一下”指把螺丝拧牢，使其不再松动。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”表示流泪或出声，与螺丝松动没有关系。"}], "explanations": {"跳": "语义：“跳”指身体离地上下运动，与修理螺丝的意思无关。", "洗": "搭配：“洗”不能与“螺丝”搭配，不能说“再洗一下螺丝”。", "固定": "正确。“螺丝太松了，要再固定一下”指把螺丝拧牢，使其不再松动。", "哭": "语义：“哭”表示流泪或出声，与螺丝松动没有关系。"}, "sentence_index": 6, "correct_answer": "固定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车子开得很固定。", "explanation": "这里应该用〈平稳〉。“固定”指使东西不动，不用来形容车子行驶的状态。"}, {"text": "他固定了一杯水。", "explanation": "这里应该用〈喝〉。固定指使东西不动，喝下液体要用喝，此处的用法不对。"}, {"text": "她在舞台上固定了一首歌。", "explanation": "这里应该用〈唱〉。固定指使东西不动，不能用于歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把相框固定墙上。", "corrected_sentence": "妈妈把相框固定在墙上。", "error_description": "漏掉介词：“固定”后面接处所时要用“在”引出，应说“固定在墙上”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把箱子固定很了。", "corrected_sentence": "他把箱子固定好了。", "error_description": "补语错误：“固定”后应接结果补语“好”，不能用“很”，应说“固定好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3ef8427-8705-4e76-a145-d2df3a556326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
