INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21906, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示不可以做某事。", "primary_collocate": null, "pronunciation": "bù néng", "ipa": "pu˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "在图书馆里不能大声说话。", "target_word": "不能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时不能看手机。", "target_word": "不能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子不能一个人过马路。", "target_word": "不能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是医院，不能抽烟。", "target_word": "不能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的时候不能说话。", "target_word": "不能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病了不能吃太凉的东西。", "target_word": "不能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课时不能吃东西。", "target_word": "不能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能把垃圾扔在地上。", "target_word": "不能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里不能带小狗进去。", "target_word": "不能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯亮着，车不能往前开。", "target_word": "不能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不能够", "label": "扩展形式"}, {"form": "能不能", "label": "疑问形式"}], "register": "中性", "sense_fingerprint": "情态动词，表示按规定、情理或条件不允许、不可以做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33c7f637-619d-49ba-80ef-a53edb7b3254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不能", "is_correct": true, "explanation": "「不能」表示不允许，与图书馆禁止大声说话的规定一致。"}, {"text": "可以", "is_correct": false, "explanation": "语义：「可以」表示允许，「在图书馆里可以大声说话」与安静场所的要求正相反。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「必须」表示强制要求，「必须大声说话」与图书馆的安静规定相冲突。"}, {"text": "敢", "is_correct": false, "explanation": "语义：「敢」表示有胆量去做某事，「在图书馆里敢大声说话」语义别扭，且不表示禁止。"}], "explanations": {"不能": "「不能」表示不允许，与图书馆禁止大声说话的规定一致。", "可以": "语义：「可以」表示允许，「在图书馆里可以大声说话」与安静场所的要求正相反。", "必须": "语义：「必须」表示强制要求，「必须大声说话」与图书馆的安静规定相冲突。", "敢": "语义：「敢」表示有胆量去做某事，「在图书馆里敢大声说话」语义别扭，且不表示禁止。"}, "sentence_index": 0, "correct_answer": "不能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事不能是他做的，他那天根本不在场。", "explanation": "这是「不能」的推断义，表示不可能，说的是这件事不可能是他做的。此句不是禁止，与本词「不可以」的禁止义不同。"}, {"text": "我吃饱了，不能再吃了。", "explanation": "这是「不能再」的极限义，表示已经到了限度，做不到更多。此句与本词「不可以」的禁止义不同。"}, {"text": "这道题太难了，我不能做出来。", "explanation": "这是「不能」的能力义，表示做不到。此句说的是题目太难、无法做出，与本词「不可以」的禁止义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不能", "is_correct": true, "explanation": "「不能」表示不允许，与上课时禁止吃东西的纪律一致。"}, {"text": "应该", "is_correct": false, "explanation": "语义：「应该」表示应当做某事，「上课时应该吃东西」与课堂纪律相悖。"}, {"text": "愿意", "is_correct": false, "explanation": "语义：「愿意」表示有意愿，「上课时愿意吃东西」说的是意愿，不表示纪律上的禁止。"}, {"text": "会", "is_correct": false, "explanation": "语义：「会」表示可能或将要，「上课时会吃东西」只是陈述可能性，不是纪律上的禁止。"}], "explanations": {"不能": "「不能」表示不允许，与上课时禁止吃东西的纪律一致。", "应该": "语义：「应该」表示应当做某事，「上课时应该吃东西」与课堂纪律相悖。", "愿意": "语义：「愿意」表示有意愿，「上课时愿意吃东西」说的是意愿，不表示纪律上的禁止。", "会": "语义：「会」表示可能或将要，「上课时会吃东西」只是陈述可能性，不是纪律上的禁止。"}, "sentence_index": 6, "correct_answer": "不能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不能听懂他的方言。", "explanation": "这是「不能」的能力义，表示做不到。此句的意思与本词「不允许」的义项不同，本句不是在说禁止。"}, {"text": "他那么聪明，不能考不上大学。", "explanation": "这是「不能」的推断义，表示不可能，用来强调结果一定如此。此处要表示禁止，与这一义项不同。"}, {"text": "我们不能不去参加会议。", "explanation": "这是「不能……不……」的双重否定义，表示必须。此处要表示不允许，与这一义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在公共场所不能了随便扔垃圾。", "corrected_sentence": "在公共场所不能随便扔垃圾。", "error_description": "错误：「不能」后多加了「了」，助动词不能带「了」。正确：删去「了」，即「不能随便扔垃圾」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在考场上不能了偷看别人的答案。", "corrected_sentence": "在考场上不能偷看别人的答案。", "error_description": "错误：「不能」后面多加了「了」，助动词不能带「了」。正确：「不能偷看」，「不能」后直接接动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21910, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗糙", "is_correct": true, "explanation": "粗糙：与“精细”构成反义，指做工不细致，与“工作很精细”相反。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹：形容场面喧嚷，与“精细”不构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线或颜色，与“精细”不构成反义。"}, {"text": "寒冷", "is_correct": false, "explanation": "寒冷：形容温度，与“精细”不构成反义。"}], "correct_answer": "粗糙", "explanations": {"粗糙": "粗糙：与“精细”构成反义，指做工不细致，与“工作很精细”相反。", "热闹": "热闹：形容场面喧嚷，与“精细”不构成反义。", "明亮": "明亮：形容光线或颜色，与“精细”不构成反义。", "寒冷": "寒冷：形容温度，与“精细”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
