INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21912, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把听到或看到的事写下来。", "primary_collocate": null, "pronunciation": "jì lù", "ipa": "tɕi˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "老师让我们把看到的东西记录下来。", "target_word": "记录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都在本子上记录天气。", "target_word": "记录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者认真地记录着老人的话。", "target_word": "记录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都把孩子的成长记录在本子上。", "target_word": "记录", "complexity_tier": "T3", "furigana": "tā měi tiān dōu bǎ háizi de chéngzhǎng jìlù zài běnzi shàng.", "sentence_source": "generated"}, {"text": "医生正在记录病人的情况。", "target_word": "记录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢用日记记录旅行。", "target_word": "记录", "complexity_tier": "T3", "furigana": "wǒ xǐhuan yòng rìjì jìlù lǚxíng.", "sentence_source": "generated"}, {"text": "请你把会上说的话记录一下。", "target_word": "记录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把听到的故事都记录了。", "target_word": "记录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明每天记录自己花了多少钱。", "target_word": "记录", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家记录过这种鸟的生活习性。", "target_word": "记录", "complexity_tier": "T3", "furigana": "kēxuéjiā jìlù guò zhè zhǒng niǎo de shēnghuó xíxìng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "记录了", "label": "体标"}, {"form": "记录着", "label": "体标"}, {"form": "记录过", "label": "体标"}, {"form": "记录下来", "label": "趋向补语"}], "register": "中性", "sense_fingerprint": "用文字、照片等把见闻留存下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21912, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "记录", "is_correct": true, "explanation": "记录，把看到的东西写下来，与“下来”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”只用于可食用的东西，看到的东西不能“吃下来”。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧，与“看到的东西”无关，不能“烧下来”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，“看到的东西”不能“喝下来”。"}], "explanations": {"记录": "记录，把看到的东西写下来，与“下来”相合。", "吃": "语义：“吃”只用于可食用的东西，看到的东西不能“吃下来”。", "烧": "语义：“烧”指燃烧，与“看到的东西”无关，不能“烧下来”。", "喝": "搭配：“喝”的对象是饮料，“看到的东西”不能“喝下来”。"}, "sentence_index": 0, "correct_answer": "记录"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对童年的记录很深，到现在还记得。", "explanation": "这里应该用〈记忆〉。记录指写下来的文字或数据，对童年的印象要用〈记忆〉。"}, {"text": "他用钢笔记录了一只小猫。", "explanation": "这里应该用〈画〉。记录指用文字、数据留存信息，用钢笔画小猫要用〈画〉。"}, {"text": "我把这张纸记录成了红色。", "explanation": "这里应该用〈涂〉。记录指把见闻、数据写下来，给纸上色要用〈涂〉，不能用〈记录〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记录", "is_correct": true, "explanation": "记录，把说过的话写下来，与“请你把……一下”相合。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”的对象是液体，话不能“倒”。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”指缝纫，说的话不能缝。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”用于衣物，“穿”话不成立。"}], "explanations": {"记录": "记录，把说过的话写下来，与“请你把……一下”相合。", "倒": "搭配：“倒”的对象是液体，话不能“倒”。", "缝": "语义：“缝”指缝纫，说的话不能缝。", "穿": "语义：“穿”用于衣物，“穿”话不成立。"}, "sentence_index": 6, "correct_answer": "记录"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这幅画记录在墙上，让大家欣赏。", "explanation": "这里应该用〈挂〉。记录指用文字、数据留存信息，把画悬挂起来要用〈挂〉。"}, {"text": "我每天晚上记录一个苹果。", "explanation": "这里应该用〈吃〉。记录的对象是信息、数据，不能是可以吃的食物。"}, {"text": "他把黑板上的字记录干净了。", "explanation": "这里应该用〈擦〉。记录是留存信息，擦去黑板上的字要用〈擦〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把实验数据记录了好。", "corrected_sentence": "他把实验数据记录好了。", "error_description": "补语位置错误：结果补语“好”应紧跟动词，“了”放在句末，应为“记录好了”，不能说“记录了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把会议内容记录很详细。", "corrected_sentence": "他把会议内容记录得很详细。", "error_description": "补语标记缺失：动词后带程度补语须用“得”，应为“记录得很详细”，不能说“记录很详细”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
