INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21916, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情发生的时间离现在很近。", "primary_collocate": null, "pronunciation": "gāng", "ipa": "/kɑŋ˥/", "syllable_count": 1, "sentences": [{"text": "我刚到家。", "target_word": "刚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他刚吃完饭。", "target_word": "刚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨刚停，我们就出门了。", "target_word": "刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子刚学走路，走得很慢。", "target_word": "刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我刚来中国一个月，还不会说汉语。", "target_word": "刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚下班，现在很累。", "target_word": "刚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师刚走，学生们就开始玩手机了。", "target_word": "刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我刚买的书，已经看完一半了。", "target_word": "刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟刚起床，还没吃早饭。", "target_word": "刚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚学会游泳，还不敢去深水区。", "target_word": "刚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "刚刚", "label": "重叠"}, {"form": "刚好", "label": "复合"}], "register": "中性", "sense_fingerprint": "副词：动作或情况刚发生不久，离说话时很近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28481438-1c53-4cd2-8bbb-0605e7c56396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "刚", "is_correct": true, "explanation": "正确答案：刚（gāng），表示事情发生的时间离现在很近。"}, {"text": "港", "is_correct": false, "explanation": "gǎng（第三声）与 gāng（第一声）声调不同，意思是港口。"}, {"text": "干", "is_correct": false, "explanation": "gān（第一声）与 gāng 的韵母不同（an 与 ang），意思是干燥或做。"}, {"text": "杠", "is_correct": false, "explanation": "gàng（第四声）与 gāng（第一声）声调不同，意思是杠杆或横木。"}], "explanations": {"刚": "正确答案：刚（gāng），表示事情发生的时间离现在很近。", "港": "gǎng（第三声）与 gāng（第一声）声调不同，意思是港口。", "干": "gān（第一声）与 gāng 的韵母不同（an 与 ang），意思是干燥或做。", "杠": "gàng（第四声）与 gāng（第一声）声调不同，意思是杠杆或横木。"}, "sentence_index": null, "correct_answer": "刚"}, "level_3": {"options": [{"text": "刚", "is_correct": true, "explanation": "刚：表示动作或情况发生不久，离说话时很近，句中正合适。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能修饰动词短语“到家”，“我很到家”不成立。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”表示经常，与“到家”这一次性的动作不合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示偶然发生，与说话人刚完成的这次到家不合。"}], "explanations": {"刚": "刚：表示动作或情况发生不久，离说话时很近，句中正合适。", "很": "语法：“很”是程度副词，不能修饰动词短语“到家”，“我很到家”不成立。", "常常": "语义：“常常”表示经常，与“到家”这一次性的动作不合。", "偶尔": "语义：“偶尔”表示偶然发生，与说话人刚完成的这次到家不合。"}, "sentence_index": 0, "correct_answer": "刚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚永远记得我的生日，每年都会祝福我。", "explanation": "这里应该去掉〈刚〉。“刚”表示事情发生的时间离现在很近，不能和“永远”这样的长时间连用。"}, {"text": "他刚每天都早起，身体很好。", "explanation": "这里应该去掉〈刚〉。“刚”表示事情发生的时间离现在很近，不能用于“每天都”这样的长期习惯。"}, {"text": "我明天刚到家，你们别等我了。", "explanation": "这里应该用〈才〉。“刚”只能用于刚发生不久的事，不能用于“明天”这样的将来时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21916, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "刚", "is_correct": true, "explanation": "正确答案：刚（gāng），表示事情发生的时间离现在很近。"}, {"text": "杠", "is_correct": false, "explanation": "gàng（第四声）与 gāng（第一声）声调不同，意思是杠杆或横木。"}, {"text": "岗", "is_correct": false, "explanation": "gǎng（第三声）与 gāng（第一声）声调不同，意思是岗位。"}, {"text": "肝", "is_correct": false, "explanation": "gān（第一声）与 gāng 的韵母不同（an 与 ang），意思是肝脏。"}], "explanations": {"刚": "正确答案：刚（gāng），表示事情发生的时间离现在很近。", "杠": "gàng（第四声）与 gāng（第一声）声调不同，意思是杠杆或横木。", "岗": "gǎng（第三声）与 gāng（第一声）声调不同，意思是岗位。", "肝": "gān（第一声）与 gāng 的韵母不同（an 与 ang），意思是肝脏。"}, "sentence_index": null, "correct_answer": "刚"}, "level_3": {"options": [{"text": "刚", "is_correct": true, "explanation": "刚：表示事情刚发生不久，离说话时很近，与后半句“就开始”的先后关系相合。"}, {"text": "还", "is_correct": false, "explanation": "语义：“还”表示仍然，前一分句说老师已经走了，用“还”句意自相矛盾。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定“走”，与后半句“学生们就开始玩手机”的先后关系不合。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能修饰动词“走”，“老师很走”不成立。"}], "explanations": {"刚": "刚：表示事情刚发生不久，离说话时很近，与后半句“就开始”的先后关系相合。", "还": "语义：“还”表示仍然，前一分句说老师已经走了，用“还”句意自相矛盾。", "不": "语义：“不”否定“走”，与后半句“学生们就开始玩手机”的先后关系不合。", "很": "语法：“很”是程度副词，不能修饰动词“走”，“老师很走”不成立。"}, "sentence_index": 6, "correct_answer": "刚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我刚从来没去过北京。", "explanation": "这里应该去掉〈刚〉。“刚”表示事情发生的时间离现在很近，不能和“从来没”这样表示从未发生的词连用。"}, {"text": "我们刚认识很久了，他已经很了解我。", "explanation": "这里应该去掉〈刚〉。“刚”表示事情发生的时间离现在很近，不能和“很久”这样的长时间连用。"}, {"text": "他刚从小就喜欢画画，已经画了二十年。", "explanation": "这里应该去掉〈刚〉。“刚”表示事情发生的时间离现在很近，不能和“从小就”这样表示很早开始的说法连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈很刚下班，正在做饭。", "corrected_sentence": "妈妈刚下班，正在做饭。", "error_description": "程度副词“很”不能修饰时间副词“刚”。应删去“很”，说成“妈妈刚下班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很刚学会做饭，还做不好。", "corrected_sentence": "我刚学会做饭，还做不好。", "error_description": "“很”是程度副词，不能修饰时间副词“刚”。应删去“很”，说成“刚学会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
