INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21920, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "欧洲历史上大约从公元五世纪到十五世纪的一段时期。", "primary_collocate": null, "pronunciation": "zhōng shì jì", "ipa": "ʈʂʊŋ˥ ʂɻ̩˥˩ tɕi˥˩", "syllable_count": 3, "sentences": [{"text": "中世纪的欧洲有很多城堡。", "target_word": "中世纪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中世纪的人不会用电脑。", "target_word": "中世纪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书讲的是中世纪的故事。", "target_word": "中世纪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中世纪的骑士穿着铁衣服。", "target_word": "中世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中世纪，很多人住在小村子里。", "target_word": "中世纪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在博物馆看了中世纪的画。", "target_word": "中世纪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中世纪离现在已经很远了。", "target_word": "中世纪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢研究中世纪的历史。", "target_word": "中世纪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中世纪的时候，书都是用手写的。", "target_word": "中世纪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里的中世纪国王住在大城堡里。", "target_word": "中世纪", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "中世紀", "label": "繁体"}], "register": "通用", "sense_fingerprint": "名词，历史时期名称，指欧洲约五世纪到十五世纪的时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60fb9430-b8df-4950-a53e-fc0e3676837a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中世纪", "is_correct": true, "explanation": "“中世纪”指欧洲约五世纪到十五世纪，与“欧洲”搭配。"}, {"text": "清朝", "is_correct": false, "explanation": "语义：“清朝”是中国的朝代，与欧洲不符。"}, {"text": "中国", "is_correct": false, "explanation": "语义：“中国”是国家，不是历史时期，与“欧洲的城堡”不符。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“学校”不能作“欧洲”的时期限定，句子不成立。"}], "explanations": {"中世纪": "“中世纪”指欧洲约五世纪到十五世纪，与“欧洲”搭配。", "清朝": "语义：“清朝”是中国的朝代，与欧洲不符。", "中国": "语义：“中国”是国家，不是历史时期，与“欧洲的城堡”不符。", "学校": "搭配：“学校”不能作“欧洲”的时期限定，句子不成立。"}, "sentence_index": 0, "correct_answer": "中世纪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把中世纪放在书架上。", "explanation": "这里应该用〈书〉。〈中世纪〉是历史时期，不是物品，不能被“放”，应说“我把书放在书架上”。"}, {"text": "我们昨天去了中世纪。", "explanation": "这里应该用〈欧洲〉。〈中世纪〉是时期名称，不是地方，不能和“去”搭配。"}, {"text": "中世纪正在放假。", "explanation": "这里应该用〈学生〉。〈中世纪〉是历史时期，不能进行“放假”这样的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中世纪", "is_correct": true, "explanation": "“中世纪”是很久以前的历史时期，与“离现在很远”相合。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指未来，不能说“已经很远了”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是地点，不是时间，不能说“离现在很远”。"}, {"text": "小明", "is_correct": false, "explanation": "搭配：“离现在”搭配时间，不搭配人名。"}], "explanations": {"中世纪": "“中世纪”是很久以前的历史时期，与“离现在很远”相合。", "明天": "语义：“明天”指未来，不能说“已经很远了”。", "教室": "语义：“教室”是地点，不是时间，不能说“离现在很远”。", "小明": "搭配：“离现在”搭配时间，不搭配人名。"}, "sentence_index": 6, "correct_answer": "中世纪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的中世纪有四十个学生。", "explanation": "这里应该用〈班级〉。〈中世纪〉是历史时期，不能指班级。"}, {"text": "这台电脑是中世纪的最新款。", "explanation": "这里应该用〈现代〉。〈中世纪〉指很久以前的时期，与“最新款”矛盾。"}, {"text": "他的中世纪很高。", "explanation": "这里应该用〈身高〉。〈中世纪〉不能用来形容人的身高，应说“他很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中世纪们的欧洲人住在城堡里。", "corrected_sentence": "中世纪的欧洲人住在城堡里。", "error_description": "错误：“中世纪”是时期名称，不能加“们”表示复数。正确：应去掉“们”，说“中世纪的欧洲人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段中世纪的中世纪历史很有意思。", "corrected_sentence": "这段中世纪的历史很有意思。", "error_description": "错误：“中世纪”重复出现（中世纪的中世纪历史）。正确：只说一次，应为“这段中世纪的历史”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
