INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21924, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事物改变为另一种东西或状态。", "primary_collocate": null, "pronunciation": "biàn chéng", "ipa": "pjɛn˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "水冷了就会变成冰。", "target_word": "变成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毛毛虫以后会变成蝴蝶。", "target_word": "变成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城变成了很大的城市。", "target_word": "变成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的头发都变成白色了。", "target_word": "变成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天冷了，雨变成了雪。", "target_word": "变成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把纸变成了一只小鸟。", "target_word": "变成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶秋天会变成黄色。", "target_word": "变成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块面团烤好以后会变成面包。", "target_word": "变成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，白天变成了晚上。", "target_word": "变成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条小河变成了一条大路。", "target_word": "变成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变成了", "label": "体标"}, {"form": "变成过", "label": "体标"}, {"form": "變成", "label": "繁体"}], "register": "通用", "sense_fingerprint": "事物改变样子，成为另一种东西或状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 那条 (Zipf 3.96), 小河 (Zipf 3.39), 大路 (Zipf 3.47)']::text[], 'e09e1671-b6a6-4032-8b8c-f04eced1b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21924, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变成", "is_correct": true, "explanation": "正确答案：变成，指事物改变为另一种东西或状态。"}, {"text": "编程", "is_correct": false, "explanation": "biān chéng（第一声）与 biàn chéng（第四声）第一个音节声调不同，编程指编写计算机程序。"}, {"text": "辩称", "is_correct": false, "explanation": "biàn chēng 与 biàn chéng 第二个音节声调不同（第一声与第二声），辩称指为自己辩解说。"}, {"text": "变长", "is_correct": false, "explanation": "biàn cháng 与 biàn chéng 只有韵母不同（-ang 与 -eng），变长指变得更长。"}], "explanations": {"变成": "正确答案：变成，指事物改变为另一种东西或状态。", "编程": "biān chéng（第一声）与 biàn chéng（第四声）第一个音节声调不同，编程指编写计算机程序。", "辩称": "biàn chēng 与 biàn chéng 第二个音节声调不同（第一声与第二声），辩称指为自己辩解说。", "变长": "biàn cháng 与 biàn chéng 只有韵母不同（-ang 与 -eng），变长指变得更长。"}, "sentence_index": null, "correct_answer": "变成"}, "level_3": {"options": [{"text": "看成", "is_correct": false, "explanation": "语义：“看成”指误认，不表示水真正变成了冰。"}, {"text": "变成", "is_correct": true, "explanation": "正确：“变成”表示水冷了以后改变为冰，符合句意。"}, {"text": "变得", "is_correct": false, "explanation": "配价：“变得”后面接形容词或状态，不接“冰”这样的名词。"}, {"text": "叫作", "is_correct": false, "explanation": "语义：“叫作”指称呼或命名，不表示水本身的变化。"}], "explanations": {"看成": "语义：“看成”指误认，不表示水真正变成了冰。", "变成": "正确：“变成”表示水冷了以后改变为冰，符合句意。", "变得": "配价：“变得”后面接形容词或状态，不接“冰”这样的名词。", "叫作": "语义：“叫作”指称呼或命名，不表示水本身的变化。"}, "sentence_index": 0, "correct_answer": "变成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次演出变成了大家的注意。", "explanation": "这里应该用〈引起〉。“引起”表示使人产生注意或情绪；“变成”表示主体本身转变为另一事物，演出不能变成注意。"}, {"text": "这次考试变成了高分。", "explanation": "这里应该用〈考出〉。“考出”表示通过考试取得成绩；“变成”表示事物本身转变，考试不能变成分数。"}, {"text": "他变成了老师的表扬。", "explanation": "这里应该用〈获得〉。“获得”表示得到某种东西；“变成”表示主体本身转变为另一事物，“他”不能变成“表扬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿上", "is_correct": false, "explanation": "搭配：“穿上”的对象是衣物，树叶不能“穿上黄色”。"}, {"text": "变成", "is_correct": true, "explanation": "正确：“变成”表示树叶秋天时颜色改变为黄色，符合句意。"}, {"text": "涂", "is_correct": false, "explanation": "配价：“涂”需要有人施加动作，树叶不能“涂黄色”。"}, {"text": "冒出", "is_correct": false, "explanation": "搭配：“冒出”多用于烟、泡、芽等，不用于颜色。"}], "explanations": {"穿上": "搭配：“穿上”的对象是衣物，树叶不能“穿上黄色”。", "变成": "正确：“变成”表示树叶秋天时颜色改变为黄色，符合句意。", "涂": "配价：“涂”需要有人施加动作，树叶不能“涂黄色”。", "冒出": "搭配：“冒出”多用于烟、泡、芽等，不用于颜色。"}, "sentence_index": 6, "correct_answer": "变成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他突然变成了一声惊叫。", "explanation": "这里应该用〈发出〉。“发出”表示发出声音；“变成”表示事物本身转变为另一种东西，人不能变成一声惊叫。"}, {"text": "他变成了好成绩。", "explanation": "这里应该用〈取得〉。“取得”表示获得成绩；“变成”表示主体本身改变，不能说“变成好成绩”。"}, {"text": "这个答案变成了要求。", "explanation": "这里应该用〈符合〉。“符合”表示与要求相合；“变成”不能说答案变成了要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块冰化了以后会变成了水。", "corrected_sentence": "这块冰化了以后会变成水。", "error_description": "“会”表示将来，“了”表示已完成，二者不能同时用在“变成”后面。正确应为“会变成水”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她布把变成了一件衣服。", "corrected_sentence": "她把布变成了一件衣服。", "error_description": "“把”引出被处置的对象，应放在“布”前面。写成“布把”是错误的，正确应为“把布变成了一件衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
