INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21928, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没错，就是对的。", "primary_collocate": null, "pronunciation": "zhǔn què", "ipa": "ʈʂun˨˩˦ tɕʰɥe˥˩", "syllable_count": 2, "sentences": [{"text": "你的回答很准确，老师很满意。", "target_word": "准确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报不太准确。", "target_word": "准确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数字不准确，请再查一下。", "target_word": "准确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一枪就准确地打中了目标。", "target_word": "准确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块表走得很准确。", "target_word": "准确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要我们准确地写每个字。", "target_word": "准确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话很准确，一点也没错。", "target_word": "准确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的位置很准确，我们很快找到了。", "target_word": "准确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词用得很准确。", "target_word": "准确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我准确的时间和地点。", "target_word": "准确", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "准确地", "label": "副词形式"}, {"form": "准确性", "label": "复合"}, {"form": "不准确", "label": "否定式"}], "register": "中性", "sense_fingerprint": "与事实或标准完全相符，没有错误", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "准确", "is_correct": true, "explanation": "正确。“你的回答很准确”说的是回答与事实相符，与“老师很满意”的语境一致。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”形容身高或高度，不能用来评价回答，“回答很高”不通。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容高度或身材，不能用来形容回答，与“老师很满意”也不协调。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”形容人的年龄，回答没有年龄，这个词与“回答”无法搭配。"}], "explanations": {"准确": "正确。“你的回答很准确”说的是回答与事实相符，与“老师很满意”的语境一致。", "高": "体貌：“高”形容身高或高度，不能用来评价回答，“回答很高”不通。", "矮": "体貌：“矮”形容高度或身材，不能用来形容回答，与“老师很满意”也不协调。", "年轻": "语义：“年轻”形容人的年龄，回答没有年龄，这个词与“回答”无法搭配。"}, "sentence_index": 0, "correct_answer": "准确"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服穿起来很准确，很称身。", "explanation": "这里应该用〈合身〉。“准确”指与标准相符、没有错误，不用来形容衣服穿着的松紧，应说“很合身”。"}, {"text": "他跑得很准确，一下子就到了终点。", "explanation": "这里应该用〈快〉。“准确”指没有错误，不表示速度，描述跑得快不能用它。"}, {"text": "这场比赛很准确，大家都很喜欢看。", "explanation": "这里应该用〈精彩〉。“准确”指与标准相符，不用来评价比赛好不好看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "准确", "is_correct": true, "explanation": "正确。“他的话很准确，一点也没错”说的是话与事实相符，与“一点也没错”一致。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容身材，不能用来评价话，“他的话很瘦”不通。"}, {"text": "凉", "is_correct": false, "explanation": "语义：“凉”形容温度，话不能有温度上的凉热，这里与“一点也没错”的语境不符。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“湿”形容物体含水，话不能是潮湿的，这个词与“话”无法搭配。"}], "explanations": {"准确": "正确。“他的话很准确，一点也没错”说的是话与事实相符，与“一点也没错”一致。", "瘦": "体貌：“瘦”形容身材，不能用来评价话，“他的话很瘦”不通。", "凉": "语义：“凉”形容温度，话不能有温度上的凉热，这里与“一点也没错”的语境不符。", "湿": "语义：“湿”形容物体含水，话不能是潮湿的，这个词与“话”无法搭配。"}, "sentence_index": 6, "correct_answer": "准确"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨下得很准确，街上的人都湿透了。", "explanation": "这里应该用〈猛烈〉。“准确”指与标准相符，不用来形容雨势的大小。"}, {"text": "这个孩子的脸很准确，大家都很喜欢他。", "explanation": "这里应该用〈漂亮〉。“准确”指与标准相符、没有错误，不用来形容相貌。"}, {"text": "这杯水很准确，你快喝吧。", "explanation": "这里应该用〈干净〉。“准确”指与事实或标准相符、没有错误，不用来形容水是否干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她准确的找到了答案。", "corrected_sentence": "她准确地找到了答案。", "error_description": "错误形式是“准确的找到”，正确形式是“准确地找到”。“准确”修饰动词“找到”时要用“地”，“的”只用于修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把准确了的地址写下来。", "corrected_sentence": "请把准确的地址写下来。", "error_description": "错误形式是“准确了的地址”，正确形式是“准确的地址”。“准确”是形容词，修饰名词“地址”时后面用“的”，不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
