INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经常做同样的事情，慢慢就变成自然了。", "primary_collocate": null, "pronunciation": "xí guàn", "ipa": "ɕi˧˥ kwan˥˩", "syllable_count": 2, "sentences": [{"text": "早起是我的好习惯。", "target_word": "习惯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有每天读书的习惯。", "target_word": "习惯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要养成早睡的习惯。", "target_word": "习惯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个坏习惯很难改。", "target_word": "习惯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个国家的饮食习惯都不一样。", "target_word": "习惯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有喝咖啡的习惯。", "target_word": "习惯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师希望学生有好习惯。", "target_word": "习惯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完饭洗碗是他的习惯。", "target_word": "习惯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他改掉了抽烟的习惯。", "target_word": "习惯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动的习惯让她很健康。", "target_word": "习惯", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "習慣", "label": "繁体"}, {"form": "习惯性", "label": "复合"}], "register": "中性", "sense_fingerprint": "习惯：长期形成的自然做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21932, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "习惯", "is_correct": true, "explanation": "正确：习惯 xí guàn，指长期形成的自然做法。"}, {"text": "吸管", "is_correct": false, "explanation": "xī guǎn 与 xí guàn 两个音节声调都不同，意思是吸管。"}, {"text": "籍贯", "is_correct": false, "explanation": "jí 与 xí 声母不同（j 与 x），声调相同，意思是籍贯。"}, {"text": "细管", "is_correct": false, "explanation": "xì guǎn 与 xí guàn 两个音节声调都不同，意思是细的管子。"}], "explanations": {"习惯": "正确：习惯 xí guàn，指长期形成的自然做法。", "吸管": "xī guǎn 与 xí guàn 两个音节声调都不同，意思是吸管。", "籍贯": "jí 与 xí 声母不同（j 与 x），声调相同，意思是籍贯。", "细管": "xì guǎn 与 xí guàn 两个音节声调都不同，意思是细的管子。"}, "sentence_index": null, "correct_answer": "习惯"}, "level_3": {"options": [{"text": "习惯", "is_correct": true, "explanation": "“习惯”指长期形成的做法，与“早起”和“好”搭配，语义通顺。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”是考试或工作的结果，不是作息方式，“早起是好成绩”不通。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”是空间，不能说“早起是好房间”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是课后的练习，不是人的做法，“早起是我的好作业”不通。"}], "explanations": {"习惯": "“习惯”指长期形成的做法，与“早起”和“好”搭配，语义通顺。", "成绩": "语义：“成绩”是考试或工作的结果，不是作息方式，“早起是好成绩”不通。", "房间": "语义：“房间”是空间，不能说“早起是好房间”。", "作业": "语义：作业是课后的练习，不是人的做法，“早起是我的好作业”不通。"}, "sentence_index": 0, "correct_answer": "习惯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的习惯很便宜。", "explanation": "这里应该用〈价格〉。便宜形容价格，习惯不能这样形容。"}, {"text": "他的习惯很开朗。", "explanation": "这里应该用〈性格〉。开朗形容性格，习惯不能这样形容。"}, {"text": "她脸上露出了习惯。", "explanation": "这里应该用〈笑容〉。露出的是表情，习惯不能“露出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "习惯", "is_correct": true, "explanation": "“习惯”指长期形成的做法，与“好”和“希望学生有”搭配，语义通顺。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是地方，不能说“有好食堂”来指学生的做法。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是报酬，与学生的日常做法无关。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光照下的暗影，不能指学生的做法，与“有好”搭配不通。"}], "explanations": {"习惯": "“习惯”指长期形成的做法，与“好”和“希望学生有”搭配，语义通顺。", "食堂": "语义：“食堂”是地方，不能说“有好食堂”来指学生的做法。", "工资": "语义：“工资”是报酬，与学生的日常做法无关。", "影子": "语义：影子是光照下的暗影，不能指学生的做法，与“有好”搭配不通。"}, "sentence_index": 6, "correct_answer": "习惯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她送了我一个习惯。", "explanation": "这里应该用〈礼物〉。送的是实物，习惯不能送人。"}, {"text": "这块布的习惯很厚。", "explanation": "这里应该用〈厚度〉。厚薄形容布料或物体，习惯不能这样形容。"}, {"text": "这朵花的习惯很鲜艳。", "explanation": "这里应该用〈颜色〉。鲜艳形容颜色，习惯不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从小就养成了一只写日记的习惯。", "corrected_sentence": "他从小就养成了一个写日记的习惯。", "error_description": "“习惯”的量词应用“个”，“只”多用于动物或成对的东西，不能用于习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直保持着很好习惯。", "corrected_sentence": "他一直保持着好习惯。", "error_description": "“好”修饰“习惯”前加“很”时需要加“的”，不能说“很好习惯”，应说“好习惯”或“很好的习惯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专用", "is_correct": true, "explanation": "专用：只供某人或某种用途使用，与「通用」（大家都可以用）意思相反，是反义词。"}, {"text": "快速", "is_correct": false, "explanation": "快速形容速度，与「通用」的意思没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净形容清洁，与「通用」没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与「通用」没有反义关系。"}], "correct_answer": "专用", "explanations": {"专用": "专用：只供某人或某种用途使用，与「通用」（大家都可以用）意思相反，是反义词。", "快速": "快速形容速度，与「通用」的意思没有反义关系。", "干净": "干净形容清洁，与「通用」没有反义关系。", "明亮": "明亮形容光线或颜色，与「通用」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "专用", "is_correct": true, "explanation": "专用：只供某人或某种用途使用，与「通用」（大家都可以用）意思相反，是反义词。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂形容事情或结构繁多，与「通用」没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软形容质地，与「通用」没有反义关系。"}, {"text": "寂静", "is_correct": false, "explanation": "寂静形容没有声音，与「通用」没有反义关系。"}], "correct_answer": "专用", "explanations": {"专用": "专用：只供某人或某种用途使用，与「通用」（大家都可以用）意思相反，是反义词。", "复杂": "复杂形容事情或结构繁多，与「通用」没有反义关系。", "柔软": "柔软形容质地，与「通用」没有反义关系。", "寂静": "寂静形容没有声音，与「通用」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大家都可以用的。", "primary_collocate": null, "pronunciation": "tōng yòng", "ipa": "tʰʊŋ˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这根充电线全家人都通用。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间的门卡大家通用。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套书全班同学通用，不用每人买一本。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们两个人的充电器是通用的。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种雨衣男女通用，大小也合适。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "办公室里的打印机大家通用。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张公园年票家人之间能通用吗？", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套标准教材全校通用。", "target_word": "通用", "complexity_tier": "T3", "furigana": "zhè tào biāozhǔn jiàocái quánxiào tōngyòng", "sentence_source": "generated"}, {"text": "这些工具在家里是大家通用的。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个账号我们一家人通用。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "通用型", "label": "复合"}], "register": "中性", "sense_fingerprint": "通用·东西不分人，大家都可以拿来用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c932acf-f05f-4d8d-ad7f-aaeceee4f32a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：这根充电线全家人都可以用，符合句意。"}, {"text": "专用", "is_correct": false, "explanation": "语义：「专用」指只供某人使用，与「全家人都」矛盾。"}, {"text": "通晓", "is_correct": false, "explanation": "搭配：「通晓」指人懂得某种知识，不能说充电线被「通晓」。"}, {"text": "通顺", "is_correct": false, "explanation": "搭配：「通顺」形容文字或语句，不能用来说充电线。"}], "explanations": {"通用": "通用：这根充电线全家人都可以用，符合句意。", "专用": "语义：「专用」指只供某人使用，与「全家人都」矛盾。", "通晓": "搭配：「通晓」指人懂得某种知识，不能说充电线被「通晓」。", "通顺": "搭配：「通顺」形容文字或语句，不能用来说充电线。"}, "sentence_index": 0, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种现象在学生中很通用。", "explanation": "这里应该用〈普遍〉。通用指东西大家都可以用，说现象的范围广要用普遍。"}, {"text": "我们俩有很多通用的爱好。", "explanation": "这里应该用〈共同〉。通用指东西大家都能用，两个人共有的爱好要用共同。"}, {"text": "这种错误在新手中很通用。", "explanation": "这里应该用〈常见〉。通用不用来说错误的多少，描述错误常见要用常见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：这张年票家人之间可以共同使用，符合句意。"}, {"text": "独立", "is_correct": false, "explanation": "语义：「独立」指不依赖他人，与「家人之间能……吗」的询问不搭，句子说不通。"}, {"text": "专属", "is_correct": false, "explanation": "配价：「专属」后一般要接「于」引出对象，单独用在「能……吗」中结构不完整。"}, {"text": "私有", "is_correct": false, "explanation": "语义：「私有」指归个人所有，与「公园年票」的公共性质矛盾。"}], "explanations": {"通用": "通用：这张年票家人之间可以共同使用，符合句意。", "独立": "语义：「独立」指不依赖他人，与「家人之间能……吗」的询问不搭，句子说不通。", "专属": "配价：「专属」后一般要接「于」引出对象，单独用在「能……吗」中结构不完整。", "私有": "语义：「私有」指归个人所有，与「公园年票」的公共性质矛盾。"}, "sentence_index": 6, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章写得很通用，连小孩都能看懂。", "explanation": "这里应该用〈通俗〉。通用指大家都能用，说文章容易懂要用「通俗」。"}, {"text": "这把牙刷是我个人通用的。", "explanation": "这里应该用〈专用〉。「通用」指大家都能用，只归个人使用的牙刷要用「专用」。"}, {"text": "这块私人土地是通用的。", "explanation": "这里应该用〈私有〉。「通用」指大家都可以用，私人土地只归一家或一个人所有，要用「私有」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款软件在各种手机上都被通用。", "corrected_sentence": "这款软件在各种手机上都通用。", "error_description": "错误：“通用”是形容词，不能用“被”引出被动；“都被通用”不成立，正确应为“在各种手机上都通用”，去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款数据线把各种品牌的手机上都能通用。", "corrected_sentence": "这款数据线在各种品牌的手机上都能通用。", "error_description": "错误：“把”的宾语应是被处置的人或事物，这里“把各种品牌的手机上”以地点作宾语，不成立；应改为“在各种品牌的手机上都能通用”，用“在”引出适用范围。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
