INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21936, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古时候用来写音乐的一种字，比如“工”和“尺”。", "primary_collocate": null, "pronunciation": "gōng chě", "ipa": "kʊŋ˥ ʈʂʰɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些字是工尺，不是普通的汉字。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷小时候学过工尺。", "target_word": "工尺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的人用工尺写歌。", "target_word": "工尺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书上有“上”“尺”“工”，这些都是工尺。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎么读工尺。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那张旧纸上写满了工尺。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古人记音用工尺，现在大多用音符。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他正在练习唱工尺，声音很好听。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本古书里的工尺，我一个也看不懂。", "target_word": "工尺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果你想唱古歌，就要先认识工尺。", "target_word": "工尺", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "工尺谱", "label": "复合"}], "register": "书面", "sense_fingerprint": "古时候用来写音乐的字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4722aed3-9c6c-4f5b-9332-20e838c26bdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工尺", "is_correct": true, "explanation": "正确：“这些字是工尺”指它们是古时用来记音乐的字。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不是字，「这些字是钢琴」说不通。"}, {"text": "笔画", "is_correct": false, "explanation": "语义：笔画是构成字的笔道，不等于字本身，与“这些字是”不符。"}, {"text": "玩意", "is_correct": false, "explanation": "语域：“玩意”是口语说法，与书面化的句子不相称。"}], "explanations": {"工尺": "正确：“这些字是工尺”指它们是古时用来记音乐的字。", "钢琴": "语义：钢琴是乐器，不是字，「这些字是钢琴」说不通。", "笔画": "语义：笔画是构成字的笔道，不等于字本身，与“这些字是”不符。", "玩意": "语域：“玩意”是口语说法，与书面化的句子不相称。"}, "sentence_index": 0, "correct_answer": "工尺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用工尺量了量桌子的长度。", "explanation": "语义：这里把“工尺”当成了〈尺〉（量长度的器具），但工尺指古时用来写音乐的字，不能用来量东西。"}, {"text": "桌上放着一位工尺。", "explanation": "量词：「位」用于人，工尺是记音的字，不能用「位」来数。"}, {"text": "他正在吃工尺。", "explanation": "语义：这里把“工尺”当成了〈食物〉来吃，但工尺是古时用来写音乐的字，不是食物，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工尺", "is_correct": true, "explanation": "正确：「古人记音用工尺」指古时用工尺这种字记音。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是演奏工具，不是记音的字，「记音用乐器」不通。"}, {"text": "扑克", "is_correct": false, "explanation": "语义：扑克是纸牌，与记音无关，句子不通。"}, {"text": "货色", "is_correct": false, "explanation": "语域：“货色”是口语贬义词，与这句书面叙述不相称。"}], "explanations": {"工尺": "正确：「古人记音用工尺」指古时用工尺这种字记音。", "乐器": "语义：乐器是演奏工具，不是记音的字，「记音用乐器」不通。", "扑克": "语义：扑克是纸牌，与记音无关，句子不通。", "货色": "语域：“货色”是口语贬义词，与这句书面叙述不相称。"}, "sentence_index": 6, "correct_answer": "工尺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在工尺上班，很辛苦。", "explanation": "语义：这里把“工尺”当成了〈单位〉（工作的场所），但工尺是古时用来写音乐的字，不指工作的地方。"}, {"text": "工尺是我的同事，人很和气。", "explanation": "语义：这里把“工尺”当成了〈朋友〉一类的人，但工尺是古时用来写音乐的字，不指人。"}, {"text": "他的工尺每月拿五千元。", "explanation": "语义：工尺指记音的字，不指工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "纸上写着几座工尺。", "corrected_sentence": "纸上写着几行工尺。", "error_description": "错误：「几座工尺」；正确：「几行工尺」。「座」用于山、楼房等大型固定物，不能用来数写下的文字；数成行的字要用「行」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于看了懂工尺。", "corrected_sentence": "他终于看懂了工尺。", "error_description": "错误：“看了懂”；正确：“看懂了”。结果补语“懂”应紧跟动词“看”，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21938, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "「现代」与「传统」构成反义，指当代的、新的做法或风尚。"}, {"text": "海洋", "is_correct": false, "explanation": "「海洋」指大面积的咸水区域，与「传统」没有反义或近义关系。"}, {"text": "花园", "is_correct": false, "explanation": "「花园」指种植花草的场所，与「传统」没有反义或近义关系。"}, {"text": "手机", "is_correct": false, "explanation": "「手机」指便携式通信工具，与「传统」没有反义或近义关系。"}], "correct_answer": "现代", "explanations": {"现代": "「现代」与「传统」构成反义，指当代的、新的做法或风尚。", "海洋": "「海洋」指大面积的咸水区域，与「传统」没有反义或近义关系。", "花园": "「花园」指种植花草的场所，与「传统」没有反义或近义关系。", "手机": "「手机」指便携式通信工具，与「传统」没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21938, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "「现代」与「传统」构成反义，指当代的、新的做法或风尚。"}, {"text": "桌子", "is_correct": false, "explanation": "「桌子」指供人放置物品的家具，与「传统」没有反义或近义关系。"}, {"text": "河流", "is_correct": false, "explanation": "「河流」指流动的水体，与「传统」没有反义或近义关系。"}, {"text": "公园", "is_correct": false, "explanation": "「公园」指供人游览休息的场所，与「传统」没有反义或近义关系。"}], "correct_answer": "现代", "explanations": {"现代": "「现代」与「传统」构成反义，指当代的、新的做法或风尚。", "桌子": "「桌子」指供人放置物品的家具，与「传统」没有反义或近义关系。", "河流": "「河流」指流动的水体，与「传统」没有反义或近义关系。", "公园": "「公园」指供人游览休息的场所，与「传统」没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21938, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很长时间以来，大家一直这样做事情、想问题的方式。", "primary_collocate": null, "pronunciation": "chuán tǒng", "ipa": "ʈʂʰwan˧˥ tʰʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "春节吃饺子是我们家的传统。", "target_word": "传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人有尊敬老人的传统。", "target_word": "传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子保持着古老的传统。", "target_word": "传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不想改变学校的传统。", "target_word": "传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年中秋节全家一起吃月饼，这是我们的传统。", "target_word": "传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人有时不喜欢旧传统。", "target_word": "传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷很重视家里的传统。", "target_word": "传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个传统已经有一百多年了。", "target_word": "传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把好的传统留下来。", "target_word": "传统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我的家乡，结婚要办三天酒席，这是老传统。", "target_word": "传统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傳統", "label": "繁体"}, {"form": "传统文化", "label": "复合"}, {"form": "传统节日", "label": "复合"}], "register": "中性", "sense_fingerprint": "长期形成并一代代延续的做事和想事的方式；名词义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33c7f637-619d-49ba-80ef-a53edb7b3254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传统", "is_correct": true, "explanation": "「传统」指长期延续的做法，「春节吃饺子是我们家的传统」语义通顺。"}, {"text": "财产", "is_correct": false, "explanation": "语义：「财产」指拥有的物质财富，春节吃饺子不是财产。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」指岁数，不能说春节吃饺子是岁数。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」只用于人或动物的重量，不能与「我们家的」组合表示习俗。"}], "explanations": {"传统": "「传统」指长期延续的做法，「春节吃饺子是我们家的传统」语义通顺。", "财产": "语义：「财产」指拥有的物质财富，春节吃饺子不是财产。", "年龄": "语义：「年龄」指岁数，不能说春节吃饺子是岁数。", "体重": "搭配：「体重」只用于人或动物的重量，不能与「我们家的」组合表示习俗。"}, "sentence_index": 0, "correct_answer": "传统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的传统很快，十分钟就能做好。", "explanation": "这里应该用〈速度〉。「传统」指长期延续的做法，不能用来形容快慢；说做事快要用「速度」。"}, {"text": "他有丰富的传统。", "explanation": "这里应该用〈经验〉。「传统」指长期延续的做法，个人积累的知识要用「经验」。"}, {"text": "他这学期的传统很好。", "explanation": "这里应该用〈成绩〉。「传统」指很长时间以来大家延续的做法，不用来指某学期的学习结果；学习的好坏要用「成绩」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传统", "is_correct": true, "explanation": "「传统」指长期延续的做法，「爷爷很重视家里的传统」语义通顺。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：「身高」只用于人或物体的高度，不能与「家里的」组合表示重视的对象。"}, {"text": "厚度", "is_correct": false, "explanation": "语义：「厚度」指物体上下或前后之间的距离，不能用来指家里的做法。"}, {"text": "体积", "is_correct": false, "explanation": "语义：「体积」指物体占据的空间大小，与「重视家里的」组合说不通。"}], "explanations": {"传统": "「传统」指长期延续的做法，「爷爷很重视家里的传统」语义通顺。", "身高": "搭配：「身高」只用于人或物体的高度，不能与「家里的」组合表示重视的对象。", "厚度": "语义：「厚度」指物体上下或前后之间的距离，不能用来指家里的做法。", "体积": "语义：「体积」指物体占据的空间大小，与「重视家里的」组合说不通。"}, "sentence_index": 6, "correct_answer": "传统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家有一根传统，每年过年都一起吃饺子。", "explanation": "这里应该用〈个〉或〈种〉。〈根〉用于细长的物体，「传统」是抽象的做法，不能用〈根〉计量。"}, {"text": "这个村子有一只传统，流传了很多年。", "explanation": "这里应该用〈个〉或〈种〉。〈只〉用于动物或成对物品之一，「传统」不能用〈只〉计量。"}, {"text": "我们学校有一把传统，已经保留了五十年。", "explanation": "这里应该用〈个〉或〈种〉。〈把〉用于有柄的器具，「传统」是抽象的做法，不能用〈把〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要修理民族的传统。", "corrected_sentence": "我们要保持民族的传统。", "error_description": "错误：「修理」用于坏了的机器、物品，不能与抽象的「传统」搭配。正确：「保持」，即「保持民族的传统」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个家庭保留着一座古老的传统。", "corrected_sentence": "这个家庭保留着一种古老的传统。", "error_description": "错误：「座」用于山、房屋等大型固定物，不能计量「传统」。正确：「种」，即「一种古老的传统」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
