INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "五线谱是写音乐用的，有五条线。", "primary_collocate": null, "pronunciation": "wǔ xiàn pǔ", "ipa": "u˨˩˦ ɕjɛn˥˩ pʰu˨˩˦", "syllable_count": 3, "sentences": [{"text": "这首歌的五线谱在钢琴上放着。", "target_word": "五线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在学看五线谱。", "target_word": "五线谱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师把五线谱写在黑板上。", "target_word": "五线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五线谱有五条线，音符写在线上。", "target_word": "五线谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他学了三年钢琴，会看五线谱了。", "target_word": "五线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友画过五线谱，也认识音符。", "target_word": "五线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你翻开书，看第一页的五线谱。", "target_word": "五线谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我买了一本五线谱，想练习弹吉他。", "target_word": "五线谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位歌手不太会读五线谱，只会听音乐学歌。", "target_word": "五线谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五线谱上的小黑点，就是音符。", "target_word": "五线谱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "五線譜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写音乐用的、有五条线的谱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4722aed3-9c6c-4f5b-9332-20e838c26bdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "五线谱", "is_correct": true, "explanation": "正确。五线谱是写音乐用的谱子，放在钢琴上很常见，句中“这首歌的”指的就是它。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“这首歌的”后应接与歌相关的东西，钥匙与歌无关。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时器具，与歌无关，「这首歌的闹钟」说不通。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是写音乐的东西，“这首歌的饼干”说不通。"}], "explanations": {"五线谱": "正确。五线谱是写音乐用的谱子，放在钢琴上很常见，句中“这首歌的”指的就是它。", "钥匙": "搭配：“这首歌的”后应接与歌相关的东西，钥匙与歌无关。", "闹钟": "语义：闹钟是计时器具，与歌无关，「这首歌的闹钟」说不通。", "饼干": "语义：饼干不是写音乐的东西，“这首歌的饼干”说不通。"}, "sentence_index": 0, "correct_answer": "五线谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子在五线谱上练习写字。", "explanation": "这里应该用〈田字格〉。五线谱是写音乐用的谱子，不能用来练习写汉字；练写字要用田字格。"}, {"text": "我买了一台五线谱，准备学钢琴。", "explanation": "这里应该用〈张〉。“台”用于机器，五线谱是纸质谱子，应说“一张五线谱”。"}, {"text": "这首歌的五线谱只用1到7的数字写成。", "explanation": "这里应该用〈简谱〉。五线谱用五条线和音符表示音高；只用1到7的数字写成的是简谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "五线谱", "is_correct": true, "explanation": "正确。五线谱可以印在书的第一页，句中“看第一页的”指的就是它。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不印在书页上，“看第一页的手机”说不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时器具，不会印在书的第一页上。"}, {"text": "唱片", "is_correct": false, "explanation": "搭配：“第一页”指书页上的印刷内容，唱片不是印刷品，不能这样搭配。"}], "explanations": {"五线谱": "正确。五线谱可以印在书的第一页，句中“看第一页的”指的就是它。", "手机": "语义：手机不印在书页上，“看第一页的手机”说不通。", "闹钟": "语义：闹钟是计时器具，不会印在书的第一页上。", "唱片": "搭配：“第一页”指书页上的印刷内容，唱片不是印刷品，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "五线谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿着五线谱，很快找到了车站。", "explanation": "这里应该用〈地图〉。五线谱是写音乐用的谱子，不标路线；找路要用地图。"}, {"text": "她每天在五线谱上写日记。", "explanation": "这里应该用〈日记本〉。五线谱是写音乐用的，不能用来写日记；写日记要用日记本。"}, {"text": "她按照五线谱，一步一步做了蛋糕。", "explanation": "这里应该用〈食谱〉。五线谱是写音乐用的谱子，不能用来做蛋糕；做蛋糕要照食谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈五线谱收进了抽屉。", "corrected_sentence": "妈妈把五线谱收进了抽屉。", "error_description": "错误：妈妈与五线谱之间缺少处置介词「把」。应说「妈妈把五线谱收进了抽屉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他第一次读懂了一台五线谱。", "corrected_sentence": "他第一次读懂了五线谱。", "error_description": "错误：多加了量词「台」。「台」用于机器等，五线谱是纸质乐谱，不能这样数；应直接说「读懂了五线谱」，或说「一张五线谱」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be863b15-4df9-42e1-87a3-ffea099293aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
