INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乐器是能发出好听声音的工具，比如钢琴、鼓。", "primary_collocate": null, "pronunciation": "yuè qì", "ipa": "ɥɛ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "钢琴是一种乐器。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鼓也是乐器。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢什么乐器？", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有两件乐器。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个乐器的声音很好听。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用这件乐器演奏了一首歌。", "target_word": "乐器", "complexity_tier": "T3", "furigana": "tā yòng zhè jiàn yuèqì yǎnzòu le yì shǒu gē", "sentence_source": "generated"}, {"text": "小孩在音乐教室里学乐器。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笛子是一种很小的乐器。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸买了一件新乐器。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐器店里有钢琴和鼓。", "target_word": "乐器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件乐器", "label": "量词"}, {"form": "一种乐器", "label": "量词"}, {"form": "樂器", "label": "繁体"}, {"form": "民族乐器", "label": "复合"}], "register": "中性", "sense_fingerprint": "能发出好听声音的工具，如钢琴、鼓", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8f5f600-ca28-4321-b5a3-d94418e5ffb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21946, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "乐器", "is_correct": true, "explanation": "乐器：能发出好听声音的工具，如钢琴、鼓。"}, {"text": "玉器", "is_correct": false, "explanation": "yù（第四声）与 yuè（第四声）韵母不同，意思是玉石制成的器物。"}, {"text": "跃起", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是猛然跳起。"}, {"text": "血气", "is_correct": false, "explanation": "xuè 与 yuè 声母不同，意思是精力、朝气，是较书面的词。"}], "explanations": {"乐器": "乐器：能发出好听声音的工具，如钢琴、鼓。", "玉器": "yù（第四声）与 yuè（第四声）韵母不同，意思是玉石制成的器物。", "跃起": "qǐ（第三声）与 qì（第四声）声调不同，意思是猛然跳起。", "血气": "xuè 与 yuè 声母不同，意思是精力、朝气，是较书面的词。"}, "sentence_index": null, "correct_answer": "乐器"}, "level_3": {"options": [{"text": "乐器", "is_correct": true, "explanation": "乐器：能发出好听声音的工具，钢琴属于这一类。"}, {"text": "食物", "is_correct": false, "explanation": "语义：钢琴不是食物，“钢琴是一种食物”说法不成立。"}, {"text": "植物", "is_correct": false, "explanation": "语义：钢琴是人造的器具，不是植物，这样归类错误。"}, {"text": "乐章", "is_correct": false, "explanation": "搭配：“乐章”指乐曲的一个段落，不能用来把钢琴归为一类。"}], "explanations": {"乐器": "乐器：能发出好听声音的工具，钢琴属于这一类。", "食物": "语义：钢琴不是食物，“钢琴是一种食物”说法不成立。", "植物": "语义：钢琴是人造的器具，不是植物，这样归类错误。", "乐章": "搭配：“乐章”指乐曲的一个段落，不能用来把钢琴归为一类。"}, "sentence_index": 0, "correct_answer": "乐器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有两本乐器。", "explanation": "这里应该用〈件〉或〈种〉。乐器用“件”或“种”计量，“本”用于书籍等。"}, {"text": "这件乐器能切菜。", "explanation": "这里应该用〈工具〉。乐器用来发声，“切菜”是工具的用途，乐器不能切菜。"}, {"text": "我家有两条乐器。", "explanation": "这里应该用〈件〉或〈种〉。“条”用于细长的东西，乐器不用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21946, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "乐器", "is_correct": true, "explanation": "乐器：能发出好听声音的工具，如钢琴、鼓。"}, {"text": "月季", "is_correct": false, "explanation": "jì（第四声）与 qì（第四声）声母不同，意思是一种花。"}, {"text": "阅历", "is_correct": false, "explanation": "lì 与 qì 声母不同，意思是人生经历、见识。"}, {"text": "跃起", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，意思是猛然跳起。"}], "explanations": {"乐器": "乐器：能发出好听声音的工具，如钢琴、鼓。", "月季": "jì（第四声）与 qì（第四声）声母不同，意思是一种花。", "阅历": "lì 与 qì 声母不同，意思是人生经历、见识。", "跃起": "qǐ（第三声）与 qì（第四声）声调不同，意思是猛然跳起。"}, "sentence_index": null, "correct_answer": "乐器"}, "level_3": {"options": [{"text": "乐器", "is_correct": true, "explanation": "乐器：学习演奏的对象，与“音乐教室”的语境相合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：音乐教室里学的是音乐，不是游泳，句子读起来不通。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪与音乐教室无关，“在音乐教室里学烹饪”说法不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语境：音乐教室里学的是乐器，学厨师与这一场景不符，句意不通。"}], "explanations": {"乐器": "乐器：学习演奏的对象，与“音乐教室”的语境相合。", "游泳": "语义：音乐教室里学的是音乐，不是游泳，句子读起来不通。", "烹饪": "语义：烹饪与音乐教室无关，“在音乐教室里学烹饪”说法不通。", "厨师": "语境：音乐教室里学的是乐器，学厨师与这一场景不符，句意不通。"}, "sentence_index": 6, "correct_answer": "乐器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件乐器很难读。", "explanation": "这里应该用〈乐谱〉。“读”的对象是乐谱，乐器不能说读。"}, {"text": "我买了一块乐器，回家练习。", "explanation": "这里应该用〈件〉或〈种〉。“块”用于成块的东西，乐器不用“块”。"}, {"text": "这座乐器很大，房间放不下。", "explanation": "这里应该用〈件〉或〈种〉。“座”用于山、楼等大型固定物，乐器不用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹学一只乐器已经两年了。", "corrected_sentence": "妹妹学一种乐器已经两年了。", "error_description": "量词错误：“乐器”应用“种”或“件”计量，“只”用于动物等，不能用于乐器，应说“一种乐器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的乐器们都很贵。", "corrected_sentence": "他的乐器都很贵。", "error_description": "多加了“们”：“乐器”是无生名词，后面不能加“们”表示复数，应说“乐器都……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
