INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "仔细看或想，来知道更多东西。", "primary_collocate": null, "pronunciation": "yán jiū", "ipa": "jɛn˧˥ tɕjoʊ˥", "syllable_count": 2, "sentences": [{"text": "医生每天都在研究这种药的作用。", "target_word": "研究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们正在研究这个问题。", "target_word": "研究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师研究了很多年中国历史。", "target_word": "研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想研究怎么让小孩爱读书。", "target_word": "研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事我要回家研究一下。", "target_word": "研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们研究过这种鱼的生活。", "target_word": "研究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在研究新的办法。", "target_word": "研究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥爱研究电脑，常常研究到半夜。", "target_word": "研究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先研究地图，再决定怎么走。", "target_word": "研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家研究着明天的计划。", "target_word": "研究", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "研究了", "label": "完成体"}, {"form": "研究过", "label": "经历体"}, {"form": "研究着", "label": "持续体"}, {"form": "研究生", "label": "复合词"}, {"form": "研究所", "label": "复合词"}], "register": "中性", "sense_fingerprint": "认真调查思考某个事物，想弄清楚它", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b72803e1-d339-466f-98b7-61dea376201f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究", "is_correct": true, "explanation": "正确。“研究”指仔细琢磨、探求，与“每天都在……这种药的作用”相符。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”指制造东西，“作用”不能被生产，应说“产生作用”。"}, {"text": "分配", "is_correct": false, "explanation": "语义：“分配”指按份额分派，与弄清药的作用无关。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”指不再坚持，与“每天都在”进行的工作不符，句意说不通。"}], "explanations": {"研究": "正确。“研究”指仔细琢磨、探求，与“每天都在……这种药的作用”相符。", "生产": "搭配：“生产”指制造东西，“作用”不能被生产，应说“产生作用”。", "分配": "语义：“分配”指按份额分派，与弄清药的作用无关。", "放弃": "语义：“放弃”指不再坚持，与“每天都在”进行的工作不符，句意说不通。"}, "sentence_index": 0, "correct_answer": "研究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每天研究教室，很辛苦。", "explanation": "这里应该用〈打扫〉。研究指仔细琢磨问题，不能用于具体的清扫动作；清扫教室要用打扫。"}, {"text": "妈妈每天研究生病的弟弟，帮他擦身换衣服。", "explanation": "这里应该用〈照顾〉。研究指仔细琢磨问题，不表示照料病人；帮病人擦身、换衣要用照顾。"}, {"text": "他把窗户研究得很干净。", "explanation": "这里应该用〈擦〉。研究不能使物体变干净，擦窗户要用擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究", "is_correct": true, "explanation": "正确。“研究”指仔细探求，与“在……新的办法”相符。"}, {"text": "丢掉", "is_correct": false, "explanation": "语义：“丢掉”指失去，与“在……新的办法”的动作相反，句意说不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”一般接衣服、鞋帽，不能与“办法”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”一般接食物或药物，“办法”不能被吃。"}], "explanations": {"研究": "正确。“研究”指仔细探求，与“在……新的办法”相符。", "丢掉": "语义：“丢掉”指失去，与“在……新的办法”的动作相反，句意说不通。", "穿": "搭配：“穿”一般接衣服、鞋帽，不能与“办法”搭配。", "吃": "搭配：“吃”一般接食物或药物，“办法”不能被吃。"}, "sentence_index": 6, "correct_answer": "研究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在食堂研究了一大碗面，吃得很饱。", "explanation": "这里应该用〈吃〉。研究指仔细看或想，不表示吃东西；吃面、吃饭要用吃。"}, {"text": "她每天研究校服去上学。", "explanation": "这里应该用〈穿〉。研究不能表示把衣服穿在身上，穿校服要用穿。"}, {"text": "他去超市研究了三斤苹果，付了钱就走了。", "explanation": "这里应该用〈买〉。研究指仔细看或想，不表示付钱购买；买苹果要用买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们研究很清楚，大家都明白了。", "corrected_sentence": "他们研究得很清楚，大家都明白了。", "error_description": "补语标记错误：“研究”后接描述结果的补语要用“得”，应说“研究得很清楚”，不能省略“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们研究过过这个方法。", "corrected_sentence": "我们研究过这个方法。", "error_description": "体标错误：经历体“过”只用一次，应说“研究过这个方法”，不能重复“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
