INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "知道一件事是什么意思，比如你听懂妈妈在说什么。", "primary_collocate": null, "pronunciation": "lǐ jiě", "ipa": "li˨˩˦ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师说得很慢，我能理解。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的专业术语太多，我看了半天也没理解。", "target_word": "理解", "complexity_tier": "T3", "furigana": "zhè piān wénzhāng de zhuānyè shùyǔ tài duō, wǒ kànle bàntiān yě méi lǐjiě", "sentence_source": "generated"}, {"text": "他不太理解妈妈的话。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我理解你为什么生气。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很难理解。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都理解了他的意思。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还不理解大人的工作。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用图表解释了病情，我终于理解了。", "target_word": "理解", "complexity_tier": "T3", "furigana": "yīshēng yòng túbiǎo jiěshìle bìngqíng, wǒ zhōngyú lǐjiě le", "sentence_source": "generated"}, {"text": "我很难理解他的想法。", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你理解这个句子的意思吗？", "target_word": "理解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "理解了", "label": "体标"}, {"form": "理解过", "label": "体标"}], "register": "中性", "sense_fingerprint": "明白某事的意思或某人的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d81d48-6f38-42b1-91d4-5cab678d6582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "理解", "is_correct": true, "explanation": "正确答案。理解 lǐ jiě，意思是明白意思或想法。"}, {"text": "礼节", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是礼节。"}, {"text": "历届", "is_correct": false, "explanation": "lì jiè 两个音节的声调都与 lǐ jiě 不同，意思是历次届别。"}, {"text": "例解", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）声调不同，意思是举例解释。"}], "explanations": {"理解": "正确答案。理解 lǐ jiě，意思是明白意思或想法。", "礼节": "jié（第二声）与 jiě（第三声）声调不同，意思是礼节。", "历届": "lì jiè 两个音节的声调都与 lǐ jiě 不同，意思是历次届别。", "例解": "lì（第四声）与 lǐ（第三声）声调不同，意思是举例解释。"}, "sentence_index": null, "correct_answer": "理解"}, "level_3": {"options": [{"text": "理解", "is_correct": true, "explanation": "“理解”指明白对方的意思，与“老师说得很慢”“我能”相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与“老师说得很慢”的语境不合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与听讲的语境无关，“我能游泳”接在句末句意不通。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”需要带具体的受事宾语，“我能修理”后面没有对象，句意也不通。"}], "explanations": {"理解": "“理解”指明白对方的意思，与“老师说得很慢”“我能”相符。", "拒绝": "语义：“拒绝”表示不接受，与“老师说得很慢”的语境不合。", "游泳": "语义：“游泳”与听讲的语境无关，“我能游泳”接在句末句意不通。", "修理": "配价：“修理”需要带具体的受事宾语，“我能修理”后面没有对象，句意也不通。"}, "sentence_index": 0, "correct_answer": "理解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我理解他的电话号码。", "explanation": "这里应该用〈知道〉。理解侧重明白意思或想法，电话号码这类具体信息要说知道。"}, {"text": "工人正在理解那座房子。", "explanation": "这里应该用〈修理〉。理解用于意思、想法，修理用于房屋、机器等实物。"}, {"text": "妈妈每天理解全家的饭。", "explanation": "这里应该用〈煮〉。理解不能作用于食物，做饭要说煮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理解", "is_correct": true, "explanation": "“理解”指明白句中的意思或道理，与“孩子还不”“大人的工作”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃大人的工作”。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”的宾语应是产品，工作不能被生产。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是咬合的动作，与“不理解”的意思毫不相关。"}], "explanations": {"理解": "“理解”指明白句中的意思或道理，与“孩子还不”“大人的工作”相符。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃大人的工作”。", "生产": "搭配：“生产”的宾语应是产品，工作不能被生产。", "咬": "语义：“咬”是咬合的动作，与“不理解”的意思毫不相关。"}, "sentence_index": 6, "correct_answer": "理解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天理解房间。", "explanation": "这里应该用〈打扫〉。理解用于意思或想法，清理房间要说打扫。"}, {"text": "我的胃能理解食物。", "explanation": "这里应该用〈消化〉。理解用于意思、想法，食物要说消化。"}, {"text": "我每天理解花。", "explanation": "这里应该用〈浇〉。理解不能用于植物，给花供水要说浇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子理解了很慢。", "corrected_sentence": "这个孩子理解得很慢。", "error_description": "错误在于“了”与程度补语“很慢”不能同用。“理解”后接程度补语要用“得”，应说“理解得很慢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈终于理解了过孩子的心情。", "corrected_sentence": "妈妈终于理解了孩子的心情。", "error_description": "错误在于“了”和“过”不能叠用于同一动词。“终于”表示动作达成，应只用“了”，应说“妈妈终于理解了孩子的心情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
