INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21954, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "弹钢琴时，每个手指怎么动的方法。", "primary_collocate": null, "pronunciation": "zhǐ fǎ", "ipa": "ʈʂɨ˨˩˦ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "弹钢琴要先学好指法。", "target_word": "指法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴老师教我新的指法。", "target_word": "指法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子的指法，我还不熟。", "target_word": "指法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谱子上的小数字表示指法。", "target_word": "指法", "complexity_tier": "T3", "furigana": "pǔ zi shàng de xiǎo shù zì biǎo shì zhǐ fǎ.", "sentence_source": "generated"}, {"text": "你的指法对了，弹得就很快。", "target_word": "指法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹钢琴时，左手的指法比右手难。", "target_word": "指法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钢琴的指法就是每个手指怎么动。", "target_word": "指法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天练习钢琴指法半小时。", "target_word": "指法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她弹钢琴的指法很漂亮。", "target_word": "指法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子先练简单的指法，再弹曲子。", "target_word": "指法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种指法", "label": "量词"}, {"form": "一套指法", "label": "量词"}], "register": "中性", "sense_fingerprint": "弹钢琴时每个手指的动作方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8f5f600-ca28-4321-b5a3-d94418e5ffb4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21954, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指法", "is_correct": true, "explanation": "指法是弹钢琴时每个手指怎么动的方法，是这里要听的词。"}, {"text": "制法", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是制作的方法。"}, {"text": "织法", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是编织的方法。"}, {"text": "执法", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是执行法律。"}], "explanations": {"指法": "指法是弹钢琴时每个手指怎么动的方法，是这里要听的词。", "制法": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是制作的方法。", "织法": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是编织的方法。", "执法": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是执行法律。"}, "sentence_index": null, "correct_answer": "指法"}, "level_3": {"options": [{"text": "指法", "is_correct": true, "explanation": "指法是弹钢琴时手指的动作方法，学好它才能弹好，句意通顺。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词是唱词，与弹钢琴的技术无关，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是弹钢琴需要学的内容，句意不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“学好”后面接的是技能或知识，“脾气”不能这样去学，搭配不当。"}], "explanations": {"指法": "指法是弹钢琴时手指的动作方法，学好它才能弹好，句意通顺。", "歌词": "语义：歌词是唱词，与弹钢琴的技术无关，句意不通。", "天气": "语义：天气不是弹钢琴需要学的内容，句意不通。", "脾气": "搭配：“学好”后面接的是技能或知识，“脾气”不能这样去学，搭配不当。"}, "sentence_index": 0, "correct_answer": "指法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "歌手练习了很久的指法，每句都很稳。", "explanation": "这里应该用〈唱法〉。唱法指歌唱的方法；指法专指钢琴等乐器上手指怎么动，不用于唱歌。"}, {"text": "这位画家的指法很精湛，作品很有名。", "explanation": "这里应该用〈技法〉。技法指绘画、书法等的技巧；指法专指弹琴或打字时手指的运用，不用于绘画。"}, {"text": "这道菜的指法很香。", "explanation": "这里应该用〈味道〉。味道是食物给人的感觉；指法是弹琴时手指怎么动的方法，不能说香。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指法", "is_correct": true, "explanation": "指法就是手指动作的方法，“钢琴的指法”句意通顺。"}, {"text": "琴键", "is_correct": false, "explanation": "语义：琴键是琴的部件，不是手指动作的方法，句意不通。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量是声音的大小，与手指怎么动无关，句意不通。"}, {"text": "音阶", "is_correct": false, "explanation": "搭配：“钢琴的音阶”指音的排列，不能用来定义手指的动作，搭配不当。"}], "explanations": {"指法": "指法就是手指动作的方法，“钢琴的指法”句意通顺。", "琴键": "语义：琴键是琴的部件，不是手指动作的方法，句意不通。", "音量": "语义：音量是声音的大小，与手指怎么动无关，句意不通。", "音阶": "搭配：“钢琴的音阶”指音的排列，不能用来定义手指的动作，搭配不当。"}, "sentence_index": 6, "correct_answer": "指法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做饭时的指法很细腻。", "explanation": "这里应该用〈刀工〉。指法专指弹琴或打字时手指的运用，做饭时不用“指法”。"}, {"text": "老师用指法示意我停下来。", "explanation": "这里应该用〈手势〉。手势是用手示意的姿态；指法是手指的运用方法，不用来示意。"}, {"text": "指法是一种乐器，靠敲击发声。", "explanation": "这里应该用〈钢琴〉。钢琴靠敲击琴键发声；指法是手指怎么动的方法，本身不发声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我学了一首指法。", "corrected_sentence": "我学了一种指法。", "error_description": "量词错误：“指法”应用“种”或“套”计量，“首”用于歌曲、诗词，不能用于指法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她这个月学会了两本新的指法。", "corrected_sentence": "她这个月学会了两种新的指法。", "error_description": "量词错误：错误形式为“两本”，正确形式为“两种”。“指法”的量词是“种”或“套”，“本”用于书本，不能用于指法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340b5352-871f-4fd4-8a70-a1c2dacdf6ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
