INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21956, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一样东西有多重要或者有多好。", "primary_collocate": null, "pronunciation": "jià zhí", "ipa": "tɕja˥˩ ʈʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这本书很有价值，值得你读一读。", "target_word": "价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画的价值很高。", "target_word": "价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得这份工作没有什么价值。", "target_word": "价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老照片对我们家很有价值。", "target_word": "价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法有很大的价值。", "target_word": "价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "友谊的价值，不能用钱来算。", "target_word": "价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件旧东西很有收藏价值。", "target_word": "价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道这个想法有没有价值。", "target_word": "价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究对医生有很大的价值。", "target_word": "价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的价值，在沙漠里最容易看出来。", "target_word": "价值", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "价值观", "label": "复合"}, {"form": "有价值", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物的重要程度或好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价值", "is_correct": true, "explanation": "正确。“很有价值”表示“值得读”，与“值得你读一读”的语境一致。"}, {"text": "力气", "is_correct": false, "explanation": "语义：“力气”指身体的力量，书不能“很有力气”，与“值得你读一读”也不搭。"}, {"text": "价钱", "is_correct": false, "explanation": "搭配：“很有”后面不接“价钱”，应说“价钱很高”，“很有价钱”不成立。"}, {"text": "礼貌", "is_correct": false, "explanation": "语义：“礼貌”是人的言行举止，书本身不能有礼貌，这个词不能修饰“这本书”。"}], "explanations": {"价值": "正确。“很有价值”表示“值得读”，与“值得你读一读”的语境一致。", "力气": "语义：“力气”指身体的力量，书不能“很有力气”，与“值得你读一读”也不搭。", "价钱": "搭配：“很有”后面不接“价钱”，应说“价钱很高”，“很有价钱”不成立。", "礼貌": "语义：“礼貌”是人的言行举止，书本身不能有礼貌，这个词不能修饰“这本书”。"}, "sentence_index": 0, "correct_answer": "价值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的价值很漂亮，我很喜欢。", "explanation": "这里应该用〈样式〉。“价值”指重要程度或好处，不用来形容外观，应说“样式很漂亮”。"}, {"text": "这箱苹果的价值很重，我一个人搬不动。", "explanation": "这里应该用〈重量〉。“价值”不指物体的重量，描述苹果重不能用“价值”。"}, {"text": "他把价值挂在了墙上。", "explanation": "这里应该用〈画〉。“价值”是抽象的重要程度，不是能挂在墙上的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价值", "is_correct": true, "explanation": "正确。“很有收藏价值”表示值得收藏，与“旧东西”的语境相符。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，东西不能“很有收藏脾气”，语境不通。"}, {"text": "费用", "is_correct": false, "explanation": "搭配：“收藏”后面不接“费用”，“费用”指开支，“很有”也不能修饰它。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”属于人或动物的性情特点，旧东西没有性格，不能与“收藏”构成这样的说法。"}], "explanations": {"价值": "正确。“很有收藏价值”表示值得收藏，与“旧东西”的语境相符。", "脾气": "语义：“脾气”指人的性情，东西不能“很有收藏脾气”，语境不通。", "费用": "搭配：“收藏”后面不接“费用”，“费用”指开支，“很有”也不能修饰它。", "性格": "语义：“性格”属于人或动物的性情特点，旧东西没有性格，不能与“收藏”构成这样的说法。"}, "sentence_index": 6, "correct_answer": "价值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这颗钻石的价值很亮，我们都很喜欢。", "explanation": "这里应该用〈光泽〉。“价值”指重要程度或好处，不用来形容光亮，应说“光泽很亮”。"}, {"text": "他的价值比我矮一头。", "explanation": "这里应该用〈身高〉。“价值”不用于比较身高，这里用“价值”完全不通。"}, {"text": "妈妈把这份价值放进了冰箱。", "explanation": "这里应该用〈食物〉。“价值”是抽象的概念，不能被放进冰箱，这里误用了它的所指。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件东西很价值，我会保存好。", "corrected_sentence": "这件东西很有价值，我会保存好。", "error_description": "错误形式是“很价值”，正确形式是“很有价值”。“价值”是名词，“很”后面不能直接接它，要用“很有价值”来表示值得重视。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这幅老照片很收藏价值，你可以留着。", "corrected_sentence": "这幅老照片很有收藏价值，你可以留着。", "error_description": "省略了“有”：“很有”是固定搭配，“很有收藏价值”表示值得收藏，不能省略“有”，应说“很有收藏价值”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
