INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用相机或电脑画出来的样子。", "primary_collocate": null, "pronunciation": "tú xiàng", "ipa": "tʰu˧˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这台相机拍出来的图像非常清楚。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师用软件生成了一张漂亮的图像。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里的图像文件太大，发不出去。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看了病人的肺部图像。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以把图像变得更亮。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相机坏了，拍到的图像全是黑的。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里的图像放大以后会变模糊。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生用电脑做出了一个立体图像。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图像是我昨天用相机拍的。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏里的图像越来越像真的。", "target_word": "图像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张图像", "label": "量词"}, {"form": "一幅图像", "label": "量词"}, {"form": "圖像", "label": "繁体"}, {"form": "图像处理", "label": "复合"}], "register": "中性", "sense_fingerprint": "相机拍摄或电脑制作出来的图", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf1fc5f1-3de3-49b7-bd2c-bca5dafc47e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图像", "is_correct": true, "explanation": "正确：相机拍出来的影像就是图像，“非常清楚”描述的正是图像。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“拍”的对象是看得见的物象，不说拍出“味道”。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量是物体的属性，相机拍不出重量，句子说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人或物的分量，相机拍不出来，句子不成立。"}], "explanations": {"图像": "正确：相机拍出来的影像就是图像，“非常清楚”描述的正是图像。", "味道": "搭配：“拍”的对象是看得见的物象，不说拍出“味道”。", "重量": "语义：重量是物体的属性，相机拍不出重量，句子说不通。", "体重": "语义：体重是人或物的分量，相机拍不出来，句子不成立。"}, "sentence_index": 0, "correct_answer": "图像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我听到了窗外的图像。", "explanation": "这里应该用〈声音〉。图像是看得见的影像，不能“听到”。"}, {"text": "他在餐厅点的图像很好吃。", "explanation": "这里应该用〈菜〉。餐厅点的是菜，图像指相机或电脑产生的影像，不能吃。"}, {"text": "这台相机拍了一条图像。", "explanation": "这里量词用错。图像要用〈张〉或〈幅〉计量，〈条〉用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图像", "is_correct": true, "explanation": "正确：电脑里的影像放大后会失真变模糊，指的正是图像。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格不是可以看见的东西，放大后不会变模糊。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“放大”用于能变大、可看见的东西，不说放大感情。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气看不见，电脑里放大不了，也不会变模糊。"}], "explanations": {"图像": "正确：电脑里的影像放大后会失真变模糊，指的正是图像。", "性格": "语义：性格不是可以看见的东西，放大后不会变模糊。", "感情": "搭配：“放大”用于能变大、可看见的东西，不说放大感情。", "脾气": "语义：脾气看不见，电脑里放大不了，也不会变模糊。"}, "sentence_index": 6, "correct_answer": "图像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的图像很好听。", "explanation": "这里应该用〈旋律〉。歌好听说的是旋律，图像指相机或电脑产生的影像，不是用来听的。"}, {"text": "山上的图像很美。", "explanation": "这里应该用〈景象〉。山上的景色叫景象，图像指拍出来或做出来的影像。"}, {"text": "这个图像写得很长，我看不懂。", "explanation": "这里应该用〈文章〉。文章是用文字写出来的，图像是相机或电脑产生的影像，不能用“写”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台相机拍出了一张非常清楚图像。", "corrected_sentence": "这台相机拍出了一张非常清楚的图像。", "error_description": "定语错误：“非常清楚”这样带程度副词的形容词短语修饰“图像”时，后面必须加“的”，应说“非常清楚的图像”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电脑里有一台图像很清楚。", "corrected_sentence": "电脑里有一张图像很清楚。", "error_description": "量词错误：“图像”应该用“张”或“幅”计量，“台”用于机器，不能数图像。应说“一张图像”，不说“一台图像”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
