INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21960, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "图形就是画出来的样子，比如圆形、方形。", "primary_collocate": null, "pronunciation": "tú xíng", "ipa": "tʰu˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小明在纸上画了很多图形。", "target_word": "图形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆形和方形是最常见的图形。", "target_word": "图形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个图形看起来像一座小房子。", "target_word": "图形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们说出图形的名字。", "target_word": "图形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用尺子画出一个整齐的图形。", "target_word": "图形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上贴着几个彩色图形。", "target_word": "图形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢画有趣的图形。", "target_word": "图形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个图形是三角形？", "target_word": "图形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把图形涂成蓝色。", "target_word": "图形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们玩积木，拼出不同的图形。", "target_word": "图形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "圖形", "label": "繁体"}, {"form": "平面图形", "label": "复合"}], "register": "中性", "sense_fingerprint": "画出来的形状（通俗说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98f4a8b1-54f9-4af0-bf82-5bf023832828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图形", "is_correct": true, "explanation": "正确：“画了很多图形”中，“图形”指画出来的样子，符合语境。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“画”不能搭配“时间”，纸上画不出时间。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“画”不能搭配“声音”，声音无法画在纸上。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不是画出来的东西，句意不通。"}], "explanations": {"图形": "正确：“画了很多图形”中，“图形”指画出来的样子，符合语境。", "时间": "搭配：“画”不能搭配“时间”，纸上画不出时间。", "声音": "搭配：“画”不能搭配“声音”，声音无法画在纸上。", "歌曲": "语义：“歌曲”不是画出来的东西，句意不通。"}, "sentence_index": 0, "correct_answer": "图形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试的图形很好。", "explanation": "这里应该用〈成绩〉。考试的结果要说“成绩”，图形指画出来的样子或几何形状。"}, {"text": "这篇文章的图形很长。", "explanation": "这里应该用〈篇幅〉。文章的长短要说“篇幅”，图形指画出来的样子，不能用来形容文章。"}, {"text": "他说话的图形很慢。", "explanation": "这里应该用〈语速〉。说话的快慢要说“语速”，图形指画出来的样子或几何形状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图形", "is_correct": true, "explanation": "正确：“画有趣的图形”指画出的有趣形状，符合“画”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“画”不能搭配“味道”，味道画不出来。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”不是能画出来的东西，句意不通。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“画”不能搭配“气味”，气味无法画出。"}], "explanations": {"图形": "正确：“画有趣的图形”指画出的有趣形状，符合“画”。", "味道": "搭配：“画”不能搭配“味道”，味道画不出来。", "温度": "语义：“温度”不是能画出来的东西，句意不通。", "气味": "搭配：“画”不能搭配“气味”，气味无法画出。"}, "sentence_index": 6, "correct_answer": "图形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在舞台上的图形很好。", "explanation": "这里应该用〈形象〉。人在舞台上的形象要说“形象”，“图形”指几何形状。"}, {"text": "这首歌的图形很好听。", "explanation": "这里应该用〈旋律〉。歌好不好听说的是“旋律”，图形指画出来的样子，不能用来说声音。"}, {"text": "他对这件事的图形很清楚。", "explanation": "这里应该用〈认识〉。对事情的了解要说“认识”，图形指画出来的样子或几何形状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用铅笔画出了一条图形。", "corrected_sentence": "她用铅笔画出了一个图形。", "error_description": "“图形”的量词应为“个”，不能用“条”。“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这个图形画很整齐。", "corrected_sentence": "他把这个图形画得很整齐。", "error_description": "补语前漏掉“得”：“画”后带补语“很整齐”时，要用“得”引出，应说“画得很整齐”，不能说“画很整齐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7bf06a-50af-4fe3-aaf0-a17605044138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
