INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21962, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西拿到这里来。", "primary_collocate": null, "pronunciation": "dài lái", "ipa": "tai˥˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "明天请带来你的作业本。", "target_word": "带来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从北京给我带来了一盒茶。", "target_word": "带来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人带来了一束漂亮的花。", "target_word": "带来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雨，你带来雨伞了吗？", "target_word": "带来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友从老家带来了很多水果。", "target_word": "带来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没带来相机，不能拍照。", "target_word": "带来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请带来你的身份证，办手续用。", "target_word": "带来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟带来了他的新玩具给我看。", "target_word": "带来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶从乡下带来了一只鸡。", "target_word": "带来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王带来了热茶，大家一起喝。", "target_word": "带来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带来了", "label": "体标"}, {"form": "带来过", "label": "体标"}, {"form": "帶來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西拿着送到说话人所在的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245aa18a-045a-46cc-b4fa-b7de9581fe19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带来", "is_correct": true, "explanation": "“带来”表示把东西拿到说话人这里，与“请……你的作业本”搭配，句意通顺。"}, {"text": "熔化", "is_correct": false, "explanation": "语义：“熔化”指固体受热变成液体，不能施用于作业本，句子语义荒谬。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于树枝、指甲等，不能说“修剪作业本”，搭配不当。"}, {"text": "刷新", "is_correct": false, "explanation": "搭配：“刷新”搭配页面、纪录等，不能说“刷新作业本”，搭配不当。"}], "explanations": {"带来": "“带来”表示把东西拿到说话人这里，与“请……你的作业本”搭配，句意通顺。", "熔化": "语义：“熔化”指固体受热变成液体，不能施用于作业本，句子语义荒谬。", "修剪": "搭配：“修剪”用于树枝、指甲等，不能说“修剪作业本”，搭配不当。", "刷新": "搭配：“刷新”搭配页面、纪录等，不能说“刷新作业本”，搭配不当。"}, "sentence_index": 0, "correct_answer": "带来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷带来我去公园。", "explanation": "这里应该用〈领〉。带来表示把东西或人拿到说话人所在的地方，带人去别处不能用“带来”，应说“领我去公园”。"}, {"text": "姐姐带来了一箱牛奶回老家。", "explanation": "这里应该用〈带回〉。带来表示把东西拿到说话人所在的地方，把东西拿回老家要用〈带回〉，不能用〈带来〉。"}, {"text": "老师带来同学去博物馆。", "explanation": "这里应该用〈带〉。带来表示把东西拿到说话人这里，领着人去别处要用“带”，应说“带同学去博物馆”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带来", "is_correct": true, "explanation": "“带来”表示把身份证拿到这里，办手续时请对方携带，句意通顺。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”会毁坏身份证，与“办手续用”的语境相悖，句子荒谬。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”用于衣物、布料，不能说“缝补身份证”，搭配不当。"}, {"text": "切割", "is_correct": false, "explanation": "语义：“切割”指把物体切成几块，不能施用于身份证，句子语义荒谬。"}], "explanations": {"带来": "“带来”表示把身份证拿到这里，办手续时请对方携带，句意通顺。", "撕碎": "语义：“撕碎”会毁坏身份证，与“办手续用”的语境相悖，句子荒谬。", "缝补": "搭配：“缝补”用于衣物、布料，不能说“缝补身份证”，搭配不当。", "切割": "语义：“切割”指把物体切成几块，不能施用于身份证，句子语义荒谬。"}, "sentence_index": 6, "correct_answer": "带来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长带来同学去操场。", "explanation": "这里应该用〈带〉。带来表示把东西拿到说话人这里，领着人去别处要用“带”，应说“带同学去操场”。"}, {"text": "妈妈带来了一盒饼干去学校。", "explanation": "这里应该用〈带去〉。带来表示把东西拿到说话人所在的地方，把东西拿到学校这类别处要用〈带去〉，不能用〈带来〉。"}, {"text": "朋友带来我去车站。", "explanation": "这里应该用〈送〉。带来表示拿到说话人这里，陪人去别处要用“送”，应说“送我去车站”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天妈妈会带来了一袋米。", "corrected_sentence": "明天妈妈会带来一袋米。", "error_description": "体标错误：“明天”指将来，“了”表示动作已经完成，不能用于将来的动作。应为“会带来一袋米”，不能说“会带来了一袋米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天没带来了雨伞。", "corrected_sentence": "我今天没带来雨伞。", "error_description": "体标错误：否定已发生的动作用“没”，后面不能再加“了”。应为“没带来雨伞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
