INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21968, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "存在了很久很久，历史悠久。", "primary_collocate": null, "pronunciation": "gǔ lǎo", "ipa": "ku˨˩˦ lau˨˩˦", "syllable_count": 2, "sentences": [{"text": "这是一座古老的城市。", "target_word": "古老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷给我讲了一个古老的故事。", "target_word": "古老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古老的房子里住着一位老人。", "target_word": "古老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城是中国最古老的建筑之一。", "target_word": "古老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街很古老，有一千多年了。", "target_word": "古老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村口有一棵古老的大树。", "target_word": "古老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种音乐很古老，现在很少有人听。", "target_word": "古老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古老的钟声在山谷里响着。", "target_word": "古老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢收集古老的硬币。", "target_word": "古老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个古老的节日已经有两千年了。", "target_word": "古老", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更古老", "label": "比较"}, {"form": "最古老", "label": "最高级"}], "register": "中性", "sense_fingerprint": "存在了很久很久的、历史悠久的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69273c12-942b-4785-8ed5-3d4f334825ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古老", "is_correct": true, "explanation": "正确：「这是一座古老的城市」，古老形容历史久远，符合句意。"}, {"text": "幼小", "is_correct": false, "explanation": "语义：「幼小」指年纪小，不能用来形容城市，与句意不符。"}, {"text": "憨厚", "is_correct": false, "explanation": "搭配：「憨厚」形容人的性格，不能用来形容城市。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：「苗条」形容人的身材，不能用来形容城市。"}], "explanations": {"古老": "正确：「这是一座古老的城市」，古老形容历史久远，符合句意。", "幼小": "语义：「幼小」指年纪小，不能用来形容城市，与句意不符。", "憨厚": "搭配：「憨厚」形容人的性格，不能用来形容城市。", "苗条": "体貌：「苗条」形容人的身材，不能用来形容城市。"}, "sentence_index": 0, "correct_answer": "古老"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶已经很古老了，走路也很慢。", "explanation": "这里应该用〈年老〉。古老形容事物存在的历史久远，不用来形容人的年龄，老人要说年老。"}, {"text": "这辆刚出厂的汽车很古老。", "explanation": "这里应该用〈崭新〉。古老指存在了很久，刚出厂的汽车只能说崭新。"}, {"text": "我昨天刚买的这双鞋很古老。", "explanation": "这里应该用〈新〉。古老指存在了很久、历史悠久，昨天刚买的鞋只能说新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古老", "is_correct": true, "explanation": "正确：「很古老，现在很少有人听」前后意思一致。"}, {"text": "热门", "is_correct": false, "explanation": "语义：「热门」指很多人喜欢，与「现在很少有人听」矛盾。"}, {"text": "时髦", "is_correct": false, "explanation": "语义：「时髦」指流行，与「现在很少有人听」矛盾。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：「瘦弱」形容人的身体，不能用来形容音乐。"}], "explanations": {"古老": "正确：「很古老，现在很少有人听」前后意思一致。", "热门": "语义：「热门」指很多人喜欢，与「现在很少有人听」矛盾。", "时髦": "语义：「时髦」指流行，与「现在很少有人听」矛盾。", "瘦弱": "体貌：「瘦弱」形容人的身体，不能用来形容音乐。"}, "sentence_index": 6, "correct_answer": "古老"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这款手机是今年最古老的型号。", "explanation": "这里应该用〈最新〉。古老指存在很久，今年推出的型号应说最新。"}, {"text": "他古老的时候很爱哭。", "explanation": "这里应该用〈幼小〉。古老只用于事物的历史久远，不用来形容人小时候。"}, {"text": "这是刚出炉的古老面包。", "explanation": "这里应该用〈新鲜〉。古老指存在很久，刚出炉的面包只能说新鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵树是村里很最古老的树。", "corrected_sentence": "这棵树是村里最古老的树。", "error_description": "错误：「很」和「最」都是程度副词，不能同时修饰「古老」。应去掉「很」，说「最古老」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶给我讲了一个古老地传说。", "corrected_sentence": "奶奶给我讲了一个古老的传说。", "error_description": "错误：「古老地传说」误用了结构助词「地」。「地」用于修饰动词，修饰名词要用「的」，应改为「古老的传说」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肤浅", "is_correct": true, "explanation": "正确。“深刻”与“肤浅”是反义词，指触及本质与停留在表面相对。"}, {"text": "平坦", "is_correct": false, "explanation": "与“深刻”没有反义关系，只是同为形容词。"}, {"text": "明亮", "is_correct": false, "explanation": "与“深刻”没有反义关系，只是同为形容词。"}, {"text": "湿润", "is_correct": false, "explanation": "与“深刻”没有反义关系，只是同为形容词。"}], "correct_answer": "肤浅", "explanations": {"肤浅": "正确。“深刻”与“肤浅”是反义词，指触及本质与停留在表面相对。", "平坦": "与“深刻”没有反义关系，只是同为形容词。", "明亮": "与“深刻”没有反义关系，只是同为形容词。", "湿润": "与“深刻”没有反义关系，只是同为形容词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肤浅", "is_correct": true, "explanation": "正确。“深刻”与“肤浅”是反义词，指触及本质与停留在表面相对。"}, {"text": "温暖", "is_correct": false, "explanation": "与“深刻”没有反义关系，只是同为形容词。"}, {"text": "坚硬", "is_correct": false, "explanation": "与“深刻”没有反义关系，只是同为形容词。"}, {"text": "辽阔", "is_correct": false, "explanation": "与“深刻”没有反义关系，只是同为形容词。"}], "correct_answer": "肤浅", "explanations": {"肤浅": "正确。“深刻”与“肤浅”是反义词，指触及本质与停留在表面相对。", "温暖": "与“深刻”没有反义关系，只是同为形容词。", "坚硬": "与“深刻”没有反义关系，只是同为形容词。", "辽阔": "与“深刻”没有反义关系，只是同为形容词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（印象、道理、认识等）触及本质，给人很深的感受。", "primary_collocate": null, "pronunciation": "shēn kè", "ipa": "ʂən˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这次旅行给我留下了深刻的印象。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的意义很深刻，值得想一想。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个问题的理解非常深刻。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话让我印象深刻。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次失败的教训太深刻了，我再也不会忘。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写得很深刻，读完让人想很久。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了一个深刻的道理，大家都点头。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影对生活的看法很深刻。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过这件事，我对朋友的意义有了更深刻的认识。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话不多，但是每句都很深刻。", "target_word": "深刻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深刻地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "形容词，指印象、道理、认识等触及本质、给人很深的感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38845469-7ba0-4215-b3c1-2b01ad8b31c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深刻", "is_correct": true, "explanation": "正确。“留下了深刻的印象”是常用说法，指印象很深、触及本质。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”描述形状，不能用来形容印象的深浅。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，印象不能是咸的，句子不通。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“印象”一般不跟“湿”搭配，“湿的印象”不是习惯说法。"}], "explanations": {"深刻": "正确。“留下了深刻的印象”是常用说法，指印象很深、触及本质。", "圆": "语义：“圆”描述形状，不能用来形容印象的深浅。", "咸": "语义：“咸”形容味道，印象不能是咸的，句子不通。", "湿": "搭配：“印象”一般不跟“湿”搭配，“湿的印象”不是习惯说法。"}, "sentence_index": 0, "correct_answer": "深刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说他的病情很深刻。", "explanation": "这里应该用〈严重〉。“深刻”用于印象、道理，形容病情这类情况要用“严重”。"}, {"text": "这所学校有深刻的教学基础。", "explanation": "这里应该用〈深厚〉。“深刻”指触及本质、给人很深的感受，“基础”要用“深厚”。"}, {"text": "这座山非常深刻，爬起来很累。", "explanation": "这里应该用〈高〉。“深刻”用于印象、道理，形容山的高低要用“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深刻", "is_correct": true, "explanation": "正确。“一个深刻的道理”是常见说法，指道理让人感觉很有深度。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：“雪白”形容颜色，道理没有颜色，句子不通。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音，不能用来修饰道理。"}, {"text": "软绵绵", "is_correct": false, "explanation": "搭配：“软绵绵”形容质地或状态，“道理”不能这样形容。"}], "explanations": {"深刻": "正确。“一个深刻的道理”是常见说法，指道理让人感觉很有深度。", "雪白": "语义：“雪白”形容颜色，道理没有颜色，句子不通。", "响亮": "语义：“响亮”形容声音，不能用来修饰道理。", "软绵绵": "搭配：“软绵绵”形容质地或状态，“道理”不能这样形容。"}, "sentence_index": 6, "correct_answer": "深刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他心里有一种深刻的负担。", "explanation": "这里应该用〈沉重〉。“深刻”用于印象、道理，负担、压力这类感受要用“沉重”。"}, {"text": "他的声音很深刻，大家都听得清楚。", "explanation": "这里应该用〈深沉〉。“深刻”用于道理、印象，声音、性格要用“深沉”。"}, {"text": "我们等了一段深刻的时间。", "explanation": "这里应该用〈漫长〉。“深刻”不用来形容时间的长短，形容时间要用“漫长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书的道理是深刻，值得反复读。", "corrected_sentence": "这本书的道理很深刻，值得反复读。", "error_description": "形容词“深刻”作谓语时前面要加程度副词“很”，应说“很深刻”；用“是”接形容词、不带“的”，不符合汉语习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次讨论让我对环境问题有了更深刻得认识。", "corrected_sentence": "这次讨论让我对环境问题有了更深刻的认识。", "error_description": "修饰名词“认识”时，形容词后应用结构助词“的”，说“更深刻的认识”；“得”用于补语，这里用“得”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f1ae452-cf09-4349-8970-8170d23b30ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
