INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21972, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里想要得到某个东西或达到某个目标。", "primary_collocate": null, "pronunciation": "zhuī qiú", "ipa": "ʈʂweɪ˥ tɕʰioʊ˧˥", "syllable_count": 2, "sentences": [{"text": "年轻人都在追求自己的梦想。", "target_word": "追求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直追求更好的生活。", "target_word": "追求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不追求有钱，只想过得开心。", "target_word": "追求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她追求完美，每件事都做得很细。", "target_word": "追求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人追求安静的生活。", "target_word": "追求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司追求质量，不追求速度。", "target_word": "追求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸年轻时追求过自由。", "target_word": "追求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你追求的目标是什么？", "target_word": "追求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生不应该只追求高分。", "target_word": "追求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们追求幸福的家庭生活。", "target_word": "追求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追求了", "label": "体标"}, {"form": "追求着", "label": "体标"}, {"form": "追求过", "label": "体标"}, {"form": "追求者", "label": "复合"}], "register": "中性", "sense_fingerprint": "心里想要并努力去得到某个目标或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21972, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追求", "is_correct": true, "explanation": "追求：表示心里想要并努力去得到某个目标，与“梦想”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能接“梦想”作宾语，“吃自己的梦想”不成立。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能接抽象的“梦想”，“洗自己的梦想”不通。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的宾语多为具体的物体，不能接“梦想”作宾语，“搬自己的梦想”不成立。"}], "explanations": {"追求": "追求：表示心里想要并努力去得到某个目标，与“梦想”搭配。", "吃": "搭配：“吃”不能接“梦想”作宾语，“吃自己的梦想”不成立。", "洗": "搭配：“洗”不能接抽象的“梦想”，“洗自己的梦想”不通。", "搬": "搭配：“搬”的宾语多为具体的物体，不能接“梦想”作宾语，“搬自己的梦想”不成立。"}, "sentence_index": 0, "correct_answer": "追求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在草地上追求蝴蝶。", "explanation": "这里应该用〈追逐〉。追求指心里想得到的目标，不用于追赶跑动的东西。"}, {"text": "他在山里追求失踪的小狗。", "explanation": "这里应该用〈寻找〉。追求的对象是理想或目标，不能用于寻找失踪的人或动物。"}, {"text": "大家在追求去世的老人。", "explanation": "这里应该用〈追悼〉。追求指想得到某个目标，不用于怀念、哀悼已经去世的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21972, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追求", "is_correct": true, "explanation": "追求：表示想要得到并努力争取，与“自由”搭配，指年轻时争取自由。"}, {"text": "卖", "is_correct": false, "explanation": "搭配：“卖”不能接“自由”作宾语，“卖过自由”不成立。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮品，不能接“自由”。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”表示修理，与“自由”这种抽象概念无关。"}], "explanations": {"追求": "追求：表示想要得到并努力争取，与“自由”搭配，指年轻时争取自由。", "卖": "搭配：“卖”不能接“自由”作宾语，“卖过自由”不成立。", "喝": "搭配：“喝”的宾语应是饮品，不能接“自由”。", "修": "语义：“修”表示修理，与“自由”这种抽象概念无关。"}, "sentence_index": 6, "correct_answer": "追求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "侦探一直在追求那个嫌疑人。", "explanation": "这里应该用〈追踪〉。追求表示想得到某种目标，不用于跟踪、盯住一个人。"}, {"text": "他向老师追求帮助。", "explanation": "这里应该用〈请求〉。追求指向目标努力，不能用于向别人请求帮助。"}, {"text": "运动员在赛道上追求对手。", "explanation": "这里应该用〈追赶〉。追求的对象是目标，不能用于追赶正在前面的对手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要追求了更高的质量。", "corrected_sentence": "我们要追求更高的质量。", "error_description": "“要”表示将来，“追求”后不能加“了”。应去掉“了”：我们要追求更高的质量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她追求过过自己的理想。", "corrected_sentence": "她追求过自己的理想。", "error_description": "多了一个“过”。“追求过”后不能再加“过”，应为：她追求过自己的理想。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
