INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "越过河流、山脉、国界等，从一边到达另一边。", "primary_collocate": null, "pronunciation": "kuà yuè", "ipa": "kʰua⁵¹ ɥe⁵¹", "syllable_count": 2, "sentences": [{"text": "这座桥跨越了一条大河。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机跨越大海,飞到了另一个国家。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们跨越山河来看我。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跨越了那条小河，走到了对岸。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路跨越了三个省。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跨越千山万水,回到了家乡。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车跨越国界,开往北京。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座长桥跨越了整个海湾。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条高速公路跨越了整个山区。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想跨越这片沙漠,去找朋友。", "target_word": "跨越", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跨越了", "label": "体标"}, {"form": "跨越过", "label": "体标"}], "register": "中性", "sense_fingerprint": "越过某地到达另一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d9ab088-f832-4c2b-8bdc-c6dfd9f23bbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨越", "is_correct": true, "explanation": "“跨越”指从河的一边到另一边，“这座桥跨越了一条大河”成立。"}, {"text": "渡", "is_correct": false, "explanation": "语义：“渡”是乘船摆渡，桥不能“渡”河。"}, {"text": "环绕", "is_correct": false, "explanation": "语义：“环绕”是围着转，桥不是围着河转。"}, {"text": "挖掘", "is_correct": false, "explanation": "语义：“挖掘”是挖土，桥不能挖掘河流，句意不通。"}], "explanations": {"跨越": "“跨越”指从河的一边到另一边，“这座桥跨越了一条大河”成立。", "渡": "语义：“渡”是乘船摆渡，桥不能“渡”河。", "环绕": "语义：“环绕”是围着转，桥不是围着河转。", "挖掘": "语义：“挖掘”是挖土，桥不能挖掘河流，句意不通。"}, "sentence_index": 0, "correct_answer": "跨越"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跨越了所有同学，考了第一名。", "explanation": "这里应该用〈超越〉。超过别人用“超越”；“跨越”指从一端到另一端，不能用来比较名次。"}, {"text": "今年的产量跨越了去年。", "explanation": "这里应该用〈超过〉。数量比较用“超过”；“跨越”指空间上从一边到另一边。"}, {"text": "他跨越了一碗饭。", "explanation": "这里应该用〈吃〉。吃饭要用“吃”；“跨越”不能接食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨越", "is_correct": true, "explanation": "“跨越”指越过国界这样的界限，“火车跨越国界，开往北京”成立。"}, {"text": "守卫", "is_correct": false, "explanation": "语义：“守卫”是防守保护，火车不守卫国界，句意不通。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象是道路、桥梁，不说“修国界”。"}, {"text": "划定", "is_correct": false, "explanation": "语义：“划定”是划出界限，火车不能划定国界。"}], "explanations": {"跨越": "“跨越”指越过国界这样的界限，“火车跨越国界，开往北京”成立。", "守卫": "语义：“守卫”是防守保护，火车不守卫国界，句意不通。", "修": "搭配：“修”的对象是道路、桥梁，不说“修国界”。", "划定": "语义：“划定”是划出界限，火车不能划定国界。"}, "sentence_index": 6, "correct_answer": "跨越"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她跨越了一双新鞋。", "explanation": "这里应该用〈穿〉。穿鞋要用“穿”；“跨越”不能接鞋子。"}, {"text": "他跨越了一杯茶。", "explanation": "这里应该用〈喝〉。喝茶要用“喝”；“跨越”指从一边越到另一边，不能接饮品。"}, {"text": "他跨越了一个秘密。", "explanation": "这里应该用〈发现〉。发现秘密用“发现”；“跨越”指越过空间或界限，不能用于秘密。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跨越了到对岸。", "corrected_sentence": "他跨越到了对岸。", "error_description": "错误：“了”放在了“到”的前面。正确应为“跨越到了对岸”，结果补语“到”后面才接“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天跨越着那座大山。", "corrected_sentence": "他昨天跨越了那座大山。", "error_description": "错误：体标用错了。“昨天”说的是已经完成的动作，“跨越”后面应该用“了”，不能用表示持续的“着”。正确应为“他昨天跨越了那座大山”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21978, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "混乱", "is_correct": true, "explanation": "「混乱」与「秩序」构成反义，指没有条理、一片乱的状态。"}, {"text": "天气", "is_correct": false, "explanation": "「天气」指大气的冷暖阴晴，与「秩序」没有反义或近义关系。"}, {"text": "距离", "is_correct": false, "explanation": "「距离」指两点之间的长度，与「秩序」没有反义或近义关系。"}, {"text": "经验", "is_correct": false, "explanation": "「经验」指从实践中积累的知识，与「秩序」没有反义或近义关系。"}], "correct_answer": "混乱", "explanations": {"混乱": "「混乱」与「秩序」构成反义，指没有条理、一片乱的状态。", "天气": "「天气」指大气的冷暖阴晴，与「秩序」没有反义或近义关系。", "距离": "「距离」指两点之间的长度，与「秩序」没有反义或近义关系。", "经验": "「经验」指从实践中积累的知识，与「秩序」没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21978, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "混乱", "is_correct": true, "explanation": "「混乱」与「秩序」构成反义，指没有条理、一片乱的状态。"}, {"text": "经济", "is_correct": false, "explanation": "「经济」指社会的生产和分配等活动，与「秩序」没有反义或近义关系。"}, {"text": "信号", "is_correct": false, "explanation": "「信号」指传递信息的标志，与「秩序」没有反义或近义关系。"}, {"text": "地址", "is_correct": false, "explanation": "「地址」指所在的位置，与「秩序」没有反义或近义关系。"}], "correct_answer": "混乱", "explanations": {"混乱": "「混乱」与「秩序」构成反义，指没有条理、一片乱的状态。", "经济": "「经济」指社会的生产和分配等活动，与「秩序」没有反义或近义关系。", "信号": "「信号」指传递信息的标志，与「秩序」没有反义或近义关系。", "地址": "「地址」指所在的位置，与「秩序」没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21978, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家按顺序做事情，不争不抢的样子。", "primary_collocate": null, "pronunciation": "zhì xù", "ipa": "ʈʂɨ˥˩ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "同学们排好队，保持教室里的秩序。", "target_word": "秩序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在路口维持交通秩序。", "target_word": "秩序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家要遵守公共秩序。", "target_word": "秩序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人太多了，现场的秩序有点乱。", "target_word": "秩序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生遵守秩序，一个一个走出教室。", "target_word": "秩序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，球迷们有秩序地离开。", "target_word": "秩序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的秩序很好，没有人插队。", "target_word": "秩序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排队买票是良好的社会秩序。", "target_word": "秩序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，医院里的秩序很快恢复了。", "target_word": "秩序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员请大家维护好店里的秩序。", "target_word": "秩序", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "秩序井然", "label": "复合"}], "register": "书面", "sense_fingerprint": "人们做事时有条理、守规矩、不混乱的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33c7f637-619d-49ba-80ef-a53edb7b3254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21978, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "秩序", "is_correct": true, "explanation": "「秩序」指人们有条理、守规矩的状态，是本题正确答案。"}, {"text": "志趣", "is_correct": false, "explanation": "qù（第四声）与 xù（第四声）声母不同（q 与 x），意思是志向和兴趣，与秩序不同。"}, {"text": "质数", "is_correct": false, "explanation": "shù（第四声）与 xù（第四声）声母不同（sh 与 x），意思是数学中只能被1和自身整除的数。"}, {"text": "制度", "is_correct": false, "explanation": "dù（第四声）与 xù（第四声）声母不同（d 与 x），意思是规定和制度。"}], "explanations": {"秩序": "「秩序」指人们有条理、守规矩的状态，是本题正确答案。", "志趣": "qù（第四声）与 xù（第四声）声母不同（q 与 x），意思是志向和兴趣，与秩序不同。", "质数": "shù（第四声）与 xù（第四声）声母不同（sh 与 x），意思是数学中只能被1和自身整除的数。", "制度": "dù（第四声）与 xù（第四声）声母不同（d 与 x），意思是规定和制度。"}, "sentence_index": null, "correct_answer": "秩序"}, "level_3": {"options": [{"text": "秩序", "is_correct": true, "explanation": "「秩序」指有条理、守规矩的状态，与排队、保持教室的语境相符。"}, {"text": "速度", "is_correct": false, "explanation": "语义：「速度」指快慢，不能用来指教室里有条理的管理状态。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：「脾气」指性情，只能用于人，不能说保持教室里的脾气。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：「保持」接的是状态或秩序，「工资」是金额，不能与「保持教室里的」搭配。"}], "explanations": {"秩序": "「秩序」指有条理、守规矩的状态，与排队、保持教室的语境相符。", "速度": "语义：「速度」指快慢，不能用来指教室里有条理的管理状态。", "脾气": "语义：「脾气」指性情，只能用于人，不能说保持教室里的脾气。", "工资": "搭配：「保持」接的是状态或秩序，「工资」是金额，不能与「保持教室里的」搭配。"}, "sentence_index": 0, "correct_answer": "秩序"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的秩序很好，用了十年都没坏。", "explanation": "这里应该用〈质量〉。「秩序」指人们有条理、守规矩的状态，不能用来说东西耐用；说东西好用不坏要用「质量」。"}, {"text": "这间教室的秩序很大，能坐下一百人。", "explanation": "这里应该用〈面积〉。「秩序」指有条理的状态，不能用大小来形容；说教室大要用「面积」。"}, {"text": "比赛开始以后，场上的秩序很热烈。", "explanation": "这里应该用〈气氛〉。「秩序」不能用热烈来形容，描述现场热烈的情绪要用「气氛」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21978, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "秩序", "is_correct": true, "explanation": "「秩序」指人们有条理、守规矩的状态，是本题正确答案。"}, {"text": "治愈", "is_correct": false, "explanation": "yù（第四声）与 xù（第四声）声母不同（y 与 x），意思是医治，使病痊愈。"}, {"text": "致谢", "is_correct": false, "explanation": "xiè（第四声）与 xù（第四声）韵母不同（ie 与 u），意思是表示感谢。"}, {"text": "直叙", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是直接叙述，属于书面用语。"}], "explanations": {"秩序": "「秩序」指人们有条理、守规矩的状态，是本题正确答案。", "治愈": "yù（第四声）与 xù（第四声）声母不同（y 与 x），意思是医治，使病痊愈。", "致谢": "xiè（第四声）与 xù（第四声）韵母不同（ie 与 u），意思是表示感谢。", "直叙": "zhí（第二声）与 zhì（第四声）声调不同，意思是直接叙述，属于书面用语。"}, "sentence_index": null, "correct_answer": "秩序"}, "level_3": {"options": [{"text": "秩序", "is_correct": true, "explanation": "「秩序」指有条理、守规矩的状态，与「没有人插队」的语境相符。"}, {"text": "口味", "is_correct": false, "explanation": "语义：「口味」指食物的滋味或喜好，不能用来形容银行的状况。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」指岁数，与银行的管理状况无关，句子说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」只用于人或动物的重量，不能和「银行的」组合。"}], "explanations": {"秩序": "「秩序」指有条理、守规矩的状态，与「没有人插队」的语境相符。", "口味": "语义：「口味」指食物的滋味或喜好，不能用来形容银行的状况。", "年龄": "语义：「年龄」指岁数，与银行的管理状况无关，句子说不通。", "体重": "搭配：「体重」只用于人或动物的重量，不能和「银行的」组合。"}, "sentence_index": 6, "correct_answer": "秩序"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室里有一把秩序。", "explanation": "这里应该用〈种〉。〈把〉用于有柄的器具，「秩序」是抽象的状态，不能用〈把〉计量。"}, {"text": "社会里有一条秩序。", "explanation": "这里应该用〈种〉。〈条〉用于细长的物体，「秩序」是抽象的状态，不能用〈条〉计量。"}, {"text": "这个班里有一只秩序。", "explanation": "这里应该用〈种〉。〈只〉用于动物或成对物品之一，「秩序」不能用〈只〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "值班老师负责增加校园秩序。", "corrected_sentence": "值班老师负责维持校园秩序。", "error_description": "错误：「增加」用于数量，不能与「秩序」搭配。正确：「维持」，「维持秩序」是常用搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会场里需要一座良好的秩序。", "corrected_sentence": "会场里需要一种良好的秩序。", "error_description": "错误：「座」用于山、房屋等大型固定物，不能计量抽象的秩序。正确：「种」，即「一种良好的秩序」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
