INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21980, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一段时间。", "primary_collocate": null, "pronunciation": "shí qī", "ipa": "ʂɨ³⁵ tɕʰi⁵⁵", "syllable_count": 2, "sentences": [{"text": "大学时期，他常去图书馆。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时期公司特别忙。", "target_word": "时期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "童年时期，他住在农村。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个时期，人们的生活很困难。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一年中这个时期最冷。", "target_word": "时期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "中学时期，她很喜欢画画。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那一时期他住在上海。", "target_word": "时期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "困难时期，大家互相帮助。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在这个时期学会了开车。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个时期，很多年轻人去南方工作。", "target_word": "时期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "泛指一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21980, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时期", "is_correct": true, "explanation": "正确答案，指一段时间，与听到的音相符。"}, {"text": "食器", "is_correct": false, "explanation": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是饮食用具。"}, {"text": "时机", "is_correct": false, "explanation": "第二音节声母不同：jī 与 qī，意思是合适的机会。"}, {"text": "时区", "is_correct": false, "explanation": "第二音节韵母不同：qū（ü）与 qī（i），意思是时区。"}], "explanations": {"时期": "正确答案，指一段时间，与听到的音相符。", "食器": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是饮食用具。", "时机": "第二音节声母不同：jī 与 qī，意思是合适的机会。", "时区": "第二音节韵母不同：qū（ü）与 qī（i），意思是时区。"}, "sentence_index": null, "correct_answer": "时期"}, "level_3": {"options": [{"text": "时期", "is_correct": true, "explanation": "正确。“大学时期”指上大学的那段时间，与“常去图书馆”相符。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”是钱，不指一段时间，“大学学费，他常去图书馆”句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与时间无关，“大学颜色”不成立。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不指时间，句子不通。"}], "explanations": {"时期": "正确。“大学时期”指上大学的那段时间，与“常去图书馆”相符。", "学费": "语义：“学费”是钱，不指一段时间，“大学学费，他常去图书馆”句意不通。", "颜色": "语义：“颜色”与时间无关，“大学颜色”不成立。", "书包": "语义：“书包”是物品，不指时间，句子不通。"}, "sentence_index": 0, "correct_answer": "时期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑完这段路只用了三分钟的时期。", "explanation": "这里应该用〈时间〉。时期指一段时间，具体的时长（三分钟）要用“时间”。"}, {"text": "现在是八点整的时期了，大家快进去。", "explanation": "这里应该用〈时刻〉。八点整指具体的时间点，时期指一段时间，不能用来指某一时刻。"}, {"text": "做饭的时期别进厨房。", "explanation": "这里应该用〈时候〉。表示某件事发生的时点用“时候”，时期指较长的一段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21980, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时期", "is_correct": true, "explanation": "正确答案，指一段时间，与听到的音相符。"}, {"text": "食器", "is_correct": false, "explanation": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是饮食用具。"}, {"text": "时气", "is_correct": false, "explanation": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是时令气候，或指流行病。"}, {"text": "石器", "is_correct": false, "explanation": "声调不同：qì（第四声）与 qī（第一声），意思是石制的工具。"}], "explanations": {"时期": "正确答案，指一段时间，与听到的音相符。", "食器": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是饮食用具。", "时气": "声调不同：第二音节 qì（第四声）与 qī（第一声），意思是时令气候，或指流行病。", "石器": "声调不同：qì（第四声）与 qī（第一声），意思是石制的工具。"}, "sentence_index": null, "correct_answer": "时期"}, "level_3": {"options": [{"text": "时期", "is_correct": true, "explanation": "语义正确：“那一时期”指那段时间，与后句“住在上海”相符。"}, {"text": "职业", "is_correct": false, "explanation": "语义：“职业”不指一段时间，“那一职业他住在上海”句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不指时间，“那一颜色”与句子无法连贯。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“那一”通常修饰时段，不能接“天气”组成可接受的说法。"}], "explanations": {"时期": "语义正确：“那一时期”指那段时间，与后句“住在上海”相符。", "职业": "语义：“职业”不指一段时间，“那一职业他住在上海”句意不通。", "颜色": "语义：“颜色”不指时间，“那一颜色”与句子无法连贯。", "天气": "搭配：“那一”通常修饰时段，不能接“天气”组成可接受的说法。"}, "sentence_index": 6, "correct_answer": "时期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的时期定在三月十五号。", "explanation": "这里应该用〈日期〉。定在具体某一天要用“日期”，时期指一段时间，不能这样指定某一天。"}, {"text": "他的时期比我大五岁。", "explanation": "这里应该用〈年龄〉。比较人的岁数要用“年龄”，时期指一段时间，不能用来比较岁数。"}, {"text": "明天的时期很满。", "explanation": "这里应该用〈日程〉。“明天的日程很满”指安排的事情多，时期指一段时间，不能说时期很满。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在那个时期的学会了游泳。", "corrected_sentence": "他在那个时期学会了游泳。", "error_description": "“的”误插在介词结构“在那个时期”与动词“学会”之间，破坏了“在……学会”的结构，应删去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只时期酒店的房价很高。", "corrected_sentence": "这段时期酒店的房价很高。", "error_description": "量词错误：“只”用于动物或成对的物件，时期应搭配“段”，应改为“这段时期”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
