INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "历史向前走的路。", "primary_collocate": null, "pronunciation": "lì shǐ jìn chéng", "ipa": "li˥˩ ʂɨ˨˩˦ tɕin˥˩ ʈʂʰəŋ˧˥", "syllable_count": 4, "sentences": [{"text": "历史进程就像一条长路。", "target_word": "历史进程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "历史进程一直向前走。", "target_word": "历史进程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张图画出了历史进程。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上画了历史进程。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学习不同国家的历史进程。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史进程不会往回走。", "target_word": "历史进程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们想知道历史进程里发生了什么。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课本把历史进程分成了几个部分。", "target_word": "历史进程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史进程有快的时候，也有慢的时候。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时间向前走，历史进程也向前走。", "target_word": "历史进程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷史進程", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "历史向前走过的道路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db84973e-d904-419a-b58d-917694db0a8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数字", "is_correct": false, "explanation": "语义：“数字”不能比作一条路，比喻与“长路”不合。"}, {"text": "历史进程", "is_correct": true, "explanation": "正确：“历史进程”指历史向前走的路，与“就像一条长路”相符。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：“咖啡”与“长路”没有比喻关系，不成立。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”是外形，不能比作一条路。"}], "explanations": {"数字": "语义：“数字”不能比作一条路，比喻与“长路”不合。", "历史进程": "正确：“历史进程”指历史向前走的路，与“就像一条长路”相符。", "咖啡": "语义：“咖啡”与“长路”没有比喻关系，不成立。", "外貌": "体貌：“外貌”是外形，不能比作一条路。"}, "sentence_index": 0, "correct_answer": "历史进程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次历史进程很愉快。", "explanation": "这里应该用〈旅程〉。历史进程指历史向前走的路，不指一次出行，说出行要用「旅程」。"}, {"text": "我们的历史进程安排得很满，每天都要赶路。", "explanation": "这里应该用〈行程〉。历史进程指历史向前走的路，不指出行的安排，说行程安排要用「行程」。"}, {"text": "这幅画的历史进程很鲜艳。", "explanation": "这里应该用〈颜色〉。历史进程指历史向前走的路，不能用来形容画面的色彩；说颜色鲜艳要用「颜色」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“里”要求地点或容器，“颜色”不能作“里”的处所。"}, {"text": "历史进程", "is_correct": true, "explanation": "正确：“历史进程”可以作“里”的处所，与“想知道……里发生了什么”相符。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：“嗓音”不能作容器，“里发生了什么”不成立。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是体形特征，不能作“里”的处所。"}], "explanations": {"颜色": "语义：“里”要求地点或容器，“颜色”不能作“里”的处所。", "历史进程": "正确：“历史进程”可以作“里”的处所，与“想知道……里发生了什么”相符。", "嗓音": "语义：“嗓音”不能作容器，“里发生了什么”不成立。", "身高": "体貌：“身高”是体形特征，不能作“里”的处所。"}, "sentence_index": 6, "correct_answer": "历史进程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的求学历史进程很艰难。", "explanation": "这里应该用〈历程〉。历史进程指历史向前走的道路，不指个人的经历，说个人的经历要用「历程」。"}, {"text": "这位歌手的历史进程很好听。", "explanation": "这里应该用〈声音〉。历史进程指历史向前走的路，不指人的嗓音；说声音好听要用「声音」。"}, {"text": "他的历史进程增加了五公斤。", "explanation": "这里应该用〈体重〉。历史进程指历史向前走的路，不能用来说人的体重；说体重增加要用「体重」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一本很长的历史进程。", "corrected_sentence": "这是一个很长的历史进程。", "error_description": "错误形式为“一本”，正确形式为“一个”。「本」用于书本，“历史进程”的量词应用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个漫长历史进程。", "corrected_sentence": "这是一个漫长的历史进程。", "error_description": "错误形式为“漫长历史进程”，正确形式为“漫长的历史进程”。双音节形容词“漫长”修饰“历史进程”时须加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dccc746-d2ac-4515-8f9a-87034dab8f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
