INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21986, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事物慢慢变化。", "primary_collocate": null, "pronunciation": "yǎn biàn", "ipa": "jɛn˨˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这个词的意思慢慢演变了。", "target_word": "演变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城市演变成了大城市。", "target_word": "演变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言会随着时间不断演变。", "target_word": "演变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小问题慢慢演变成大问题。", "target_word": "演变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种说法是从古代演变过来的。", "target_word": "演变", "complexity_tier": "T3", "furigana": "zhè zhǒng shuō fǎ shì cóng gǔ dài yǎn biàn guò lái de", "sentence_source": "generated"}, {"text": "汉字的样子一直在演变。", "target_word": "演变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的关系演变得很复杂。", "target_word": "演变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日是从旧习俗演变而来的。", "target_word": "演变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情为什么会演变成这样？", "target_word": "演变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的样子几十年里演变了很多。", "target_word": "演变", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演变了", "label": "体标"}, {"form": "演變", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物经过较长时间逐渐发生变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662c7823-51e1-46b7-b4e3-759c04a652e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倒下", "is_correct": false, "explanation": "搭配：“意思”不能说“倒下”，这里的说法不成立。"}, {"text": "演变", "is_correct": true, "explanation": "“演变”指事物经过较长时间逐渐变化，与“慢慢……了”的语境相符。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”指身体动作，与“意思”这类抽象事物无关。"}, {"text": "发火", "is_correct": false, "explanation": "语义：“发火”指生气，“意思发火”说不通。"}], "explanations": {"倒下": "搭配：“意思”不能说“倒下”，这里的说法不成立。", "演变": "“演变”指事物经过较长时间逐渐变化，与“慢慢……了”的语境相符。", "跳舞": "语义：“跳舞”指身体动作，与“意思”这类抽象事物无关。", "发火": "语义：“发火”指生气，“意思发火”说不通。"}, "sentence_index": 0, "correct_answer": "演变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一下子演变成了大人。", "explanation": "这里应该用〈长大〉。演变指事物慢慢变化，人从孩子长成大人要说“长大”，不能用“演变”。"}, {"text": "他在舞台上演变了一个角色。", "explanation": "这里应该用〈扮演〉。演变指事物逐渐变化，在舞台上表演某个角色要说“扮演”。"}, {"text": "政府演变了这个小区。", "explanation": "这里应该用〈改造〉。演变不表示人为有计划地改建，改造小区要用“改造”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演奏", "is_correct": false, "explanation": "语义：“演奏”指表演乐器，关系不能被演奏。"}, {"text": "演变", "is_correct": true, "explanation": "“演变”指事物逐渐发生变化，与“关系……得很复杂”的语境相符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清除脏东西，与“关系”无关。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”后不能接“得很复杂”来描述关系的变化，“关系完成得很复杂”不成说法。"}], "explanations": {"演奏": "语义：“演奏”指表演乐器，关系不能被演奏。", "演变": "“演变”指事物逐渐发生变化，与“关系……得很复杂”的语境相符。", "打扫": "语义：“打扫”指清除脏东西，与“关系”无关。", "完成": "搭配：“完成”后不能接“得很复杂”来描述关系的变化，“关系完成得很复杂”不成说法。"}, "sentence_index": 6, "correct_answer": "演变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校几年里演变了很多教室。", "explanation": "这里应该用〈扩建〉。演变指事物自然地逐渐变化，学校增加建筑要用“扩建”。"}, {"text": "他们演变了局面。", "explanation": "这里应该用〈扭转〉。演变指事物逐渐变化，不能用于人为地使局面反转。"}, {"text": "他在纸上演变了一道数学题。", "explanation": "这里应该用〈演算〉。演变指事物逐渐变化，在纸上计算答案要用“演算”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市慢慢演变了成大城市。", "corrected_sentence": "这个城市慢慢演变成了大城市。", "error_description": "“了”的位置错误：“了”应放在补语“成”之后，说“演变成了”，不能说“演变了成”。正确说法：演变成了大城市。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市的样子慢慢演变得。", "corrected_sentence": "城市的样子慢慢演变了。", "error_description": "补语／体标错误：“演变”后应用“了”表示完成，不能用“得”；“得”需接补语，如“演变得很大”，单独的“演变得”不完整。正确说法：城市的样子慢慢演变了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
