INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21988, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人从躺着或睡着的样子起身，变成坐着或站着。", "primary_collocate": null, "pronunciation": "qǐ", "ipa": "tɕʰi˨˩˦", "syllable_count": 1, "sentences": [{"text": "我每天起得很早。", "target_word": "起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟星期天总是起得很晚。", "target_word": "起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早睡早起，身体才会好。", "target_word": "起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他昨晚没睡好，今天起晚了。", "target_word": "起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人起得早，睡得也早。", "target_word": "起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天还没亮，妈妈就起了。", "target_word": "起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你明天几点起？", "target_word": "起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我病了，两天都没起，一直躺在床上。", "target_word": "起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天天冷，孩子们都起得晚。", "target_word": "起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天要去山上，我们得五点起。", "target_word": "起", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "起了", "label": "完成体"}, {"form": "起过", "label": "经历体"}, {"form": "起床", "label": "复合词"}, {"form": "起身", "label": "复合词"}], "register": "口语", "sense_fingerprint": "人从躺着或睡着的状态起身、起床", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b72803e1-d339-466f-98b7-61dea376201f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21988, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "起", "is_correct": true, "explanation": "正确。起（qǐ，第三声）指从躺着或睡着的状态起身。"}, {"text": "气", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，意思是空气、脾气。"}, {"text": "骑", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是骑车、骑马。"}, {"text": "七", "is_correct": false, "explanation": "qī（第一声）与 qǐ（第三声）声调不同，意思是数字七。"}, {"text": "洗", "is_correct": false, "explanation": "xǐ 与 qǐ 声母不同（x 与 q），意思是清洗。"}], "explanations": {"起": "正确。起（qǐ，第三声）指从躺着或睡着的状态起身。", "气": "qì（第四声）与 qǐ（第三声）声调不同，意思是空气、脾气。", "骑": "qí（第二声）与 qǐ（第三声）声调不同，意思是骑车、骑马。", "七": "qī（第一声）与 qǐ（第三声）声调不同，意思是数字七。", "洗": "xǐ 与 qǐ 声母不同（x 与 q），意思是清洗。"}, "sentence_index": null, "correct_answer": "起"}, "level_3": {"options": [{"text": "起", "is_correct": true, "explanation": "正确。“起得很早”指每天起床很早，与句意相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指抛出，与起床时间早没有关系。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”要接具体事物，“咬得很早”不成立。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”指发光或天色变亮，不能用来形容人的起床时间。"}], "explanations": {"起": "正确。“起得很早”指每天起床很早，与句意相符。", "扔": "语义：“扔”指抛出，与起床时间早没有关系。", "咬": "搭配：“咬”要接具体事物，“咬得很早”不成立。", "亮": "搭配：“亮”指发光或天色变亮，不能用来形容人的起床时间。"}, "sentence_index": 0, "correct_answer": "起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他起在沙发上看书，不想动。", "explanation": "这里应该用〈躺〉。起指从躺着变为坐着或站着，躺在沙发上要用躺。"}, {"text": "他昨晚起得很沉，精神很好。", "explanation": "这里应该用〈睡〉。起指身体离开床，不能形容睡眠的深浅，睡得沉要用睡。"}, {"text": "衣服起在墙上，很整齐。", "explanation": "这里应该用〈挂〉。起指人从躺着或睡着的状态起身，不能用于衣物；衣服挂在墙上要用挂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21988, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "起", "is_correct": true, "explanation": "正确。起（qǐ，第三声）指从躺着或睡着的状态起身。"}, {"text": "几", "is_correct": false, "explanation": "jǐ 与 qǐ 声母不同（j 与 q），意思是几个、多少。"}, {"text": "棋", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是下棋用的棋子。"}, {"text": "喜", "is_correct": false, "explanation": "xǐ 与 qǐ 声母不同（x 与 q），意思是高兴。"}, {"text": "旗", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是旗帜。"}], "explanations": {"起": "正确。起（qǐ，第三声）指从躺着或睡着的状态起身。", "几": "jǐ 与 qǐ 声母不同（j 与 q），意思是几个、多少。", "棋": "qí（第二声）与 qǐ（第三声）声调不同，意思是下棋用的棋子。", "喜": "xǐ 与 qǐ 声母不同（x 与 q），意思是高兴。", "旗": "qí（第二声）与 qǐ（第三声）声调不同，意思是旗帜。"}, "sentence_index": null, "correct_answer": "起"}, "level_3": {"options": [{"text": "起", "is_correct": true, "explanation": "正确。“你明天几点起？”问的是明天什么时候起床，与句意相符。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指跌倒，问的是起床时间，与此不符。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”指发出咳声，与问起床时间无关。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”形容体形，不能用来问几点做什么。"}], "explanations": {"起": "正确。“你明天几点起？”问的是明天什么时候起床，与句意相符。", "摔": "语义：“摔”指跌倒，问的是起床时间，与此不符。", "咳嗽": "语义：“咳嗽”指发出咳声，与问起床时间无关。", "胖": "语义：“胖”形容体形，不能用来问几点做什么。"}, "sentence_index": 6, "correct_answer": "起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他累了，要起一会儿。", "explanation": "这里应该用〈歇〉。起指身体离开床或座位，不表示休息；想休息要用歇。"}, {"text": "他起上了山顶。", "explanation": "这里应该用〈爬〉。起不表示攀登，爬上山顶要用爬。"}, {"text": "他起了一个电话。", "explanation": "这里应该用〈打〉。起不表示拨打，打电话要用打。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天起了得很早，精神很好。", "corrected_sentence": "他今天起得很早，精神很好。", "error_description": "补语错误：“起”后接程度补语“得很早”时不能再加“了”，应说“起得很早”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天要去爬山，我们起很早。", "corrected_sentence": "明天要去爬山，我们起得很早。", "error_description": "补语标记错误：“起”后接描述程度的补语要用“得”，应说“起得很早”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
