INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21990, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "试着做一件事。", "primary_collocate": null, "pronunciation": "cháng shì", "ipa": "ʈʂʰaŋ³⁵ ʂɨ⁵¹", "syllable_count": 2, "sentences": [{"text": "别怕，你先尝试一下。", "target_word": "尝试", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我尝试骑自行车上班。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟尝试爬上那棵树。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她尝试了好几次，才打开门。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们尝试自己回答问题。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我第一次尝试游泳，有点怕。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你尝试过写日记吗？", "target_word": "尝试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他尝试着站起来，可是腿很疼。", "target_word": "尝试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈尝试用新锅做饭。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想尝试学一门外语。", "target_word": "尝试", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "尝试了", "label": "体标"}, {"form": "尝试过", "label": "体标"}, {"form": "尝试着", "label": "体标"}], "register": "中性", "sense_fingerprint": "试着做一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尝试", "is_correct": true, "explanation": "正确答案，指试着做一件事，与听到的音相符。"}, {"text": "常识", "is_correct": false, "explanation": "声调不同：shí（第二声）与 shì（第四声），意思是常识。"}, {"text": "长史", "is_correct": false, "explanation": "声调不同：第二音节 shǐ（第三声）与 shì（第四声）不同，意思是古代官职名。"}, {"text": "长诗", "is_correct": false, "explanation": "声调不同：shī（第一声）与 shì（第四声），意思是长篇诗歌。"}], "explanations": {"尝试": "正确答案，指试着做一件事，与听到的音相符。", "常识": "声调不同：shí（第二声）与 shì（第四声），意思是常识。", "长史": "声调不同：第二音节 shǐ（第三声）与 shì（第四声）不同，意思是古代官职名。", "长诗": "声调不同：shī（第一声）与 shì（第四声），意思是长篇诗歌。"}, "sentence_index": null, "correct_answer": "尝试"}, "level_3": {"options": [{"text": "尝试", "is_correct": true, "explanation": "语义与搭配正确：“你先尝试一下”表示先试着做，与“别怕”的语气相符。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与“别怕”的安慰语气不合，句意不通。"}, {"text": "投降", "is_correct": false, "explanation": "语义：“投降”表示放弃抵抗，与“你先……一下”的鼓励语气矛盾。"}, {"text": "缔结", "is_correct": false, "explanation": "语域：“缔结”是书面正式用语，口语中不说“你先缔结一下”。"}], "explanations": {"尝试": "语义与搭配正确：“你先尝试一下”表示先试着做，与“别怕”的语气相符。", "逃跑": "语义：“逃跑”与“别怕”的安慰语气不合，句意不通。", "投降": "语义：“投降”表示放弃抵抗，与“你先……一下”的鼓励语气矛盾。", "缔结": "语域：“缔结”是书面正式用语，口语中不说“你先缔结一下”。"}, "sentence_index": 0, "correct_answer": "尝试"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天尝试吃饭，已经吃了三年。", "explanation": "这里应该用〈吃〉。“尝试”指试着做某事，日常吃饭是习惯性的行为，不用“尝试”。"}, {"text": "我尝试了一口咖啡，觉得太苦了。", "explanation": "这里应该用〈尝〉。品尝饮料的味道用“尝”，“尝试”指试着做事。"}, {"text": "我们尝试了一位老师，然后很高兴。", "explanation": "这里应该用〈见〉。见老师要用“见”，“尝试”的对象是做法，不能以人作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尝试", "is_correct": true, "explanation": "语义与搭配正确：“你尝试过写日记吗”询问是否试过写日记，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能接“写日记”，“你吃过写日记吗”句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的宾语应是歌曲，不能接“写日记”。"}, {"text": "刷", "is_correct": false, "explanation": "搭配：“刷”只与牙、锅等搭配，不能接“写日记”组成词组。"}], "explanations": {"尝试": "语义与搭配正确：“你尝试过写日记吗”询问是否试过写日记，与句意相符。", "吃": "语义：“吃”不能接“写日记”，“你吃过写日记吗”句意不通。", "唱": "语义：“唱”的宾语应是歌曲，不能接“写日记”。", "刷": "搭配：“刷”只与牙、锅等搭配，不能接“写日记”组成词组。"}, "sentence_index": 6, "correct_answer": "尝试"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生尝试了一下那个病人，然后开了药。", "explanation": "这里应该用〈检查〉。给病人做检查要用“检查”，“尝试”指试着做以了解效果。"}, {"text": "他尝试了那座房子，然后买下了它。", "explanation": "这里应该用〈看〉。看房子要用“看”，“尝试”不能直接以房子为宾语。"}, {"text": "她尝试了那个孩子，然后很放心。", "explanation": "这里应该用〈照顾〉。照顾孩子要用“照顾”，“尝试”不能接人作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我尝试着三次，都没成功。", "corrected_sentence": "我尝试过三次，都没成功。", "error_description": "体标错误：表示曾经做过的动作应用“过”，写成“尝试过三次”；“尝试着”表示动作进行，不能直接接数量“三次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们可以尝试一下子新方法。", "corrected_sentence": "我们可以尝试一下新方法。", "error_description": "“一下子”与动量补语“一下”混用：“一下子”是副词，表示突然或一次完成，不能放在动词后作动量补语。应写作“尝试一下”，“一下子”错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
