INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "音响是让声音变大、变好听的机器。", "primary_collocate": null, "pronunciation": "yīn xiǎng", "ipa": "in⁵⁵ ɕjɑŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "他买了一个新音响听音乐。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个音响能让声音变得更大。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里没有音响，听不到音乐。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给教室买一套音响。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音响坏了，老师的声音太小。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手机连上了音响。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个音响价格不高，声音却很清楚。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在厨房开着音响听歌。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有人带着音响跳舞。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把音响关小一点。", "target_word": "音响", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套音响", "label": "量词"}, {"form": "一台音响", "label": "量词"}, {"form": "音響", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让声音变大变好听的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21994, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "音响", "is_correct": true, "explanation": "正确：音响是让声音变大、变好听的机器，与释义一致。"}, {"text": "印象", "is_correct": false, "explanation": "yìnxiàng 与 yīnxiǎng 两个音节的声调都不同，意思是“印象”。"}, {"text": "影响", "is_correct": false, "explanation": "yǐngxiǎng 第一个音节是后鼻音 -ing、声调不同，与 yīnxiǎng 易混，意思是“影响”。"}, {"text": "音像", "is_correct": false, "explanation": "yīnxiàng 只有第二个音节的声调与 yīnxiǎng 不同，意思是“音像”。"}], "explanations": {"音响": "正确：音响是让声音变大、变好听的机器，与释义一致。", "印象": "yìnxiàng 与 yīnxiǎng 两个音节的声调都不同，意思是“印象”。", "影响": "yǐngxiǎng 第一个音节是后鼻音 -ing、声调不同，与 yīnxiǎng 易混，意思是“影响”。", "音像": "yīnxiàng 只有第二个音节的声调与 yīnxiǎng 不同，意思是“音像”。"}, "sentence_index": null, "correct_answer": "音响"}, "level_3": {"options": [{"text": "音响", "is_correct": true, "explanation": "正确：“买一个新音响听音乐”指能让声音变大变好听的机器，与上下文一致。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁是建筑构件，不能买来听音乐。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是视觉属性，不是可以买来播放声音的东西。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶用来插花，不能用来听音乐。"}], "explanations": {"音响": "正确：“买一个新音响听音乐”指能让声音变大变好听的机器，与上下文一致。", "墙壁": "语义：墙壁是建筑构件，不能买来听音乐。", "颜色": "语义：“颜色”是视觉属性，不是可以买来播放声音的东西。", "花瓶": "语义：花瓶用来插花，不能用来听音乐。"}, "sentence_index": 0, "correct_answer": "音响"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用音响烧开了一壶水。", "explanation": "这里应该用〈水壶〉。音响不能加热，烧开水要用水壶。"}, {"text": "他戴上音响在街上跑步。", "explanation": "这里应该用〈耳机〉。耳机戴在耳朵上，音响是放在房间里的大型设备，不能戴在身上。"}, {"text": "他用音响缝好了裤子上的破洞。", "explanation": "这里应该用〈针线〉。音响是放大声音的设备，缝补破洞要用针线，不能用音响。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音响", "is_correct": true, "explanation": "正确：“这个音响价格不高，声音却很清楚”说的是能发出清楚声音的设备，与上下文一致。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发没有声音，不能说声音很清楚。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是挂在窗上的布，不会发出声音，不能用“声音清楚”来描述。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“声音清楚”不能用来形容眼镜这类视觉物品。"}], "explanations": {"音响": "正确：“这个音响价格不高，声音却很清楚”说的是能发出清楚声音的设备，与上下文一致。", "沙发": "语义：沙发没有声音，不能说声音很清楚。", "窗帘": "语义：窗帘是挂在窗上的布，不会发出声音，不能用“声音清楚”来描述。", "眼镜": "搭配：“声音清楚”不能用来形容眼镜这类视觉物品。"}, "sentence_index": 6, "correct_answer": "音响"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用音响切了一块肉。", "explanation": "这里应该用〈刀〉。音响只用来放大和播放声音，切肉要用刀，音响不能当作切肉的工具。"}, {"text": "他每天给音响浇水。", "explanation": "这里应该用〈花〉。浇水只用于植物，音响是电子设备，不是植物，不能浇水。"}, {"text": "这台音响每天在操场上跑步。", "explanation": "这里应该用〈学生〉。跑步的主语应是人，音响是没有生命的设备，不能像人一样跑步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想给教室买一张音响，声音很好。", "corrected_sentence": "我想给教室买一台音响，声音很好。", "error_description": "错误：“一张音响”；正确：“一台音响”。“张”用于平面的物品，音响这类电器应该用“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一张新音响，听音乐很方便。", "corrected_sentence": "他买了一台新音响，听音乐很方便。", "error_description": "错误：“一张新音响”；正确：“一台新音响”。“张”用于平面的物品，音响这类电器应该用“台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
