INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21998, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "做事情非常准确，没有错误。", "primary_collocate": null, "pronunciation": "jīng què xìng", "ipa": "tɕiŋ⁵⁵ tɕʰɥe⁵¹ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "工人做零件时很重视精确性。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做实验时每一步都很注意精确性。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回答问题的精确性让老师很满意。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "射箭比赛看的是精确性。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人的动作有很高的精确性。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新软件提高了计算的精确性。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报的精确性越来越高。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做蛋糕时，量糖的精确性很重要。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要检查每个数据的精确性。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "精确性比速度更重要，别做得太快。", "target_word": "精确性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精確性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "做事非常准确、没有错误", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精确性", "is_correct": true, "explanation": "正确。“工人做零件时很重视精确性”指零件要做得准确、没有错误，与句意相符。"}, {"text": "随意性", "is_correct": false, "explanation": "语义：“随意性”指随便、不讲定准，与“很重视”做零件的要求相反。"}, {"text": "学术性", "is_correct": false, "explanation": "语域：“学术性”是专业研究用语，不用来形容工人做零件的要求，与句意不合。"}, {"text": "幽默性", "is_correct": false, "explanation": "语义：“幽默性”指引人发笑，与零件加工的严谨要求无关，句意不通。"}], "explanations": {"精确性": "正确。“工人做零件时很重视精确性”指零件要做得准确、没有错误，与句意相符。", "随意性": "语义：“随意性”指随便、不讲定准，与“很重视”做零件的要求相反。", "学术性": "语域：“学术性”是专业研究用语，不用来形容工人做零件的要求，与句意不合。", "幽默性": "语义：“幽默性”指引人发笑，与零件加工的严谨要求无关，句意不通。"}, "sentence_index": 0, "correct_answer": "精确性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "举重比赛看的是精确性。", "explanation": "这里应该用〈力量〉。精确性指做事准确、没有错误，举重比赛看的是举起重物的能力，要用力量。"}, {"text": "短跑比赛看的是精确性。", "explanation": "这里应该用〈速度〉。精确性指做事准确、没有错误，短跑比赛看的是快慢，要用速度。"}, {"text": "马拉松比赛看的是精确性。", "explanation": "这里应该用〈耐力〉。精确性指做事准确、没有错误，马拉松比赛看的是持久坚持，要用耐力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精确性", "is_correct": true, "explanation": "正确。“天气预报的精确性越来越高”指预报越来越准确，与句意相符。"}, {"text": "任意性", "is_correct": false, "explanation": "语义：“任意性”指随意、没有定准，与“越来越高”的提升趋势相反。"}, {"text": "文学性", "is_correct": false, "explanation": "语域：“文学性”是文艺评论用语，不用来形容天气预报，与语境不合。"}, {"text": "浪漫性", "is_correct": false, "explanation": "语义：“浪漫性”指富有诗意的情调，与天气预报追求准确的要求不符。"}], "explanations": {"精确性": "正确。“天气预报的精确性越来越高”指预报越来越准确，与句意相符。", "任意性": "语义：“任意性”指随意、没有定准，与“越来越高”的提升趋势相反。", "文学性": "语域：“文学性”是文艺评论用语，不用来形容天气预报，与语境不合。", "浪漫性": "语义：“浪漫性”指富有诗意的情调，与天气预报追求准确的要求不符。"}, "sentence_index": 6, "correct_answer": "精确性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡的精确性太高了，喝起来甜得发腻。", "explanation": "这里应该用〈甜度〉。精确性指做事准确、没有错误，咖啡甜的程度要用甜度。"}, {"text": "这块毛巾的精确性很好，摸起来很舒服。", "explanation": "这里应该用〈柔软性〉。精确性指做事准确、没有错误，毛巾摸起来舒服要用柔软性。"}, {"text": "这座山的精确性很高，爬上去要一整天。", "explanation": "这里应该用〈高度〉。精确性指做事准确、没有错误，山的高矮要用高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位技师的精确性的很高。", "corrected_sentence": "这位技师的精确性很高。", "error_description": "多出一个“的”。“的”已接在“技师”后面，“精确性”后应直接接谓语“很高”，不能再加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台仪器的精确性了很高。", "corrected_sentence": "这台仪器的精确性很高。", "error_description": "“了”误加在名词“精确性”后面。“精确性”后直接接“很高”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22000, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "野蛮", "is_correct": true, "explanation": "正确：“野蛮”与“文明”构成反义，指举止粗野、不讲礼貌。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”形容智力，与“文明”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”形容外貌，与“文明”没有反义关系。"}, {"text": "善良", "is_correct": false, "explanation": "无关：“善良”形容品性，与“文明”没有反义关系。"}], "correct_answer": "野蛮", "explanations": {"野蛮": "正确：“野蛮”与“文明”构成反义，指举止粗野、不讲礼貌。", "聪明": "无关：“聪明”形容智力，与“文明”没有反义关系。", "漂亮": "无关：“漂亮”形容外貌，与“文明”没有反义关系。", "善良": "无关：“善良”形容品性，与“文明”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22000, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "野蛮", "is_correct": true, "explanation": "正确：“野蛮”与“文明”构成反义，指不讲礼貌、粗野。"}, {"text": "勇敢", "is_correct": false, "explanation": "无关：“勇敢”形容胆量，与“文明”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "无关：“热情”形容待人的态度，与“文明”不构成反义。"}, {"text": "整洁", "is_correct": false, "explanation": "无关：“整洁”形容卫生状况，与“文明”没有反义关系。"}], "correct_answer": "野蛮", "explanations": {"野蛮": "正确：“野蛮”与“文明”构成反义，指不讲礼貌、粗野。", "勇敢": "无关：“勇敢”形容胆量，与“文明”没有反义关系。", "热情": "无关：“热情”形容待人的态度，与“文明”不构成反义。", "整洁": "无关：“整洁”形容卫生状况，与“文明”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22000, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "文明就是人们生活得很有礼貌，不打架，不乱扔垃圾。", "primary_collocate": null, "pronunciation": "wén míng", "ipa": "wən˧˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "在公共汽车上，请大家文明乘车。", "target_word": "文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很文明，从来不骂人。", "target_word": "文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的城市越来越文明了。", "target_word": "文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文明的人不会在街上乱扔垃圾。", "target_word": "文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看球赛要文明，不能打架。", "target_word": "文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的服务员很文明。", "target_word": "文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家文明排队，不要挤。", "target_word": "文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在老师的带领下文明参观。", "target_word": "文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个很文明的人，对谁都很有礼貌。", "target_word": "文明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车文明一点，大家都安全。", "target_word": "文明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不文明", "label": "否定"}], "register": "中性", "sense_fingerprint": "举止有礼貌、讲规矩的;文明行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61123057-4989-4a95-82bf-725897152c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文明", "is_correct": true, "explanation": "正确：“文明乘车”指有秩序、有礼貌地乘车，与“请大家”的语境一致。"}, {"text": "粗鲁地", "is_correct": false, "explanation": "语义：“粗鲁地”与“请大家”的礼貌语气相反，句子不合理。"}, {"text": "大声地", "is_correct": false, "explanation": "语义：“大声地”会打扰他人，与公共场合的要求相反。"}, {"text": "乱七八糟地", "is_correct": false, "explanation": "语义：“乱七八糟地”指没有秩序，与“请大家”有礼貌、有秩序乘车的要求相反。"}], "explanations": {"文明": "正确：“文明乘车”指有秩序、有礼貌地乘车，与“请大家”的语境一致。", "粗鲁地": "语义：“粗鲁地”与“请大家”的礼貌语气相反，句子不合理。", "大声地": "语义：“大声地”会打扰他人，与公共场合的要求相反。", "乱七八糟地": "语义：“乱七八糟地”指没有秩序，与“请大家”有礼貌、有秩序乘车的要求相反。"}, "sentence_index": 0, "correct_answer": "文明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小朋友脑子很文明，学习很快。", "explanation": "这里应该用〈聪明〉。“文明”指举止有礼貌，不能形容头脑；形容头脑灵活要用〈聪明〉。"}, {"text": "她长得很文明。", "explanation": "这里应该用〈漂亮〉。“文明”形容举止，形容外貌要用〈漂亮〉。"}, {"text": "她的数学成绩很文明。", "explanation": "这里应该用〈好〉。“文明”指举止有礼貌，不能用来形容成绩；形容成绩要用〈好〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文明", "is_correct": true, "explanation": "正确：“文明排队”指有秩序地排队，与“不要挤”相呼应，符合句意。"}, {"text": "推搡地", "is_correct": false, "explanation": "语义：“推搡地”与“不要挤”的要求正好相反。"}, {"text": "大声地", "is_correct": false, "explanation": "语义：“大声地”排队不合常理，句子说不通。"}, {"text": "乱糟糟地", "is_correct": false, "explanation": "语义：“乱糟糟地”指没有秩序，与“排队”“不要挤”的要求相反。"}], "explanations": {"文明": "正确：“文明排队”指有秩序地排队，与“不要挤”相呼应，符合句意。", "推搡地": "语义：“推搡地”与“不要挤”的要求正好相反。", "大声地": "语义：“大声地”排队不合常理，句子说不通。", "乱糟糟地": "语义：“乱糟糟地”指没有秩序，与“排队”“不要挤”的要求相反。"}, "sentence_index": 6, "correct_answer": "文明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑得很文明。", "explanation": "这里应该用〈快〉。“文明”形容举止有礼貌，形容速度要用〈快〉。"}, {"text": "这本书很文明。", "explanation": "这里应该用〈厚〉。“文明”不用于形容书的厚薄，这里要用〈厚〉。"}, {"text": "这个西瓜很文明。", "explanation": "这里应该用〈甜〉。“文明”形容人的举止，不能形容食物的味道，要用〈甜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子很文明地。", "corrected_sentence": "这个孩子很文明。", "error_description": "“地”是状语标记，后面须接动词；“很文明地”后面没有动词，句子不完整。应说“这个孩子很文明”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他文明的说话。", "corrected_sentence": "他文明地说话。", "error_description": "这里“的”用错：修饰动词“说话”的状语应写作“文明地说话”。（“文明排队”“文明参观”这类直接修饰动词的用法也成立，但此句用“的”不对。）", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
