INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22002, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一点点时间就很快没有了。", "primary_collocate": null, "pronunciation": "shāo zòng jí shì", "ipa": "ʂaʊ⁵⁵ tsʊŋ⁵¹ tɕi³⁵ ʂɨ⁵¹", "syllable_count": 4, "sentences": [{"text": "烟花稍纵即逝，一下子就看不到了。", "target_word": "稍纵即逝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夕阳的美稍纵即逝，几分钟后天就黑了。", "target_word": "稍纵即逝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脸上的笑容稍纵即逝。", "target_word": "稍纵即逝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天的花期稍纵即逝，要赶快去看。", "target_word": "稍纵即逝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快乐的时光稍纵即逝。", "target_word": "稍纵即逝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪落在手上，稍纵即逝。", "target_word": "稍纵即逝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打折的时间稍纵即逝，快去买吧。", "target_word": "稍纵即逝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她心里的想法稍纵即逝，没有说出口。", "target_word": "稍纵即逝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞过窗前，稍纵即逝。", "target_word": "稍纵即逝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期稍纵即逝，转眼又要上班了。", "target_word": "稍纵即逝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "很短的时间就消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稍纵即逝", "is_correct": true, "explanation": "正确：“稍纵即逝”形容烟花很快消失，与“一下子就看不到了”一致。"}, {"text": "永久", "is_correct": false, "explanation": "语义：“永久”指长期存在，与“一下子就看不到了”矛盾。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容物体质地，不用来形容烟花。"}, {"text": "冗长", "is_correct": false, "explanation": "搭配：“冗长”多形容文字、讲话或过程，不用来形容烟花。"}], "explanations": {"稍纵即逝": "正确：“稍纵即逝”形容烟花很快消失，与“一下子就看不到了”一致。", "永久": "语义：“永久”指长期存在，与“一下子就看不到了”矛盾。", "坚硬": "搭配：“坚硬”形容物体质地，不用来形容烟花。", "冗长": "搭配：“冗长”多形容文字、讲话或过程，不用来形容烟花。"}, "sentence_index": 0, "correct_answer": "稍纵即逝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天天气稍纵即逝，大家都要带伞。", "explanation": "这里应该用〈瞬息万变〉。稍纵即逝形容时光或机会很快消失，天气多变要用瞬息万变。"}, {"text": "这把椅子稍纵即逝。", "explanation": "这里应该用〈牢固〉。稍纵即逝说时间很快没有了，椅子能长期使用，表示结实要用牢固。"}, {"text": "这座古塔稍纵即逝，几百年来一直站在这里。", "explanation": "这里应该用〈屹立不倒〉。稍纵即逝说时间很快没有了，古塔几百年一直存在，要用屹立不倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稍纵即逝", "is_correct": true, "explanation": "正确：“稍纵即逝”说时间很快过去，与“快去买吧”的紧迫语气相合。"}, {"text": "漫长", "is_correct": false, "explanation": "语义：“漫长”说时间很久，与“快去买吧”矛盾，不需要急着买。"}, {"text": "无限", "is_correct": false, "explanation": "语义：“无限”说时间没有尽头，与“快去买吧”矛盾。"}, {"text": "稳定", "is_correct": false, "explanation": "搭配：“稳定”多用于局势、状态，不用来形容打折的时间。"}], "explanations": {"稍纵即逝": "正确：“稍纵即逝”说时间很快过去，与“快去买吧”的紧迫语气相合。", "漫长": "语义：“漫长”说时间很久，与“快去买吧”矛盾，不需要急着买。", "无限": "语义：“无限”说时间没有尽头，与“快去买吧”矛盾。", "稳定": "搭配：“稳定”多用于局势、状态，不用来形容打折的时间。"}, "sentence_index": 6, "correct_answer": "稍纵即逝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校稍纵即逝，已经有一百年了。", "explanation": "这里应该用〈历史悠久〉。稍纵即逝说时间很快没有了，学校存在了很久，要用历史悠久。"}, {"text": "她的书法功力稍纵即逝。", "explanation": "这里应该用〈深厚〉。稍纵即逝说时间很快没有了，书法功力是长期积累的能力，表示功底的程度要用深厚。"}, {"text": "这条大河稍纵即逝。", "explanation": "这里应该用〈奔流不息〉。稍纵即逝说时间很快没有了，大河长期存在、持续流动，应该表达这种持续的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏夜的流星稍纵即逝地，大家都抬头去看。", "corrected_sentence": "夏夜的流星稍纵即逝，大家都抬头去看。", "error_description": "多出“地”。“稍纵即逝”在此作谓语，后面不能接“地”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份稍纵即逝好心情，要好好珍惜。", "corrected_sentence": "这份稍纵即逝的好心情，要好好珍惜。", "error_description": "错误：“稍纵即逝好心情”；正确：“稍纵即逝的好心情”。“稍纵即逝”修饰名词时，中间需要加结构助词“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
