INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22004, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉别人该怎么做。", "primary_collocate": null, "pronunciation": "zhǐ shì", "ipa": "ʈʂɻ̩˨˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "经理指示我们今天把报告做完。", "target_word": "指示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师指示大家先看第一页。", "target_word": "指示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生指示他每天吃两次药。", "target_word": "指示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上级指示各部门马上检查安全。", "target_word": "指示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长指示老师们周五开会。", "target_word": "指示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长指示大家在门口等他。", "target_word": "指示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导指示过要早点完成这个工作。", "target_word": "指示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有指示我们怎么做。", "target_word": "指示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板指示秘书订两张机票。", "target_word": "指示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察指示司机把车停在路边。", "target_word": "指示", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指示了", "label": "体标"}, {"form": "指示过", "label": "体标"}], "register": "正式", "sense_fingerprint": "上级或长辈对别人说明应该怎么做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b61e398c-20aa-46ca-9d37-d0eb222c07e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22004, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指示", "is_correct": true, "explanation": "正确。听到的是 zhǐ shì，意思是告诉别人该怎么做。"}, {"text": "芝士", "is_correct": false, "explanation": "声调不同：zhī（第一声）与 zhǐ（第三声）声调不同，第二个音节相同，意思是奶酪（cheese 的音译）。"}, {"text": "直视", "is_correct": false, "explanation": "声调不同：zhí（第二声）与 zhǐ（第三声）声调不同，第二个音节相同，意思是笔直地看着。"}, {"text": "知识", "is_correct": false, "explanation": "第一个音节 zhī（第一声）与 zhǐ（第三声）声调不同，第二个音节读轻声，意思是学到的认识。"}], "explanations": {"指示": "正确。听到的是 zhǐ shì，意思是告诉别人该怎么做。", "芝士": "声调不同：zhī（第一声）与 zhǐ（第三声）声调不同，第二个音节相同，意思是奶酪（cheese 的音译）。", "直视": "声调不同：zhí（第二声）与 zhǐ（第三声）声调不同，第二个音节相同，意思是笔直地看着。", "知识": "第一个音节 zhī（第一声）与 zhǐ（第三声）声调不同，第二个音节读轻声，意思是学到的认识。"}, "sentence_index": null, "correct_answer": "指示"}, "level_3": {"options": [{"text": "指示", "is_correct": true, "explanation": "正确。“指示”指上级对别人说明该怎么做，这里是经理下达安排。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑别人，不能用来引出“我们今天把报告做完”这样的安排。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：微笑是不及物动词，不能带“我们今天把报告做完”这样的宾语。"}, {"text": "叹气", "is_correct": false, "explanation": "配价：叹气是不及物动词，后面不能直接接“我们今天把报告做完”这样的句子。"}], "explanations": {"指示": "正确。“指示”指上级对别人说明该怎么做，这里是经理下达安排。", "嘲笑": "语义：嘲笑是取笑别人，不能用来引出“我们今天把报告做完”这样的安排。", "微笑": "配价：微笑是不及物动词，不能带“我们今天把报告做完”这样的宾语。", "叹气": "配价：叹气是不及物动词，后面不能直接接“我们今天把报告做完”这样的句子。"}, "sentence_index": 0, "correct_answer": "指示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的微笑指示他很高兴。", "explanation": "这里应该用〈表示〉。指示是上级对下级的安排，表明心情要说〈表示〉。"}, {"text": "这条新闻指示了一个重要的消息。", "explanation": "这里应该用〈报道〉。指示是下达安排，传播消息要说〈报道〉。"}, {"text": "他指示了我的错误。", "explanation": "这里应该用〈指出〉。指示是下达安排，把别人的错误点明要说〈指出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22004, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "指示", "is_correct": true, "explanation": "正确。听到的是 zhǐ shì，意思是告诉别人该怎么做。"}, {"text": "知事", "is_correct": false, "explanation": "声调不同：zhī（第一声）与 zhǐ（第三声）声调不同，第二个音节相同，意思是旧时地方行政长官。"}, {"text": "执事", "is_correct": false, "explanation": "声调不同：zhí（第二声）与 zhǐ（第三声）声调不同，第二个音节相同，意思是旧时管事的人，也指负责处理事务的人。"}, {"text": "制式", "is_correct": false, "explanation": "声调不同：zhì（第四声）与 zhǐ（第三声）声调不同，意思是统一规定的样式。"}], "explanations": {"指示": "正确。听到的是 zhǐ shì，意思是告诉别人该怎么做。", "知事": "声调不同：zhī（第一声）与 zhǐ（第三声）声调不同，第二个音节相同，意思是旧时地方行政长官。", "执事": "声调不同：zhí（第二声）与 zhǐ（第三声）声调不同，第二个音节相同，意思是旧时管事的人，也指负责处理事务的人。", "制式": "声调不同：zhì（第四声）与 zhǐ（第三声）声调不同，意思是统一规定的样式。"}, "sentence_index": null, "correct_answer": "指示"}, "level_3": {"options": [{"text": "指示", "is_correct": true, "explanation": "正确。“指示”指上级对别人下达要求，这里“领导指示过”引出“要早点完成这个工作”。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：游泳是不及物动词，不能带“要早点完成这个工作”作宾语。"}, {"text": "哭", "is_correct": false, "explanation": "配价：哭是不及物动词，不能带“要早点完成这个工作”这样的宾语。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是走路活动，与给出工作要求无关。"}], "explanations": {"指示": "正确。“指示”指上级对别人下达要求，这里“领导指示过”引出“要早点完成这个工作”。", "游泳": "配价：游泳是不及物动词，不能带“要早点完成这个工作”作宾语。", "哭": "配价：哭是不及物动词，不能带“要早点完成这个工作”这样的宾语。", "散步": "语义：散步是走路活动，与给出工作要求无关。"}, "sentence_index": 6, "correct_answer": "指示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我指示大家的帮助。", "explanation": "这里应该用〈感谢〉。指示是下达安排，对别人的帮助表示谢意要说〈感谢〉。"}, {"text": "老师指示了他的努力。", "explanation": "这里应该用〈表扬〉。指示是下达安排，肯定别人的努力要说〈表扬〉。"}, {"text": "他在社区指示环保知识。", "explanation": "这里应该用〈宣传〉。指示是对具体行动的安排，向大众传播环保知识要说〈宣传〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "主任昨天已经指示着我们把房间打扫干净。", "corrected_sentence": "主任昨天已经指示我们把房间打扫干净。", "error_description": "错误形式：“指示着”；正确形式：“指示”。“昨天已经”表示指示已经完成，不能用表示持续的“着”，应去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把任务指示很清楚。", "corrected_sentence": "他把任务指示得很清楚。", "error_description": "错误：漏掉了补语的“得”。“指示”后要用“得”引出情态补语，应说“指示得很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
