INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22006, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22006, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "能让人明白一件事的性质。", "primary_collocate": null, "pronunciation": "tí shì xìng", "ipa": "tʰi³⁵ ʂɻ̩⁵¹ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "这张图的提示性很清楚，一看就懂。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答有提示性，我马上明白了。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段说明的提示性很强，读一遍就懂。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了一个提示性的问题。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个符号有很强的提示性。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路牌的提示性不够，我们走错了路。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的眼神很有提示性，我知道该停了。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些颜色的提示性让孩子容易分清。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书的图片提示性很好。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的标题要有提示性，让人知道内容。", "target_word": "提示性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "能让人明白一件事的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '677953e1-536a-4b77-a1de-d380c0f30240') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提示性", "is_correct": true, "explanation": "正确。“提示性很清楚”说的是图能给人提示，与后句“一看就懂”相符。"}, {"text": "复杂性", "is_correct": false, "explanation": "语义：“复杂性”指繁杂，与“很清楚，一看就懂”相反，句意不通。"}, {"text": "艺术性", "is_correct": false, "explanation": "语义：“艺术性”指审美价值，与“一看就懂”的说明功能无关。"}, {"text": "学术性", "is_correct": false, "explanation": "语域：“学术性”是专业研究用语，与口语化的“一看就懂”语域不合。"}], "explanations": {"提示性": "正确。“提示性很清楚”说的是图能给人提示，与后句“一看就懂”相符。", "复杂性": "语义：“复杂性”指繁杂，与“很清楚，一看就懂”相反，句意不通。", "艺术性": "语义：“艺术性”指审美价值，与“一看就懂”的说明功能无关。", "学术性": "语域：“学术性”是专业研究用语，与口语化的“一看就懂”语域不合。"}, "sentence_index": 0, "correct_answer": "提示性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的提示性很强，让人很紧张。", "explanation": "这里应该用〈挑战性〉。提示性指能让人明白事情，考试的难度令人紧张要用挑战性。"}, {"text": "这部动画的提示性很强，孩子们笑个不停。", "explanation": "这里应该用〈娱乐性〉。提示性指让人明白事情，动画使孩子发笑要用娱乐性。"}, {"text": "这台机器的提示性很好，每天都能正常运行。", "explanation": "这里应该用〈稳定性〉。提示性指让人明白事情，机器持续正常运转要用稳定性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提示性", "is_correct": true, "explanation": "正确。“有提示性”说眼神能给人暗示，与后句“我知道该停了”相符。"}, {"text": "随机性", "is_correct": false, "explanation": "语义：“随机性”指无规律、靠偶然，与“我知道该停了”的明确示意不符。"}, {"text": "学术性", "is_correct": false, "explanation": "语域：“学术性”是专业研究用语，不用来形容眼神，句意不通。"}, {"text": "装饰性", "is_correct": false, "explanation": "语义：“装饰性”指美化外观，与眼神传递“该停了”的示意作用无关。"}], "explanations": {"提示性": "正确。“有提示性”说眼神能给人暗示，与后句“我知道该停了”相符。", "随机性": "语义：“随机性”指无规律、靠偶然，与“我知道该停了”的明确示意不符。", "学术性": "语域：“学术性”是专业研究用语，不用来形容眼神，句意不通。", "装饰性": "语义：“装饰性”指美化外观，与眼神传递“该停了”的示意作用无关。"}, "sentence_index": 6, "correct_answer": "提示性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个段子的提示性很强，大家都笑了。", "explanation": "这里应该用〈幽默性〉。提示性指让人明白事情，段子引人发笑要用幽默性。"}, {"text": "这份文件的提示性很强，只有领导能看。", "explanation": "这里应该用〈保密性〉。提示性指让人明白事情，限制他人查看要用保密性。"}, {"text": "这种杯子的提示性很好，能耐高温。", "explanation": "这里应该用〈耐热性〉。提示性指让人明白事情，杯子承受高温要用耐热性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张地图的提示性的很好。", "corrected_sentence": "这张地图的提示性很好。", "error_description": "多出一个“的”。“的”已接在“地图”后面，“提示性”后应直接接谓语“很好”，不能再加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个指示牌的提示性了很好。", "corrected_sentence": "这个指示牌的提示性很好。", "error_description": "“了”误加在名词“提示性”后面。“提示性”后直接接“很好”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897ec96f-ae45-4199-905e-a3cadaccbe81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
