INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22008, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或东西去抓住正在动的东西。", "primary_collocate": null, "pronunciation": "bǔ zhuō", "ipa": "pu˨˩˦ ʈʂwo˥˥", "syllable_count": 2, "sentences": [{"text": "猫正在捕捉桌子上的小虫。", "target_word": "捕捉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用网捕捉花园里的蝴蝶。", "target_word": "捕捉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们拿着小瓶，想捕捉飞来飞去的萤火虫。", "target_word": "捕捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青蛙一伸舌头，就捕捉到了一只苍蝇。", "target_word": "捕捉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔夫用大网捕捉水里的鱼。", "target_word": "捕捉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老鹰在天上捕捉地面上的兔子。", "target_word": "捕捉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手捕捉水里游动的小鱼。", "target_word": "捕捉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜘蛛织网是为了捕捉飞虫。", "target_word": "捕捉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我小时候在河边捕捉过小鱼。", "target_word": "捕捉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚊子飞得太快，我很难捕捉到它。", "target_word": "捕捉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "捕捉了", "label": "体标"}, {"form": "捕捉过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：用手或工具抓住正在活动的动物或小东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8255edc7-1bda-449e-b03b-0b60ad03ab09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捕捉", "is_correct": true, "explanation": "捕捉：用爪子抓住正在活动的小虫，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于坏了的器物，不能用于活的小虫。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：猫不会“收藏”小虫，与“正在……桌子上”的动作不符。"}, {"text": "打磨", "is_correct": false, "explanation": "搭配：“打磨”用于器物或玉石，不能说打磨小虫。"}], "explanations": {"捕捉": "捕捉：用爪子抓住正在活动的小虫，符合句意。", "修理": "搭配：“修理”用于坏了的器物，不能用于活的小虫。", "收藏": "语义：猫不会“收藏”小虫，与“正在……桌子上”的动作不符。", "打磨": "搭配：“打磨”用于器物或玉石，不能说打磨小虫。"}, "sentence_index": 0, "correct_answer": "捕捉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快捕捉到了桌上的书。", "explanation": "这里应该用〈拿〉。捕捉用于抓住正在活动的东西，桌上静止的书只能用拿。"}, {"text": "他一把捕捉了椅子腿。", "explanation": "这里应该用〈抓住〉。捕捉针对正在活动的小东西，椅子腿是静止的，要用抓住。"}, {"text": "他紧紧捕捉住了妈妈的手，怎么也不肯松开。", "explanation": "这里应该用〈握住〉。捕捉用于抓正在活动的东西，妈妈的手是静止的，紧紧握住要用握住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捕捉", "is_correct": true, "explanation": "捕捉：用手抓住水中活动的小鱼，符合句意。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：“缝补”针对破损的布料或衣物，与小鱼无关。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于枝叶、头发等，不用于活着的鱼。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“包装”用于商品，不能说“包装游动的小鱼”。"}], "explanations": {"捕捉": "捕捉：用手抓住水中活动的小鱼，符合句意。", "缝补": "语义：“缝补”针对破损的布料或衣物，与小鱼无关。", "修剪": "搭配：“修剪”用于枝叶、头发等，不用于活着的鱼。", "包装": "搭配：“包装”用于商品，不能说“包装游动的小鱼”。"}, "sentence_index": 6, "correct_answer": "捕捉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人一起使劲，捕捉起了那块大石头。", "explanation": "这里应该用〈搬〉。捕捉用于抓正在活动的东西，石头是静止的，要说搬起。"}, {"text": "他用手一按，就捕捉住了桌上的纸。", "explanation": "这里应该用〈按住〉。捕捉针对活动的东西，纸张静止，要说按住。"}, {"text": "她在树上捕捉了一个苹果。", "explanation": "这里应该用〈摘〉。捕捉用于抓正在活动的东西，树上的苹果是静止的，要说摘下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候曾捕捉了过一只蝴蝶。", "corrected_sentence": "我小时候曾捕捉过一只蝴蝶。", "error_description": "体标错误：“捕捉”后只能用“过”表示经历过，不能同时用“了”，说“捕捉了过”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫把那只老鼠捕捉。", "corrected_sentence": "猫把那只老鼠捕捉住了。", "error_description": "补语错误：“把”字句中动词后要有补语或“了”等成分，只说“把那只老鼠捕捉”不完整，应说“捕捉住了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e956bd7-ba43-4da4-9086-c22e0b76dbf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
