INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "单个的书写文字或符号，如‘大’；与由字组成的词（如‘大家’）相对。", "primary_collocate": null, "pronunciation": "zì fú", "ipa": "tsɨ˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "中文处理通常以字符或词为单位。", "target_word": "字符", "complexity_tier": "T3", "furigana": "zhōng wén chǔ lǐ tōng cháng yǐ zì fú huò cí wéi dān wèi.", "sentence_source": "generated"}, {"text": "这篇短文一共有两百个字符。", "target_word": "字符", "complexity_tier": "T3", "furigana": "zhè piān duǎn wén yí gòng yǒu liǎng bǎi gè zì fú.", "sentence_source": "generated"}, {"text": "这个程序能统计文章里的字符和词。", "target_word": "字符", "complexity_tier": "T3", "furigana": "zhè gè chéng xù néng tǒng jì wén zhāng lǐ de zì fú hé cí.", "sentence_source": "generated"}, {"text": "这个软件可以把句子切分成字符。", "target_word": "字符", "complexity_tier": "T3", "furigana": "zhè gè ruǎn jiàn kě yǐ bǎ jù zi qiē fēn chéng zì fú.", "sentence_source": "generated"}, {"text": "这种编码最多能表示六万多个字符。", "target_word": "字符", "complexity_tier": "T3", "furigana": "zhè zhǒng biān mǎ zuì duō néng biǎo shì liù wàn duō gè zì fú.", "sentence_source": "generated"}, {"text": "这份扫描件里的字符很模糊，识别率低。", "target_word": "字符", "complexity_tier": "T3", "furigana": "zhè fèn sǎo miáo jiàn lǐ de zì fú hěn mó hu, shí bié lǜ dī.", "sentence_source": "generated"}, {"text": "我们的模型先学习字符，再学习词语。", "target_word": "字符", "complexity_tier": "T3", "furigana": "wǒ men de mó xíng xiān xué xí zì fú, zài xué xí cí yǔ.", "sentence_source": "generated"}, {"text": "汉语的字符远比英文字母多得多。", "target_word": "字符", "complexity_tier": "T3", "furigana": "hàn yǔ de zì fú yuǎn bǐ yīng wén zì mǔ duō de duō.", "sentence_source": "generated"}, {"text": "屏幕上的字符太小，我看不清。", "target_word": "字符", "complexity_tier": "T3", "furigana": "píng mù shàng de zì fú tài xiǎo, wǒ kàn bù qīng.", "sentence_source": "generated"}, {"text": "我们把每个词拆开，再看里面的字符。", "target_word": "字符", "complexity_tier": "T3", "furigana": "wǒ men bǎ měi gè cí chāi kāi, zài kàn lǐ miàn de zì fú.", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "字符串", "label": "复合"}, {"form": "字符集", "label": "复合"}], "register": "中性", "sense_fingerprint": "单个书写文字，区别于由字组成的词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5516fdd-9a58-4c2f-a23e-f5845a48af52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22012, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "字符", "is_correct": true, "explanation": "正确答案。字符指单个的书写文字，读作 zì fú。"}, {"text": "制服", "is_correct": false, "explanation": "zhì（zh）与 zì（z）声母不同，制服意思是统一样式的服装。"}, {"text": "自负", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，自负意思是自以为了不起。"}, {"text": "赐福", "is_correct": false, "explanation": "cì（第四声）与 zì（第四声）声母不同（c 与 z），意思是赐予福气。"}], "explanations": {"字符": "正确答案。字符指单个的书写文字，读作 zì fú。", "制服": "zhì（zh）与 zì（z）声母不同，制服意思是统一样式的服装。", "自负": "fù（第四声）与 fú（第二声）声调不同，自负意思是自以为了不起。", "赐福": "cì（第四声）与 zì（第四声）声母不同（c 与 z），意思是赐予福气。"}, "sentence_index": null, "correct_answer": "字符"}, "level_3": {"options": [{"text": "字符", "is_correct": true, "explanation": "正确答案。句中“字符或词”指字和词两种单位，应用“字符”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是语言的单位，与“或词为单位”的说法不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气候状况，不能作为中文处理的单位。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“为单位”要求可计量的语言单位，“脚步”不能用作处理中文的单位。"}], "explanations": {"字符": "正确答案。句中“字符或词”指字和词两种单位，应用“字符”。", "颜色": "语义：颜色不是语言的单位，与“或词为单位”的说法不合。", "天气": "语义：天气指气候状况，不能作为中文处理的单位。", "脚步": "搭配：“为单位”要求可计量的语言单位，“脚步”不能用作处理中文的单位。"}, "sentence_index": 0, "correct_answer": "字符"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首乐曲的字符很动听。", "explanation": "这里应该用〈旋律〉。字符指单个书写文字，不能用来形容乐曲的旋律。"}, {"text": "这道菜的字符很好。", "explanation": "这里应该用〈味道〉。字符指单个书写文字，不能用来说菜的味道。"}, {"text": "他的字符很丰富。", "explanation": "这里应该用〈词汇〉。字符指单个书写文字，不能用来说一个人掌握的词语多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22012, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "字符", "is_correct": true, "explanation": "正确答案。字符指单个的书写文字，读作 zì fú。"}, {"text": "自付", "is_correct": false, "explanation": "fù（第四声）与 fú（第二声）声调不同，自付意思是自己付钱。"}, {"text": "赐福", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），赐福意思是赐予福气。"}, {"text": "制伏", "is_correct": false, "explanation": "zhì（zh）与 zì（z）声母不同，制伏意思是制服、征服，不是字符。"}], "explanations": {"字符": "正确答案。字符指单个的书写文字，读作 zì fú。", "自付": "fù（第四声）与 fú（第二声）声调不同，自付意思是自己付钱。", "赐福": "cì 与 zì 声母不同（c 与 z），赐福意思是赐予福气。", "制伏": "zhì（zh）与 zì（z）声母不同，制伏意思是制服、征服，不是字符。"}, "sentence_index": null, "correct_answer": "字符"}, "level_3": {"options": [{"text": "字符", "is_correct": true, "explanation": "正确答案。模型先学习的是单个的书写文字，应用“字符”。"}, {"text": "灯火", "is_correct": false, "explanation": "语义：灯火指灯光，不是模型学习的语言单位。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵与学习语言单位无关。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“学习”的对象是知识、语言、技能，“窗户”不能被学习。"}], "explanations": {"字符": "正确答案。模型先学习的是单个的书写文字，应用“字符”。", "灯火": "语义：灯火指灯光，不是模型学习的语言单位。", "云朵": "语义：云朵与学习语言单位无关。", "窗户": "搭配：“学习”的对象是知识、语言、技能，“窗户”不能被学习。"}, "sentence_index": 6, "correct_answer": "字符"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的字符很温柔。", "explanation": "这里应该用〈笑容〉。字符指单个书写文字，不能用来形容表情。"}, {"text": "他说话的字符很平静。", "explanation": "这里应该用〈语调〉。字符指单个书写文字，不能用来形容说话的语调。"}, {"text": "她的字符很苗条。", "explanation": "这里应该用〈身材〉。字符指单个书写文字，不能用来形容人的身材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份资料里有很多字符们。", "corrected_sentence": "这份资料里有很多字符。", "error_description": "复数错误：“字符”前面已有“很多”，不能再加“们”。“们”只用于指人，不用于“字符”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个模型一共认识了五千本字符。", "corrected_sentence": "这个模型一共认识了五千个字符。", "error_description": "量词错误：“字符”应该用“个”，不能用“本”。“本”多用于书籍、册子，不用于“字符”，应说“五千个字符”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
