INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22014, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "还没有的意思，比如“我还没吃饭”。", "primary_collocate": null, "pronunciation": "wèi", "ipa": "weɪ˥˩", "syllable_count": 1, "sentences": [{"text": "他还未回家，妈妈很担心。", "target_word": "未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我还未告诉任何人。", "target_word": "未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议还未开始，大家已经坐好了。", "target_word": "未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到现在，我们未收到他的信。", "target_word": "未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天未亮，他就起床了。", "target_word": "未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业未做完，不能出去玩。", "target_word": "未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病未好，今天不能上班。", "target_word": "未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我未吃早饭，现在很饿。", "target_word": "未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门未关，小猫跑出去了。", "target_word": "未", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师未到，同学们先看书。", "target_word": "未", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未必", "label": "复合"}, {"form": "尚未", "label": "复合"}], "register": "书面语", "sense_fingerprint": "还没有，表示事情尚未发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62f285c-3fff-4d83-96f3-aac2e819e030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未", "is_correct": true, "explanation": "正确：「未」表示尚未发生，与「还」连用，符合句意。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」修饰形容词，不能修饰动词「回家」，句子不通。"}, {"text": "很", "is_correct": false, "explanation": "搭配：「很」修饰形容词，不能直接修饰动词「回家」。"}, {"text": "太", "is_correct": false, "explanation": "搭配：「太」表示过分，与「回家」不搭配。"}], "explanations": {"未": "正确：「未」表示尚未发生，与「还」连用，符合句意。", "非常": "搭配：「非常」修饰形容词，不能修饰动词「回家」，句子不通。", "很": "搭配：「很」修饰形容词，不能直接修饰动词「回家」。", "太": "搭配：「太」表示过分，与「回家」不搭配。"}, "sentence_index": 0, "correct_answer": "未"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天未去学校。", "explanation": "这里应该用〈不〉。「未」指已经或应当发生的事还没有发生，将来的否定口语要用「不」。"}, {"text": "这家店的菜未好吃。", "explanation": "这里应该用〈不〉。「未」多表示尚未发生的动作或变化，描述菜的口味要用「不」。"}, {"text": "我未是学生。", "explanation": "这里应该用〈不是〉。「未」表示尚未发生，判断句的否定要用「不是」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未", "is_correct": true, "explanation": "正确：「未」表示尚未，与「病」和「不能上班」的因果相符。"}, {"text": "最", "is_correct": false, "explanation": "语义：「最好」表示程度最高，与「不能上班」的因果矛盾。"}, {"text": "更", "is_correct": false, "explanation": "语义：「更好」与「不能上班」的句意矛盾。"}, {"text": "挺", "is_correct": false, "explanation": "语域：「挺」口语色彩强，与书面语的「未」不协调，且句意矛盾。"}], "explanations": {"未": "正确：「未」表示尚未，与「病」和「不能上班」的因果相符。", "最": "语义：「最好」表示程度最高，与「不能上班」的因果矛盾。", "更": "语义：「更好」与「不能上班」的句意矛盾。", "挺": "语域：「挺」口语色彩强，与书面语的「未」不协调，且句意矛盾。"}, "sentence_index": 6, "correct_answer": "未"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都未早起。", "explanation": "这里应该用〈不〉。「未」指尚未发生的动作，习惯性的否定要用「不」。"}, {"text": "他未喜欢吃辣。", "explanation": "这里应该用〈不〉。「未」多指动作尚未发生，表示喜好的否定要用「不」。"}, {"text": "我未在乎你的看法。", "explanation": "这里应该用〈不在乎〉。「未」表示尚未发生，表示态度上的否定要用「不」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们还未没开始，你先等等。", "corrected_sentence": "我们还未开始，你先等等。", "error_description": "「未」与「没」不能叠用，「还未」之后不再加「没」，应为「还未开始」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的伤未还痊愈，不能参加比赛。", "corrected_sentence": "他的伤还未痊愈，不能参加比赛。", "error_description": "「还」和「未」的语序错误，应为「还未」，不能说「未还」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
