INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22024, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情的小部分。", "primary_collocate": null, "pronunciation": "xì jié", "ipa": "ɕi˥˩ tɕje˧˥", "syllable_count": 2, "sentences": [{"text": "他讲故事时，连小细节都不放过。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的细节我已经忘了。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旅行的细节写在本子上。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成功常常取决于细节。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求大家检查工作中的细节。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能说说事故的细节吗？", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些细节会影响比赛的结果。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有讲细节，只讲了大意。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的生活细节写得很生动。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对每个细节都很认真。", "target_word": "细节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "細節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情中不起眼的小部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5516fdd-9a58-4c2f-a23e-f5845a48af52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "细节", "is_correct": true, "explanation": "正确答案。细节指事情中不起眼的小部分，读作 xì jié。"}, {"text": "季节", "is_correct": false, "explanation": "jì（第四声）与 xì（第四声）声母不同，季节意思是一年中的春夏秋冬。"}, {"text": "气节", "is_correct": false, "explanation": "qì（第四声）与 xì（第四声）声母不同，气节意思是坚守的节操。"}, {"text": "洗劫", "is_correct": false, "explanation": "xǐ（第三声）与 xì（第四声）声调不同，洗劫意思是把财物抢光。"}], "explanations": {"细节": "正确答案。细节指事情中不起眼的小部分，读作 xì jié。", "季节": "jì（第四声）与 xì（第四声）声母不同，季节意思是一年中的春夏秋冬。", "气节": "qì（第四声）与 xì（第四声）声母不同，气节意思是坚守的节操。", "洗劫": "xǐ（第三声）与 xì（第四声）声调不同，洗劫意思是把财物抢光。"}, "sentence_index": null, "correct_answer": "细节"}, "level_3": {"options": [{"text": "细节", "is_correct": true, "explanation": "正确答案。句中说“连小细节都不放过”，指故事中的小部分。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：讲故事时不放过的是情节和内容，颜色不能作为讲述的对象。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与讲故事的内容无关。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能与“讲故事”中的“小”部分搭配。"}], "explanations": {"细节": "正确答案。句中说“连小细节都不放过”，指故事中的小部分。", "颜色": "语义：讲故事时不放过的是情节和内容，颜色不能作为讲述的对象。", "天气": "语义：天气与讲故事的内容无关。", "身材": "体貌：身材指人的体形，不能与“讲故事”中的“小”部分搭配。"}, "sentence_index": 0, "correct_answer": "细节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯水的细节很烫。", "explanation": "这里应该用〈温度〉。细节指事情中的小部分，不能用来说水的冷热。"}, {"text": "这个孩子的细节很活泼。", "explanation": "这里应该用〈性格〉。细节指事情的小部分，不能用来形容人的性格。"}, {"text": "这辆车的细节很快。", "explanation": "这里应该用〈速度〉。细节指事情的小部分，不能用来说车的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22024, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "细节", "is_correct": true, "explanation": "正确答案。细节指事情中不起眼的小部分，读作 xì jié。"}, {"text": "戏剧", "is_correct": false, "explanation": "xì jù 与 xì jié 第一个音节相同，第二个音节韵母不同；戏剧指舞台表演艺术。"}, {"text": "细则", "is_correct": false, "explanation": "xì zé 与 xì jié 第一个音节相同，第二个音节声母不同；细则指具体的规则条文。"}, {"text": "细菌", "is_correct": false, "explanation": "xì jūn 与 xì jié 第一个音节相同，第二个音节韵母不同；细菌指微小的生物。"}], "explanations": {"细节": "正确答案。细节指事情中不起眼的小部分，读作 xì jié。", "戏剧": "xì jù 与 xì jié 第一个音节相同，第二个音节韵母不同；戏剧指舞台表演艺术。", "细则": "xì zé 与 xì jié 第一个音节相同，第二个音节声母不同；细则指具体的规则条文。", "细菌": "xì jūn 与 xì jié 第一个音节相同，第二个音节韵母不同；细菌指微小的生物。"}, "sentence_index": null, "correct_answer": "细节"}, "level_3": {"options": [{"text": "细节", "is_correct": true, "explanation": "正确答案。句中说“会影响比赛的结果”，指事情中的小部分。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词是歌曲的文字，不能影响比赛的结果。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料是绘画用的材料，与比赛结果无关。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：面容指人的相貌，一般不会被说成影响比赛结果的因素。"}], "explanations": {"细节": "正确答案。句中说“会影响比赛的结果”，指事情中的小部分。", "歌词": "语义：歌词是歌曲的文字，不能影响比赛的结果。", "颜料": "语义：颜料是绘画用的材料，与比赛结果无关。", "面容": "体貌：面容指人的相貌，一般不会被说成影响比赛结果的因素。"}, "sentence_index": 6, "correct_answer": "细节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个包的细节很高。", "explanation": "这里应该用〈价钱〉。细节指事情的小部分，不能用来说东西价钱的高低。"}, {"text": "这首歌的细节很大。", "explanation": "这里应该用〈音量〉。细节指事情中的小部分，不能用来说歌曲的音量大小。"}, {"text": "他的细节很大了。", "explanation": "这里应该用〈年龄〉。细节指事情的小部分，不能用来说人的年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事的每条细节我都记得。", "corrected_sentence": "这件事的每个细节我都记得。", "error_description": "量词错误：“细节”应该用“个”，“条”多用于线、消息等，不用于“细节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我只记得几个细节们。", "corrected_sentence": "我只记得几个细节。", "error_description": "复数错误：“细节”是事情的小部分，不能加“们”。“们”只用于指人，应说“几个细节”，不说“几个细节们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2937c6e-0bec-4e7d-bb53-6f421e9727a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
