INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22036, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉别人应该怎么做，别人就要照着做。", "primary_collocate": null, "pronunciation": "guī dìng", "ipa": "kweɪ̯˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学校规定，学生早上八点前要到教室。", "target_word": "规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司规定，上班时不能玩手机。", "target_word": "规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师规定我们每天写一篇日记。", "target_word": "规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律规定，开车的人必须系安全带。", "target_word": "规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院规定，病人的家人晚上八点后不能进来。", "target_word": "规定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈规定我晚上十点以前一定要睡觉。", "target_word": "规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛规定每个人只能报一个项目。", "target_word": "规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆规定，借的书要在一个月内还。", "target_word": "规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店规定，客人不能带狗进来。", "target_word": "规定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸规定了我们每周只能玩两小时游戏。", "target_word": "规定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "规定了", "label": "体标"}, {"form": "规定过", "label": "体标"}], "register": "中性", "sense_fingerprint": "规定：用命令或制度要求别人必须照着做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17259789-fe49-4308-9f94-df080a361105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22036, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规定", "is_correct": true, "explanation": "「学校规定」表示学校用制度要求学生，与后句的要求相合。"}, {"text": "祝愿", "is_correct": false, "explanation": "语义：「祝愿」是表达美好的心愿，不能引出学校对学生的要求。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：「喜欢」表示爱好，不能引出这样的制度性要求。"}, {"text": "散步", "is_correct": false, "explanation": "配价：「散步」是不及物动词，后面不能接「学生……」这样的小句。"}], "explanations": {"规定": "「学校规定」表示学校用制度要求学生，与后句的要求相合。", "祝愿": "语义：「祝愿」是表达美好的心愿，不能引出学校对学生的要求。", "喜欢": "语义：「喜欢」表示爱好，不能引出这样的制度性要求。", "散步": "配价：「散步」是不及物动词，后面不能接「学生……」这样的小句。"}, "sentence_index": 0, "correct_answer": "规定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我规定昨天很开心。", "explanation": "这里应该用〈觉得〉。规定是对别人提出的要求，表达个人的感受要用觉得。"}, {"text": "天气预报规定明天会下雨。", "explanation": "这里应该用〈说〉。规定是要求人照做的，不能用来陈述天气情况，描述天气预测要用说，如：天气预报说明天会下雨。"}, {"text": "他规定了电脑。", "explanation": "这里应该用〈修理〉。规定针对的是要求或规则，不能用于物品，对电脑的维修要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规定", "is_correct": true, "explanation": "「比赛规定」表示比赛用规则要求每个人，与句意相合。"}, {"text": "跑", "is_correct": false, "explanation": "配价：「跑」是不及物动词，后面不能接「每个人只能报一个项目」这样的小句。"}, {"text": "担心", "is_correct": false, "explanation": "语义：「担心」表示心里忧虑，比赛不会担心，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指进食，与比赛的规则无关，句中说不通。"}], "explanations": {"规定": "「比赛规定」表示比赛用规则要求每个人，与句意相合。", "跑": "配价：「跑」是不及物动词，后面不能接「每个人只能报一个项目」这样的小句。", "担心": "语义：「担心」表示心里忧虑，比赛不会担心，句意不通。", "吃": "语义：「吃」指进食，与比赛的规则无关，句中说不通。"}, "sentence_index": 6, "correct_answer": "规定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我规定了一个好朋友。", "explanation": "这里应该用〈交〉。规定针对的是要求或制度，不能用来指结交朋友，交朋友要用交。"}, {"text": "他规定了我的错误。", "explanation": "这里应该用〈承认〉。规定针对的是要求或规则，不能用来指认错，认错要用承认。"}, {"text": "我规定天气好。", "explanation": "这里应该用〈希望〉。规定是对别人下要求，表示期盼要用希望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司规定着，员工上班要穿工作服。", "corrected_sentence": "公司规定，员工上班要穿工作服。", "error_description": "错误形式：「规定着」；正确形式：「规定」。「规定」后面直接引出要求的内容，不表示持续的动作，不能加「着」，应去掉「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆把规定，借书要在两周内还。", "corrected_sentence": "图书馆规定，借书要在两周内还。", "error_description": "错误形式：「把规定」；正确形式：「规定」。「把」字句要求「把」后接宾语再接动词，「把规定」中「规定」本身是动词，前面不能加「把」，应去掉「把」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
