INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22038, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放进去。", "primary_collocate": null, "pronunciation": "tiān jiā", "ipa": "tʰjɛn˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "锅里的水太少了，请再添加一些。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他往杯子里添加了两块冰。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他往粥里添加了一小把葱花。", "target_word": "添加", "complexity_tier": "T3", "furigana": "tiān jiā", "sentence_source": "generated"}, {"text": "妈妈往汤里添加了一些青菜。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王把盐添加到菜里了。", "target_word": "添加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆里的土少了，要添加一些。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶往茶里添加了一点蜂蜜。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在咖啡里添加了牛奶。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给机器添加一些水。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在炒饭里添加了一个鸡蛋。", "target_word": "添加", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "添加了", "label": "体标"}, {"form": "添加过", "label": "体标"}, {"form": "添加剂", "label": "复合"}], "register": "通用", "sense_fingerprint": "把东西放进某物里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e54962f-2c27-426e-ada9-9ddfb59d8bac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22038, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "添加", "is_correct": true, "explanation": "正确答案，意思是把东西放进某物里面。"}, {"text": "天价", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）只差声调，天价指极高的价格。"}, {"text": "天骄", "is_correct": false, "explanation": "jiāo 与 jiā 只差韵母末尾的 o，天骄指杰出而受人瞩目的人。"}, {"text": "天街", "is_correct": false, "explanation": "jiē 与 jiā 只差韵母 e 与 a，天街指天上的街道，多见于诗文。"}], "explanations": {"添加": "正确答案，意思是把东西放进某物里面。", "天价": "jià（第四声）与 jiā（第一声）只差声调，天价指极高的价格。", "天骄": "jiāo 与 jiā 只差韵母末尾的 o，天骄指杰出而受人瞩目的人。", "天街": "jiē 与 jiā 只差韵母 e 与 a，天街指天上的街道，多见于诗文。"}, "sentence_index": null, "correct_answer": "添加"}, "level_3": {"options": [{"text": "添加", "is_correct": true, "explanation": "正确：「添加」表示把水加入锅里，与「水太少了，请再……一些」相符。"}, {"text": "减少", "is_correct": false, "explanation": "语义：水已经太少，还说「减少」，与句意相反。"}, {"text": "倒掉", "is_correct": false, "explanation": "语义：「倒掉」是把水倒出去，与「水太少」的语境矛盾。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：「扔」不能用于水，说「扔一些水」不通。"}], "explanations": {"添加": "正确：「添加」表示把水加入锅里，与「水太少了，请再……一些」相符。", "减少": "语义：水已经太少，还说「减少」，与句意相反。", "倒掉": "语义：「倒掉」是把水倒出去，与「水太少」的语境矛盾。", "扔": "搭配：「扔」不能用于水，说「扔一些水」不通。"}, "sentence_index": 0, "correct_answer": "添加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我家的收入添加了很多。", "explanation": "这里应该用〈增加〉。添加是把东西放进某物中，收入的增多要用增加。"}, {"text": "我们要添加公司的规模。", "explanation": "这里应该用〈扩大〉。添加指放进东西，规模的扩展要用扩大。"}, {"text": "他把书添加在桌子上了。", "explanation": "这里应该用〈放〉。添加指把东西放进某物中，把书摆在桌面上要用放，不能用添加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22038, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "添加", "is_correct": true, "explanation": "正确答案，意思是把东西放进某物里面。"}, {"text": "天下", "is_correct": false, "explanation": "xià 与 jiā 声母、声调不同，天下指全世界、全国。"}, {"text": "田家", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）只差声调；田家指农家，是书面词。"}, {"text": "天价", "is_correct": false, "explanation": "jià（第四声）与 jiā（第一声）只差声调，天价指极高的价格。"}], "explanations": {"添加": "正确答案，意思是把东西放进某物里面。", "天下": "xià 与 jiā 声母、声调不同，天下指全世界、全国。", "田家": "tián（第二声）与 tiān（第一声）只差声调；田家指农家，是书面词。", "天价": "jià（第四声）与 jiā（第一声）只差声调，天价指极高的价格。"}, "sentence_index": null, "correct_answer": "添加"}, "level_3": {"options": [{"text": "添加", "is_correct": true, "explanation": "正确：「添加」表示把蜂蜜加进茶里，与「往茶里」相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是液体，不能说「往茶里喝」。"}, {"text": "切", "is_correct": false, "explanation": "搭配：「切」用于块状的东西，蜂蜜不能说「切」。"}, {"text": "发明", "is_correct": false, "explanation": "语义：蜂蜜不是被「发明」出来的，与句意不符。"}], "explanations": {"添加": "正确：「添加」表示把蜂蜜加进茶里，与「往茶里」相符。", "喝": "搭配：「喝」的对象是液体，不能说「往茶里喝」。", "切": "搭配：「切」用于块状的东西，蜂蜜不能说「切」。", "发明": "语义：蜂蜜不是被「发明」出来的，与句意不符。"}, "sentence_index": 6, "correct_answer": "添加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把椅子添加到了门口。", "explanation": "这里应该用〈搬〉。添加指把东西放进某物中，把椅子移动到某处要用搬，不能用添加。"}, {"text": "我们要添加调查的范围。", "explanation": "这里应该用〈扩大〉。添加指把东西放进去，调查范围的扩展要用扩大。"}, {"text": "我们城市的人口添加很快。", "explanation": "这里应该用〈增长〉。添加表示放进东西，人口自然增多要用增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在往粥里添加了着一把葱。", "corrected_sentence": "他正在往粥里添加一把葱。", "error_description": "错误：「添加了着」同时用了「了」和「着」两个动态助词。表示正在进行时只用「正在」即可，应去掉「了着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把牛奶添加咖啡里了。", "corrected_sentence": "我们把牛奶添加到咖啡里了。", "error_description": "错误：「添加」后缺少介词「到」，「添加咖啡里」不通顺。正确应为「添加到咖啡里」，表示把东西加入某处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
