INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书里写的很神圣的话。", "primary_collocate": null, "pronunciation": "jīng wén", "ipa": "tɕiŋ˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "这本书里有很多神圣的经文。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶每晚都读一段经文。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把喜欢的经文写在本子上。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经文里的话让人心里很平静。", "target_word": "经文", "complexity_tier": "T3", "furigana": "jīng wén", "sentence_source": "generated"}, {"text": "小明在教堂里听到了一段经文。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段经文我已经背会了。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人对着经文小声祈祷。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈教我念这本书里的经文。", "target_word": "经文", "complexity_tier": "T3", "furigana": "jīng wén", "sentence_source": "generated"}, {"text": "他每天都抄一页经文。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些经文是用古老的文字写的。", "target_word": "经文", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "經文", "label": "繁体"}], "register": "通用", "sense_fingerprint": "书里写的很神圣的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e54962f-2c27-426e-ada9-9ddfb59d8bac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经文", "is_correct": true, "explanation": "正确。「书里有很多」指书中的文字，「神圣的经文」符合句意。"}, {"text": "圣殿", "is_correct": false, "explanation": "语义：圣殿是建筑，书里不会「有很多」这样的建筑。"}, {"text": "圣水", "is_correct": false, "explanation": "语义：圣水是液体，不能说「书里有很多」。"}, {"text": "圣餐", "is_correct": false, "explanation": "搭配：圣餐是一种仪式，「书里有很多神圣的圣餐」不成立。"}], "explanations": {"经文": "正确。「书里有很多」指书中的文字，「神圣的经文」符合句意。", "圣殿": "语义：圣殿是建筑，书里不会「有很多」这样的建筑。", "圣水": "语义：圣水是液体，不能说「书里有很多」。", "圣餐": "搭配：圣餐是一种仪式，「书里有很多神圣的圣餐」不成立。"}, "sentence_index": 0, "correct_answer": "经文"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部小说的经文很长，我读了三天。", "explanation": "这里应该用〈篇幅〉。经文指宗教经典的文字，小说的长短要说篇幅。"}, {"text": "这篇经文详细报道了昨天的比赛。", "explanation": "这里应该用〈新闻〉。经文是宗教文字，报道比赛的文章应说〈新闻〉。"}, {"text": "这首流行歌的经文很打动人。", "explanation": "这里应该用〈歌词〉。歌曲的词要说〈歌词〉，经文指宗教或古代经典的文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经文", "is_correct": true, "explanation": "正确。老人对着经文小声祈祷，句意成立。"}, {"text": "电视", "is_correct": false, "explanation": "语义：祈祷的对象应是神明，电视不是祈祷的对象。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱与祈祷无关，句中的「对着」没有合理的对象。"}, {"text": "篮球", "is_correct": false, "explanation": "搭配：「对着……祈祷」不与篮球搭配。"}], "explanations": {"经文": "正确。老人对着经文小声祈祷，句意成立。", "电视": "语义：祈祷的对象应是神明，电视不是祈祷的对象。", "冰箱": "语义：冰箱与祈祷无关，句中的「对着」没有合理的对象。", "篮球": "搭配：「对着……祈祷」不与篮球搭配。"}, "sentence_index": 6, "correct_answer": "经文"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首唐诗的经文写得很美。", "explanation": "这里应该用〈诗句〉。经文指宗教经典的文字，诗里的句子要说诗句。"}, {"text": "报纸上的经文说明天会下雨。", "explanation": "这里应该用〈消息〉。经文是宗教经典的文字，报纸上报道的内容要说消息。"}, {"text": "这部电影的经文是英文的，我看不懂。", "explanation": "这里应该用〈字幕〉。经文指宗教经典的文字，电影画面上的文字要说字幕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天给我读一只经文。", "corrected_sentence": "妈妈每天给我读一段经文。", "error_description": "「经文」是文字，量词应用「段」，不能用「只」。应改为「一段经文」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每天都读这些经文们。", "corrected_sentence": "他们每天都读这些经文。", "error_description": "错误：「们」只用于指人的名词或代词，「经文」是文字，不能加「们」。应改为「这些经文」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
