INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22046, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事物随时间慢慢改变、逐步发展。", "primary_collocate": null, "pronunciation": "yǎn huà", "ipa": "jɛn˨˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "语言会随着时间慢慢演化。", "target_word": "演化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座小村子慢慢演化成了一座大城市。", "target_word": "演化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物在几百万年里不断演化。", "target_word": "演化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的样子一直在演化着。", "target_word": "演化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼演化成能走路的动物，用了很长时间。", "target_word": "演化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机从最早的样子演化到现在，变化很大。", "target_word": "演化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "达尔文研究了生物是怎么演化的。", "target_word": "演化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种风俗是从古代的仪式演化来的。", "target_word": "演化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一场小误会慢慢演化成了大矛盾。", "target_word": "演化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汉字的形状经过了很多次演化。", "target_word": "演化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演化着", "label": "体标"}, {"form": "演化了", "label": "体标"}, {"form": "演化过", "label": "体标"}, {"form": "演化成", "label": "结果补语"}], "register": "书面", "sense_fingerprint": "事物慢慢改变发展的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c928e1f6-5741-4790-be78-40c893415c14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22046, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "演化", "is_correct": true, "explanation": "正确答案。yǎn huà，意思是事物慢慢改变发展。"}, {"text": "眼花", "is_correct": false, "explanation": "huā（第一声）与 huà（第四声）声调不同，意思是视线模糊。"}, {"text": "烟花", "is_correct": false, "explanation": "yān 与 yǎn、huā 与 huà 声调都不同，意思是烟火。"}, {"text": "掩护", "is_correct": false, "explanation": "hù 与 huà 的韵母不同（少了 a 音），意思是遮挡保护。"}], "explanations": {"演化": "正确答案。yǎn huà，意思是事物慢慢改变发展。", "眼花": "huā（第一声）与 huà（第四声）声调不同，意思是视线模糊。", "烟花": "yān 与 yǎn、huā 与 huà 声调都不同，意思是烟火。", "掩护": "hù 与 huà 的韵母不同（少了 a 音），意思是遮挡保护。"}, "sentence_index": null, "correct_answer": "演化"}, "level_3": {"options": [{"text": "演化", "is_correct": true, "explanation": "正确：“慢慢演化”说事物随时间逐渐改变，与“随着时间慢慢”相符。"}, {"text": "演出", "is_correct": false, "explanation": "语义：“演出”指表演给观众看，与语言随时间的变化无关。"}, {"text": "演讲", "is_correct": false, "explanation": "搭配：“演讲”指人站在台上讲话，不用来描写语言的变化。"}, {"text": "演练", "is_correct": false, "explanation": "语义：“演练”指按计划预先练习，与语言随时间的变化不符。"}], "explanations": {"演化": "正确：“慢慢演化”说事物随时间逐渐改变，与“随着时间慢慢”相符。", "演出": "语义：“演出”指表演给观众看，与语言随时间的变化无关。", "演讲": "搭配：“演讲”指人站在台上讲话，不用来描写语言的变化。", "演练": "语义：“演练”指按计划预先练习，与语言随时间的变化不符。"}, "sentence_index": 0, "correct_answer": "演化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的体重一直在演化。", "explanation": "这里应该用〈变化〉。演化指事物长期逐步发展，体重的短期增减要用“变化”。"}, {"text": "他在台上演化了一段舞蹈。", "explanation": "这里是“表演”的意思，但“演化”不能表示舞台上的表演。"}, {"text": "他把这封信演化成了一张贺卡。", "explanation": "“演化”指事物自发、逐渐地发展，人为的改写或加工不用“演化”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22046, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "演化", "is_correct": true, "explanation": "正确答案。yǎn huà，意思是事物慢慢改变发展。"}, {"text": "喊话", "is_correct": false, "explanation": "hǎn（第三声）与 yǎn 声母不同，意思是大声对人说。"}, {"text": "简化", "is_correct": false, "explanation": "jiǎn 比 yǎn 多了声母 j，意思是使简单。"}, {"text": "显化", "is_correct": false, "explanation": "xiǎn 与 yǎn 声母不同，意思是显现出来。"}], "explanations": {"演化": "正确答案。yǎn huà，意思是事物慢慢改变发展。", "喊话": "hǎn（第三声）与 yǎn 声母不同，意思是大声对人说。", "简化": "jiǎn 比 yǎn 多了声母 j，意思是使简单。", "显化": "xiǎn 与 yǎn 声母不同，意思是显现出来。"}, "sentence_index": null, "correct_answer": "演化"}, "level_3": {"options": [{"text": "演化", "is_correct": true, "explanation": "正确：“是怎么演化的”指生物长期逐步发展，与“达尔文研究”相符。"}, {"text": "表演", "is_correct": false, "explanation": "搭配：“表演”用于在台上做动作，不用来描写生物的发展过程。"}, {"text": "演算", "is_correct": false, "explanation": "语义：“演算”指计算，与研究生物的发展过程不符。"}, {"text": "演习", "is_correct": false, "explanation": "语义：“演习”指模拟操练，与“研究生物”无关。"}], "explanations": {"演化": "正确：“是怎么演化的”指生物长期逐步发展，与“达尔文研究”相符。", "表演": "搭配：“表演”用于在台上做动作，不用来描写生物的发展过程。", "演算": "语义：“演算”指计算，与研究生物的发展过程不符。", "演习": "语义：“演习”指模拟操练，与“研究生物”无关。"}, "sentence_index": 6, "correct_answer": "演化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一夜之间演化成了一个大人。", "explanation": "这里用法不对。“演化”强调逐渐发展，不能用于一夜之间突然发生的变化。"}, {"text": "他在黑板上演化了这道数学题。", "explanation": "这里是推算、计算的意思，但“演化”不能表示计算。"}, {"text": "这个学生经过一个学期，演化得很好。", "explanation": "这里应该用〈进步〉。演化用于事物长期逐步发展，个人的学习进步要说“进步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个词在古代的意思慢慢了演化了。", "corrected_sentence": "这个词在古代的意思慢慢演化了。", "error_description": "“了”位置错误且重复：“慢慢了演化了”中，“了”不能放在动词前，也不能与后面的“了”重复；正确形式是“慢慢演化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种方言一直在演化了着。", "corrected_sentence": "这种方言一直在演化着。", "error_description": "错误形式“演化了着”，正确形式“演化着”。“了”和“着”不能同时用在同一个动词上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
