INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22050, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "修士是专心学习宗教道理的男人。", "primary_collocate": null, "pronunciation": "xiū shì", "ipa": "ɕjoʊ˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "那位修士每天都专心读经。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的修道院里住着几位修士。", "target_word": "修士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想做一名修士，一辈子学习宗教。", "target_word": "修士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修士不结婚，生活很简单。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位修士穿着一件灰色的长袍。", "target_word": "修士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇的人都很尊敬这位修士。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修士给孩子们讲了一个故事。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老修士每天早晨都在花园里祈祷。", "target_word": "修士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天有一位修士来我们学校。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修士们安静地坐在教堂里。", "target_word": "修士", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "修士们", "label": "复数"}], "register": "通用", "sense_fingerprint": "专心学习宗教道理的男人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e54962f-2c27-426e-ada9-9ddfb59d8bac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修士", "is_correct": true, "explanation": "正确。「修士」指专心研习宗教的男人，与句中「专心读经」一致。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不识字，无法专心读经。"}, {"text": "醉汉", "is_correct": false, "explanation": "语义：醉汉的状态与「专心读经」相矛盾。"}, {"text": "文盲", "is_correct": false, "explanation": "语义：文盲不识字，无法读经。"}], "explanations": {"修士": "正确。「修士」指专心研习宗教的男人，与句中「专心读经」一致。", "婴儿": "语义：婴儿不识字，无法专心读经。", "醉汉": "语义：醉汉的状态与「专心读经」相矛盾。", "文盲": "语义：文盲不识字，无法读经。"}, "sentence_index": 0, "correct_answer": "修士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她小时候就立誓，要做一名修士。", "explanation": "这里应该用〈修女〉。修士指男性修道者，女性修道者称〈修女〉，〈修士〉不能指女性。"}, {"text": "这位修士的妻子每天都在厨房里做饭。", "explanation": "这里应该用〈牧师〉。修士不结婚，没有妻子；已婚的基督教教职人员称〈牧师〉。"}, {"text": "这位修士在学校教数学，每天给学生批改作业。", "explanation": "这里应该用〈老师〉。修士是专心学习宗教道理的男人，不是学校里教数学的人；在学校教书的人称〈老师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修士", "is_correct": true, "explanation": "正确。「修士」是人，能够给孩子们讲故事，句意成立。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物品，不会给孩子们讲故事。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教具，本身不会给孩子们讲故事。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不能主动讲故事。"}], "explanations": {"修士": "正确。「修士」是人，能够给孩子们讲故事，句意成立。", "窗户": "语义：窗户是物品，不会给孩子们讲故事。", "黑板": "语义：黑板是教具，本身不会给孩子们讲故事。", "书包": "语义：书包是装东西的袋子，不能主动讲故事。"}, "sentence_index": 6, "correct_answer": "修士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在医院当修士，负责给病人量体温。", "explanation": "这里应该用〈护士〉。修士指立誓献身宗教的男人，不是医院的职务；给病人量体温的人称〈护士〉。"}, {"text": "他是我们足球队的修士，每周都上场比赛。", "explanation": "这里应该用〈队员〉。修士不是球队的成员称呼；每周上场比赛的人称〈队员〉。"}, {"text": "他在银行当修士，负责给客户办理存款。", "explanation": "这里应该用〈柜员〉。修士不是银行的职务；给客户办理存款的人称〈柜员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两位修士们每天都一起祈祷。", "corrected_sentence": "这两位修士每天都一起祈祷。", "error_description": "「这两位」已经表示数量，「修士」后面不能再加「们」。应改为「这两位修士」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只修士每天清晨都在花园里祈祷。", "corrected_sentence": "这位修士每天清晨都在花园里祈祷。", "error_description": "「修士」指人，量词应用「位」，不能用「只」。应改为「这位修士」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d4b6c02-f764-40fe-9847-fc4e3234ea52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
