INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22052, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物表现出来的样子或特点。", "primary_collocate": null, "pronunciation": "biǎo zhēng", "ipa": "piɑʊ˨˩ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "发烧是身体生病的一种表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子爱哭常常是缺少安全感的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脸红不一定是害羞的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这些症状是感冒的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种表征很明显，大家都能看出来。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是迟到，这是不重视工作的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济变好的表征之一，是找工作更容易了。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮肤发黄可能是肝出问题的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她睡不着觉，这是压力太大的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师认为，爱问问题是学生认真的表征。", "target_word": "表征", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "心理表征", "label": "复合"}, {"form": "表徵", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "事物外在表现出的样子或特点，常指某种内在情况的外在标志", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c5811c7-5286-4a58-bed4-0f21f210b18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表征", "is_correct": true, "explanation": "表征：指事物表现出的样子或特点，此处指发烧是身体生病的外在标志。"}, {"text": "药品", "is_correct": false, "explanation": "语义：药品是用来治病的物质，不是身体生病的外在标志。"}, {"text": "节奏", "is_correct": false, "explanation": "搭配：“节奏”指有规律的起伏变化，不能说成身体生病的一种节奏。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”为口语，与这段书面语的语域不合，且不指外在标志。"}], "explanations": {"表征": "表征：指事物表现出的样子或特点，此处指发烧是身体生病的外在标志。", "药品": "语义：药品是用来治病的物质，不是身体生病的外在标志。", "节奏": "搭配：“节奏”指有规律的起伏变化，不能说成身体生病的一种节奏。", "家伙": "语域：“家伙”为口语，与这段书面语的语域不合，且不指外在标志。"}, "sentence_index": 0, "correct_answer": "表征"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款手机的表征卖出了一百万台。", "explanation": "这里应该用〈销量〉。表征指事物表现出来的样子或特点，不指商品的销售数量；商品卖出了多少要用销量。"}, {"text": "这部电影的表征很高。", "explanation": "这里应该用〈票房〉。表征不指电影的票房收入；票房的高低要用票房。"}, {"text": "这项投资的表征很高。", "explanation": "这里应该用〈收益〉。表征不指经济回报；投资的回报要用收益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表征", "is_correct": true, "explanation": "表征：指外在显露、可据以判断内在情况的标志，此处指经济变好的外在迹象。"}, {"text": "主人", "is_correct": false, "explanation": "语义：“主人”指拥有所有权的人，经济变好不能说是其中的“主人之一”。"}, {"text": "零件", "is_correct": false, "explanation": "搭配：“零件”是机器的组成部分，不能指经济变好的迹象。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”指性情，不能与“经济变好”构成表示迹象的成分。"}], "explanations": {"表征": "表征：指外在显露、可据以判断内在情况的标志，此处指经济变好的外在迹象。", "主人": "语义：“主人”指拥有所有权的人，经济变好不能说是其中的“主人之一”。", "零件": "搭配：“零件”是机器的组成部分，不能指经济变好的迹象。", "脾气": "搭配：“脾气”指性情，不能与“经济变好”构成表示迹象的成分。"}, "sentence_index": 6, "correct_answer": "表征"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次研究的表征很大。", "explanation": "这里应该用〈成果〉。表征指内在情况显露出的外在标志，不指研究取得的成果；研究取得的成果要用成果。"}, {"text": "这家店的表征很高。", "explanation": "这里应该用〈利润〉。表征不指经营中的盈利；店铺的盈利要用利润。"}, {"text": "这个班学生的表征很高。", "explanation": "这里应该用〈水平〉。表征不指学习能力的高低；学生的学习水平要用水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种反复咳嗽是肺部发炎一种表征。", "corrected_sentence": "这种反复咳嗽是肺部发炎的一种表征。", "error_description": "定语“肺部发炎”与“一种表征”之间应加“的”，应说「肺部发炎的一种表征」，漏掉“的”是语法错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总在会议上走神，是注意力不集中的一只表征。", "corrected_sentence": "他总在会议上走神，是注意力不集中的一种表征。", "error_description": "“表征”前的量词用错。“只”多用于动物或个体物件，不搭配这类抽象事物；应说“一种表征”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef8669af-1187-499f-b907-8925a3beaf1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22054, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：“模糊”与“明确”相对，指不清楚、不确定，符合“说明写得不够明确”的对立。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”指质地不硬，与“明确”没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "“温暖”指温度或感情，与“明确”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”指人多、声响大，与“明确”没有反义关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：“模糊”与“明确”相对，指不清楚、不确定，符合“说明写得不够明确”的对立。", "柔软": "“柔软”指质地不硬，与“明确”没有反义关系。", "温暖": "“温暖”指温度或感情，与“明确”没有反义关系。", "热闹": "“热闹”指人多、声响大，与“明确”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22054, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确：“模糊”与“明确”相对，指不清楚、不确定，符合“小王明确表示”的对立。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”指内容多、难理解，与“明确”没有反义关系。"}, {"text": "凉爽", "is_correct": false, "explanation": "“凉爽”指温度适宜、凉快，与“明确”没有反义关系。"}, {"text": "倔强", "is_correct": false, "explanation": "“倔强”指性格固执、不肯变通，与“明确”没有反义关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确：“模糊”与“明确”相对，指不清楚、不确定，符合“小王明确表示”的对立。", "复杂": "“复杂”指内容多、难理解，与“明确”没有反义关系。", "凉爽": "“凉爽”指温度适宜、凉快，与“明确”没有反义关系。", "倔强": "“倔强”指性格固执、不肯变通，与“明确”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22054, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是清清楚楚，很容易明白。", "primary_collocate": null, "pronunciation": "míng què", "ipa": "miŋ³⁵ tɕʰɥɛ⁵¹", "syllable_count": 2, "sentences": [{"text": "老师的要求很明确。", "target_word": "明确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你明确地告诉我时间。", "target_word": "明确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的态度非常明确，不同意。", "target_word": "明确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份说明写得不够明确。", "target_word": "明确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给了我一个明确的答案。", "target_word": "明确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的方向很明确。", "target_word": "明确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理明确说了，明天必须交报告。", "target_word": "明确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这件事的看法不太明确。", "target_word": "明确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同上写得很明确，不能晚交。", "target_word": "明确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王明确表示，他不去旅行。", "target_word": "明确", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "明确地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "内容或态度清楚、不含糊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7cea0ef-f5d6-475e-98b1-4539dcad4711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22054, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明确", "is_correct": true, "explanation": "正确：“明确”表示清楚、不含糊，符合“老师的要求很……”的语境。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”描述味道，不用于形容要求。"}, {"text": "红", "is_correct": false, "explanation": "搭配：“红”描述颜色，不能修饰“要求”，句子不成立。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来形容“要求”。"}], "explanations": {"明确": "正确：“明确”表示清楚、不含糊，符合“老师的要求很……”的语境。", "甜": "语义：“甜”描述味道，不用于形容要求。", "红": "搭配：“红”描述颜色，不能修饰“要求”，句子不成立。", "漂亮": "体貌：“漂亮”形容外貌，不能用来形容“要求”。"}, "sentence_index": 0, "correct_answer": "明确"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盒饭的味道很明确，有点咸。", "explanation": "这里应该用〈咸〉。明确指内容或态度清楚，不能用来形容味道，说味道咸要用〈咸〉。"}, {"text": "他脸上的伤痕很明确。", "explanation": "这里应该用〈明显〉。明确不用于描述痕迹的醒目程度，伤痕看得见要用〈明显〉。"}, {"text": "这条河的水很明确，很清澈。", "explanation": "这里应该用〈清澈〉。明确指内容或态度清楚，不能用来形容水质，应说〈清澈〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明确", "is_correct": true, "explanation": "正确：“明确”作状语，表示清楚地表态，符合“经理……说了”的语境。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列有序，不能修饰“说”，“整齐说了”不成立。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，与“明天必须交报告”的确定要求不合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰程度，不能直接修饰“说”，“非常说了”不通。"}], "explanations": {"明确": "正确：“明确”作状语，表示清楚地表态，符合“经理……说了”的语境。", "整齐": "搭配：“整齐”形容排列有序，不能修饰“说”，“整齐说了”不成立。", "偶尔": "语义：“偶尔”表示有时，与“明天必须交报告”的确定要求不合。", "非常": "搭配：“非常”修饰程度，不能直接修饰“说”，“非常说了”不通。"}, "sentence_index": 6, "correct_answer": "明确"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布很明确，一点灰尘也没有。", "explanation": "这里应该用〈干净〉。明确指内容或态度清楚，不能用来形容布的洁净。"}, {"text": "他的脸色很明确，看起来很健康。", "explanation": "这里应该用〈红润〉。明确指内容或态度清楚，不能用来形容脸色。"}, {"text": "他明确地眨了眨眼。", "explanation": "这里应该用〈轻轻〉。明确的副词用法只修饰说清楚的内容或态度，不能修饰眨眼这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他解释得很明确地。", "corrected_sentence": "他解释得很明确。", "error_description": "错误：“得”字后的补语“很明确”句末不能再加“地”，“地”只用于动词前作状语。去掉句末“地”即为“他解释得很明确。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明确的告诉我，他不来了。", "corrected_sentence": "他明确地告诉我，他不来了。", "error_description": "“明确”在动词“告诉”前作状语，要用“地”，不能用“的”，应说“明确地告诉我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22056, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "凝固", "is_correct": true, "explanation": "凝固与“化”（融化）意思相反，指液体变成固体，词典中互为反义词。"}, {"text": "飞翔", "is_correct": false, "explanation": "飞翔指在空中飞行，与“化”没有反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "生长指植物或生物长大，与“化”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步指慢慢走路，与“化”没有反义关系。"}], "correct_answer": "凝固", "explanations": {"凝固": "凝固与“化”（融化）意思相反，指液体变成固体，词典中互为反义词。", "飞翔": "飞翔指在空中飞行，与“化”没有反义关系。", "生长": "生长指植物或生物长大，与“化”没有反义关系。", "散步": "散步指慢慢走路，与“化”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22056, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "凝固", "is_correct": true, "explanation": "凝固与“化”（融化）意思相反，指液体变成固体，词典中互为反义词。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌指发声演唱，与“化”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字指用笔写出文字，与“化”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步指快速跑动，与“化”没有反义关系。"}], "correct_answer": "凝固", "explanations": {"凝固": "凝固与“化”（融化）意思相反，指液体变成固体，词典中互为反义词。", "唱歌": "唱歌指发声演唱，与“化”没有反义关系。", "写字": "写字指用笔写出文字，与“化”没有反义关系。", "跑步": "跑步指快速跑动，与“化”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22056, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "冰雪等固体受热变成水或液体，即融化。", "primary_collocate": null, "pronunciation": "huà", "ipa": "xwa˥˩", "syllable_count": 1, "sentences": [{"text": "太阳出来了，雪化了。", "target_word": "化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰放在太阳下面，很快就化成水了。", "target_word": "化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "糖放进热水里，一会儿就化了。", "target_word": "化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，河里的冰都化了。", "target_word": "化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "巧克力在手里化了，我赶快吃掉。", "target_word": "化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰化成水以后，水会流到地上。", "target_word": "化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪人化着化着，只剩下一顶帽子。", "target_word": "化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰激凌放太久，已经化了，不好吃了。", "target_word": "化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的雪化了，河水一下子多了起来。", "target_word": "化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把冰块放在杯子里，它慢慢化成了水。", "target_word": "化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "化了", "label": "体标"}, {"form": "化过", "label": "体标"}, {"form": "化成", "label": "复合"}, {"form": "融化", "label": "复合"}], "register": "中性", "sense_fingerprint": "化:冰雪等固体变成水或液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96644a94-d766-4004-bc27-ec755acabdc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22056, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "化", "is_correct": true, "explanation": "正确答案：化（huà），意思是冰雪等固体变成水，即融化。"}, {"text": "挂", "is_correct": false, "explanation": "guà（第四声）与 huà 声母不同（g/h），意思是挂起来。"}, {"text": "跨", "is_correct": false, "explanation": "kuà（第四声）与 huà 声母不同（k/h），意思是跨过。"}, {"text": "花", "is_correct": false, "explanation": "huā（第一声）与 huà 声调不同，意思是花朵。"}, {"text": "滑", "is_correct": false, "explanation": "huá（第二声）与 huà 声调不同，意思是滑动或光滑。"}], "explanations": {"化": "正确答案：化（huà），意思是冰雪等固体变成水，即融化。", "挂": "guà（第四声）与 huà 声母不同（g/h），意思是挂起来。", "跨": "kuà（第四声）与 huà 声母不同（k/h），意思是跨过。", "花": "huā（第一声）与 huà 声调不同，意思是花朵。", "滑": "huá（第二声）与 huà 声调不同，意思是滑动或光滑。"}, "sentence_index": null, "correct_answer": "化"}, "level_3": {"options": [{"text": "化", "is_correct": true, "explanation": "正确：化在此指雪由固体变成水，与“太阳出来了”的语境一致。"}, {"text": "冻", "is_correct": false, "explanation": "语义：冻指变凉变硬，与太阳出来、天气变暖的语境相反。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：烧指燃烧，雪不能被烧。"}, {"text": "碎", "is_correct": false, "explanation": "语义：碎指破裂成小块，不是雪因阳光而改变状态。"}], "explanations": {"化": "正确：化在此指雪由固体变成水，与“太阳出来了”的语境一致。", "冻": "语义：冻指变凉变硬，与太阳出来、天气变暖的语境相反。", "烧": "搭配：烧指燃烧，雪不能被烧。", "碎": "语义：碎指破裂成小块，不是雪因阳光而改变状态。"}, "sentence_index": 0, "correct_answer": "化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听到这个消息，脸色一下子化了。", "explanation": "这里应该用〈变〉。化指冰、糖等固体受热变成液体，脸色的改变要用“变”，不能用“化”。"}, {"text": "这支铅笔用了很久，已经化了，写不出字来。", "explanation": "这里不是固体遇热溶化，铅笔用久了是磨短，应说“磨短”，不能用“化”。"}, {"text": "这份作业他一个晚上就化完了。", "explanation": "“化”只用于固体变成液体，不能用来说完成作业，这里的用法错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22056, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "化", "is_correct": true, "explanation": "正确答案：化（huà），意思是固体变成液体。"}, {"text": "华", "is_correct": false, "explanation": "huá（第二声）与 huà 声调不同，意思是中华、华丽。"}, {"text": "划", "is_correct": false, "explanation": "huá（第二声）与 huà 声调不同，意思是划船。"}, {"text": "换", "is_correct": false, "explanation": "huàn 与 huà 韵母不同（多一个 n），意思是交换。"}, {"text": "晃", "is_correct": false, "explanation": "huàng 与 huà 韵母不同（多 ng），意思是摇晃。"}], "explanations": {"化": "正确答案：化（huà），意思是固体变成液体。", "华": "huá（第二声）与 huà 声调不同，意思是中华、华丽。", "划": "huá（第二声）与 huà 声调不同，意思是划船。", "换": "huàn 与 huà 韵母不同（多一个 n），意思是交换。", "晃": "huàng 与 huà 韵母不同（多 ng），意思是摇晃。"}, "sentence_index": null, "correct_answer": "化"}, "level_3": {"options": [{"text": "化", "is_correct": true, "explanation": "正确：化在此表示雪人慢慢消融，与“只剩下一顶帽子”的语境一致。"}, {"text": "写", "is_correct": false, "explanation": "语义：写指写字，雪人不会写字，与“只剩下一顶帽子”的语境不符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：吃需要进食的主体，雪人不能吃东西。"}, {"text": "长", "is_correct": false, "explanation": "语义：长指变大、生长，与雪人渐渐消失的语境相反。"}], "explanations": {"化": "正确：化在此表示雪人慢慢消融，与“只剩下一顶帽子”的语境一致。", "写": "语义：写指写字，雪人不会写字，与“只剩下一顶帽子”的语境不符。", "吃": "搭配：吃需要进食的主体，雪人不能吃东西。", "长": "语义：长指变大、生长，与雪人渐渐消失的语境相反。"}, "sentence_index": 6, "correct_answer": "化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湖水在寒冷的夜里慢慢化成了冰。", "explanation": "“化”表示固体变成液体，这里是液体变成固体，方向相反，应当说“结成冰”。"}, {"text": "这杯水太烫，我把它化一化再喝。", "explanation": "水本来就是液体，不能再用“化”表示变成液体。"}, {"text": "我把桌子化了，然后放进了水里。", "explanation": "这里误把“化”当作使桌子变形或消失的意思。“化”只指冰雪、糖等固体遇热溶化，木制的桌子不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪在阳光下慢慢化到了水。", "corrected_sentence": "雪在阳光下慢慢化成了水。", "error_description": "错误：化到了水。正确：化成了水。表示变化的结果要用补语“成”，“到”表示到达某处，不能表示变成什么。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把糖放进热水里，它很快就开化了。", "corrected_sentence": "我把糖放进热水里，它很快就化开了。", "error_description": "错误：开化了。正确：化开了。“化开”是动词“化”加结果补语“开”，表示溶化散开；“开化”是另一个词，顺序颠倒后意思和用法都不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
