INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22060, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人一起做一件事，互相帮助。", "primary_collocate": null, "pronunciation": "pèi hé", "ipa": "pʰeɪ̯˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我们要好好配合。", "target_word": "配合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我和同事配合完成了这个项目。", "target_word": "配合", "complexity_tier": "T3", "furigana": "wǒ hé tóngshì pèihé wánchéng le zhège xiàngmù.", "sentence_source": "generated"}, {"text": "他和我配合得很好。", "target_word": "配合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天他们配合得很好，赢了比赛。", "target_word": "配合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人配合着把箱子抬上了楼。", "target_word": "配合", "complexity_tier": "T3", "furigana": "liǎng gè rén pèihé zhe bǎ xiāngzi tái shàng le lóu.", "sentence_source": "generated"}, {"text": "大家配合了半天，终于做完了。", "target_word": "配合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跳舞的时候，两个人要互相配合。", "target_word": "配合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个配合过很多次，所以很有默契。", "target_word": "配合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司互相配合，共同开发了新产品。", "target_word": "配合", "complexity_tier": "T3", "furigana": "liǎng jiā gōngsī hùxiāng pèihé, gòngtóng kāifā le xīn chǎnpǐn.", "sentence_source": "generated"}, {"text": "这件事太大，我们必须配合着做。", "target_word": "配合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "配合了", "label": "体标"}, {"form": "配合过", "label": "体标"}, {"form": "配合着", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：几个人为了同一件事互相协调、互相帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a37e-859d-480a-acef-93c3977707a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配合", "is_correct": true, "explanation": "“好好配合”指双方协调、互相帮助地做事，符合“我们要”的语境。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”是没有按时到达的失误，不能“好好”去做，与“要好好”的要求相悖。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”是不希望发生的结果，不能用“好好”来修饰。"}, {"text": "生病", "is_correct": false, "explanation": "搭配：“生病”是身体状态，不能说“好好生病”，与“要好好”的语境不符。"}], "explanations": {"配合": "“好好配合”指双方协调、互相帮助地做事，符合“我们要”的语境。", "迟到": "语义：“迟到”是没有按时到达的失误，不能“好好”去做，与“要好好”的要求相悖。", "丢失": "语义：“丢失”是不希望发生的结果，不能用“好好”来修饰。", "生病": "搭配：“生病”是身体状态，不能说“好好生病”，与“要好好”的语境不符。"}, "sentence_index": 0, "correct_answer": "配合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人配合完成了这个项目。", "explanation": "这里应该用〈独自〉。“配合”指两人或多人相互协作，一个人单独完成时不能用“配合”。"}, {"text": "两个朋友配合着看了一场电影。", "explanation": "这里应该用〈一起〉。“配合”强调分工协作完成一件事，看电影没有分工，只能说“一起看”。"}, {"text": "我配合了他的好意，收下了礼物。", "explanation": "这里应该用〈领情〉。“配合”指双方协作做事，不用于接受别人的好意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配合", "is_correct": true, "explanation": "“互相配合”指双方协调、彼此协作，符合跳舞需要双人协作的语境。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是个人的动作，不能说“互相睡觉”，与双人跳舞的语境不符。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”是一方动身前往，双方不能“互相出发”，与跳舞的语境不符。"}, {"text": "站立", "is_correct": false, "explanation": "语义：“站立”是单独的身体姿态，不能彼此进行，与双人跳舞的语境相悖。"}], "explanations": {"配合": "“互相配合”指双方协调、彼此协作，符合跳舞需要双人协作的语境。", "睡觉": "语义：“睡觉”是个人的动作，不能说“互相睡觉”，与双人跳舞的语境不符。", "出发": "语义：“出发”是一方动身前往，双方不能“互相出发”，与跳舞的语境不符。", "站立": "语义：“站立”是单独的身体姿态，不能彼此进行，与双人跳舞的语境相悖。"}, "sentence_index": 6, "correct_answer": "配合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "领导配合了我的电话。", "explanation": "这里应该用〈接〉。“配合”表示双方协作做事，不用于接听电话。"}, {"text": "老师配合黑板写字。", "explanation": "这里应该用〈在〉。“配合”指人与人之间协作，不能用于人与物；“在黑板上写字”应用“在”。"}, {"text": "他把书配合了一下，放在桌上。", "explanation": "这里应该用〈摆放〉。“配合”指人与人协作，不表示整理或摆放物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和朋友互相配合的很默契，很快就把房间打扫干净了。", "corrected_sentence": "我和朋友互相配合得很默契，很快就把房间打扫干净了。", "error_description": "错误在于补语标记：表示程度的补语应由“得”引出，写成“的”是误用。正确为“互相配合得很默契”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位同学配合的很好，把桌子搬进了教室。", "corrected_sentence": "两位同学配合得很好，把桌子搬进了教室。", "error_description": "错误在于补语标记：“配合”后表示程度的补语应由“得”引出，写成“的”是误用。正确为“配合得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
