INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22064, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是慢慢变化，比如天慢慢变黑了。", "primary_collocate": null, "pronunciation": "zhú jiàn", "ipa": "ʈʂu˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "天气逐渐变冷了。", "target_word": "逐渐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空逐渐黑了下来。", "target_word": "逐渐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了老师的话，他逐渐明白了问题在哪里。", "target_word": "逐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来中国以后，我逐渐习惯了这里的生活。", "target_word": "逐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，树叶逐渐变绿。", "target_word": "逐渐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨声逐渐小了，我们走出了咖啡店。", "target_word": "逐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的汉语水平逐渐提高。", "target_word": "逐渐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市里的人逐渐多起来了。", "target_word": "逐渐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子逐渐长大，不再需要我们照顾。", "target_word": "逐渐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐声逐渐变小，最后听不见了。", "target_word": "逐渐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逐漸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表示程度或数量一点一点地变化；副词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd392b4f9-49cb-42d5-83fd-145c61c00b83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逐渐", "is_correct": true, "explanation": "正确：「逐渐」表示一点一点地变化，「天气逐渐变冷了」自然。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：「亲自」要求施事是人，天气不会「亲自」变冷。"}, {"text": "故意", "is_correct": false, "explanation": "语义：「故意」表示有意识地去做，天气变化不是有意的。"}, {"text": "大力", "is_correct": false, "explanation": "搭配：「大力」修饰有意的动作，不说「天气大力变冷」。"}], "explanations": {"逐渐": "正确：「逐渐」表示一点一点地变化，「天气逐渐变冷了」自然。", "亲自": "语义：「亲自」要求施事是人，天气不会「亲自」变冷。", "故意": "语义：「故意」表示有意识地去做，天气变化不是有意的。", "大力": "搭配：「大力」修饰有意的动作，不说「天气大力变冷」。"}, "sentence_index": 0, "correct_answer": "逐渐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他逐渐大声喊了一句。", "explanation": "这里应该用〈突然〉。逐渐指慢慢变化，喊一句话是瞬间完成的动作，要用〈突然〉。"}, {"text": "他逐渐接了电话。", "explanation": "这里应该用〈立刻〉。逐渐指慢慢变化，接电话是一次完成的动作，要用〈立刻〉。"}, {"text": "他逐渐出生在一个冬天。", "explanation": "这里不应该用〈逐渐〉。逐渐指慢慢变化，出生是一下子发生的事，不能说慢慢出生，应删去“逐渐”：他出生在一个冬天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逐渐", "is_correct": true, "explanation": "正确：「逐渐」表示能力或水平慢慢变化，「汉语水平逐渐提高」自然。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：「连忙」描述人急忙行动，「汉语水平」是状态，不能「连忙提高」。"}, {"text": "拼命", "is_correct": false, "explanation": "语义：「拼命」表示竭尽全力的行为，不能用来修饰水平自然地变化。"}, {"text": "乱", "is_correct": false, "explanation": "搭配：「乱」表示没有秩序，不修饰「提高」，「汉语水平乱提高」不通。"}], "explanations": {"逐渐": "正确：「逐渐」表示能力或水平慢慢变化，「汉语水平逐渐提高」自然。", "连忙": "语义：「连忙」描述人急忙行动，「汉语水平」是状态，不能「连忙提高」。", "拼命": "语义：「拼命」表示竭尽全力的行为，不能用来修饰水平自然地变化。", "乱": "搭配：「乱」表示没有秩序，不修饰「提高」，「汉语水平乱提高」不通。"}, "sentence_index": 6, "correct_answer": "逐渐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他逐渐拿到了冠军。", "explanation": "这里应该用〈一举〉。逐渐指慢慢变化，拿到冠军是一次决定性的结果，要用〈一举〉。"}, {"text": "闹钟逐渐响了一声。", "explanation": "这里应该用〈猛然〉。逐渐指慢慢变化，闹钟响一声是瞬间的事，要用〈猛然〉。"}, {"text": "老人逐渐摔了一跤。", "explanation": "这里应该用〈突然〉。逐渐指慢慢变化，摔一跤是瞬间发生的事，要用〈突然〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一下子逐渐好了。", "corrected_sentence": "他一下子就好了。", "error_description": "时间副词错误：“逐渐”表示慢慢变化，与“一下子”矛盾，应删去“逐渐”，“一下子”已表示瞬间完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市的交通立刻逐渐便利了。", "corrected_sentence": "城市的交通立刻便利了。", "error_description": "时间副词错误：“逐渐”表示慢慢变化，与“立刻”矛盾，应删去“逐渐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
