INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给别人东西。", "primary_collocate": null, "pronunciation": "tí gōng", "ipa": "tʰi˧˥ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "学校给学生提供午饭。", "target_word": "提供", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家酒店提供免费早餐。", "target_word": "提供", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司为我们提供了一台电脑。", "target_word": "提供", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你提供一下你的电话号码。", "target_word": "提供", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆提供很多免费的书。", "target_word": "提供", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想给孩子提供更好的学习环境。", "target_word": "提供", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网站提供各种旅游信息。", "target_word": "提供", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院给病人提供过很多帮助。", "target_word": "提供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师提供的这些资料对我很有用。", "target_word": "提供", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店为客人提供中文菜单和英文菜单。", "target_word": "提供", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "提供了", "label": "体标"}, {"form": "提供过", "label": "体标"}], "register": "中性", "sense_fingerprint": "给别人所需要的东西或帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b2333-0eb6-4215-84dd-38c7b4eb1246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提供", "is_correct": true, "explanation": "正确答案。“提供午饭”指学校供应或给予学生午饭。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象不是午饭，“欣赏午饭”句意不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地，不能与“午饭”搭配。"}, {"text": "研究", "is_correct": false, "explanation": "语义：学校不会“研究”学生的午饭，句意不通。"}], "explanations": {"提供": "正确答案。“提供午饭”指学校供应或给予学生午饭。", "欣赏": "语义：“欣赏”的对象不是午饭，“欣赏午饭”句意不通。", "打扫": "搭配：“打扫”的对象是场地，不能与“午饭”搭配。", "研究": "语义：学校不会“研究”学生的午饭，句意不通。"}, "sentence_index": 0, "correct_answer": "提供"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提供了一个错误。", "explanation": "这里应该用〈发现〉。“提供”指给别人需要的东西或帮助，发现错误要用“发现”。"}, {"text": "这个方法能提供效率。", "explanation": "这里应该用〈提高〉。效率是要提高的数量，“提供”指给别人需要的东西，不能用于效率。"}, {"text": "他提供了一个好成绩。", "explanation": "这里应该用〈获得〉。“获得”指取得成绩或成果，“提供”指给予别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提供", "is_correct": true, "explanation": "正确答案。“提供各种旅游信息”指网站给出可供查询的信息。"}, {"text": "吞咽", "is_correct": false, "explanation": "语义：网站不能“吞咽”信息，句意不通。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”的对象是衣物，不能与“旅游信息”搭配。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”的对象是植物或头发，不能用于信息。"}], "explanations": {"提供": "正确答案。“提供各种旅游信息”指网站给出可供查询的信息。", "吞咽": "语义：网站不能“吞咽”信息，句意不通。", "缝补": "搭配：“缝补”的对象是衣物，不能与“旅游信息”搭配。", "修剪": "语义：“修剪”的对象是植物或头发，不能用于信息。"}, "sentence_index": 6, "correct_answer": "提供"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂提供了很多垃圾。", "explanation": "这里应该用〈产生〉。“提供”指给别人需要的东西，垃圾是工厂产生出来的，应说“产生”。"}, {"text": "我昨晚提供了一个梦。", "explanation": "这里应该用〈做〉。“做梦”是固定说法，“提供”指给别人需要的东西或帮助，不能用于梦。"}, {"text": "他提供了感谢。", "explanation": "这里应该用〈表示〉。“表示感谢”是表达感谢的动作，不说“提供感谢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院被病人提供免费的检查。", "corrected_sentence": "这家医院为病人提供免费的检查。", "error_description": "介词错误：“提供”的受事是“检查”，“病人”是受益者，应用“为”引出，不能用“被”。“被”字句中主语应是受事，此处应改为“为病人提供”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个网站为游客给提供各种旅游信息。", "corrected_sentence": "这个网站为游客提供各种旅游信息。", "error_description": "介词错误：“为游客”已经引出了受益人，“给”是多余的，不能再与“提供”并列，应去掉“给”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
