INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22074, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "慢慢变化，从一种样子变成另一种样子。", "primary_collocate": null, "pronunciation": "yǎn jìn", "ipa": "jɛn˨˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "手机的样子一直在演进。", "target_word": "演进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类的语言慢慢演进到了今天的样子。", "target_word": "演进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种技术经过多年演进，越来越好用。", "target_word": "演进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物从简单到复杂，一步一步演进。", "target_word": "演进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市的交通方式在不断演进。", "target_word": "演进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车从很慢的机器演进成了现在的样子。", "target_word": "演进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐也会随着时代演进。", "target_word": "演进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的做法已经演进了很多次。", "target_word": "演进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的拍法几十年来不断演进。", "target_word": "演进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的生活方式正在慢慢演进。", "target_word": "演进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演进了", "label": "体标"}, {"form": "演进着", "label": "体标"}, {"form": "演进过", "label": "体标"}], "register": "通用", "sense_fingerprint": "事物慢慢变化发展，变成新样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8b19119-d89a-436b-a0df-53ddddc827e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22074, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "演进", "is_correct": true, "explanation": "演进 yǎn jìn：慢慢变化、变成新的样子，是本题正确答案。"}, {"text": "严禁", "is_correct": false, "explanation": "严禁 yán jìn 与 演进 yǎn jìn 的第一音节声调不同（第二声与第三声），意思是严格禁止。"}, {"text": "眼镜", "is_correct": false, "explanation": "眼镜 yǎnjìng 与 演进 yǎn jìn 的第二音节韵母不同（ing 与 in），意思是眼镜。"}, {"text": "眼睛", "is_correct": false, "explanation": "眼睛 yǎnjing 与 演进 yǎn jìn 的第二音节韵母不同（ing 与 in），且声调不同（轻声），意思是眼睛。"}], "explanations": {"演进": "演进 yǎn jìn：慢慢变化、变成新的样子，是本题正确答案。", "严禁": "严禁 yán jìn 与 演进 yǎn jìn 的第一音节声调不同（第二声与第三声），意思是严格禁止。", "眼镜": "眼镜 yǎnjìng 与 演进 yǎn jìn 的第二音节韵母不同（ing 与 in），意思是眼镜。", "眼睛": "眼睛 yǎnjing 与 演进 yǎn jìn 的第二音节韵母不同（ing 与 in），且声调不同（轻声），意思是眼睛。"}, "sentence_index": null, "correct_answer": "演进"}, "level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”指休息入睡，不能用来描述手机样子的变化。"}, {"text": "演进", "is_correct": true, "explanation": "演进：正确答案，表示事物慢慢变化，与“一直在”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是人或动物吃食物的动作，不能用来描述手机样子的变化。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”是人的行为，不能用来描述手机样子的发展。"}], "explanations": {"睡觉": "语义：“睡觉”指休息入睡，不能用来描述手机样子的变化。", "演进": "演进：正确答案，表示事物慢慢变化，与“一直在”搭配自然。", "吃": "语义：“吃”是人或动物吃食物的动作，不能用来描述手机样子的变化。", "唱歌": "语义：“唱歌”是人的行为，不能用来描述手机样子的发展。"}, "sentence_index": 0, "correct_answer": "演进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一夜之间演进了很多。", "explanation": "这里应该用〈变化〉。“演进”指一步一步慢慢变化，不能用于一夜之间突然发生的改变。"}, {"text": "这杯茶慢慢演进了。", "explanation": "这里应该用〈凉〉。“演进”指事物的形态或制度逐渐发展，一杯茶慢慢变凉是温度下降，要说“凉”。"}, {"text": "这起事故演进了。", "explanation": "这里应该用〈发生〉。“演进”指事物慢慢形成新样子，不用于事故这类突发事件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是人或动物在水中的活动，不能描述音乐随时代的变化。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”是身体的运动，不能用于音乐与时代的关系。"}, {"text": "演进", "is_correct": true, "explanation": "演进：正确答案，表示音乐随时代慢慢变化，与“随着时代”搭配。"}, {"text": "缝", "is_correct": false, "explanation": "配价：“缝”需要缝制的对象作宾语，“音乐也会随着时代缝”缺少宾语，不成立。"}], "explanations": {"游泳": "语义：“游泳”是人或动物在水中的活动，不能描述音乐随时代的变化。", "跑步": "语义：“跑步”是身体的运动，不能用于音乐与时代的关系。", "演进": "演进：正确答案，表示音乐随时代慢慢变化，与“随着时代”搭配。", "缝": "配价：“缝”需要缝制的对象作宾语，“音乐也会随着时代缝”缺少宾语，不成立。"}, "sentence_index": 6, "correct_answer": "演进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的人口演进了很多。", "explanation": "这里应该用〈增长〉。“演进”强调事物形态的渐变，人口数量增加要用“增长”。"}, {"text": "他的成绩演进了很多。", "explanation": "这里应该用〈进步〉。“演进”不用于个人的成绩或能力，成绩提高要用“进步”。"}, {"text": "孩子慢慢演进了。", "explanation": "这里应该用〈成长〉。“演进”指事物形态或系统的渐变，一般不用于人的成长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个行业的规则被演进了。", "corrected_sentence": "这个行业的规则演进了。", "error_description": "错误：“被演进了”；正确：“演进了”。“演进”是不及物动词，不能用“被”构成被动句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套软件的界面演进的很平稳。", "corrected_sentence": "这套软件的界面演进得很平稳。", "error_description": "错误：“的”；正确：“得”。“演进”后面的程度补语要用“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
