INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22078, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "表示乐谱中每小节的拍数和强弱规律的符号。", "primary_collocate": null, "pronunciation": "pāi hào", "ipa": "pʰai̯˥ xau̯˥˩", "syllable_count": 2, "sentences": [{"text": "每首乐曲的开头，都会标出拍号。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首进行曲用的是二四拍号。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们正在学习怎么读拍号。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍号告诉我们每小节有几拍。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把拍号抄错了，所以弹得很乱。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "华尔兹的拍号通常是三四拍。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这个小节前面加上拍号。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到这个拍号，我就知道是三拍子。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们：这个拍号是什么意思？", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "曲子中间换了拍号，节奏也变了。", "target_word": "拍号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拍號", "label": "繁体"}], "register": "专业", "sense_fingerprint": "乐谱上表示节奏强弱规律的符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ea6cd0-2927-4045-bed6-9cd5a0064201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22078, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拍号", "is_correct": true, "explanation": "正确：拍号，乐谱上表示节奏强弱规律的符号。"}, {"text": "排号", "is_correct": false, "explanation": "pái（第二声）与 pāi（第一声）声调不同，意思是排号（排队取号），与乐谱无关。"}, {"text": "牌号", "is_correct": false, "explanation": "pái（第二声）与 pāi（第一声）声调不同，意思是牌号（产品或车辆的编号）。"}, {"text": "拍好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是拍好（拍得好、拍完成）。"}, {"text": "拍照", "is_correct": false, "explanation": "zhào 与 hào 声母不同（zh 与 h），意思是拍照（照相）。"}], "explanations": {"拍号": "正确：拍号，乐谱上表示节奏强弱规律的符号。", "排号": "pái（第二声）与 pāi（第一声）声调不同，意思是排号（排队取号），与乐谱无关。", "牌号": "pái（第二声）与 pāi（第一声）声调不同，意思是牌号（产品或车辆的编号）。", "拍好": "hǎo（第三声）与 hào（第四声）声调不同，意思是拍好（拍得好、拍完成）。", "拍照": "zhào 与 hào 声母不同（zh 与 h），意思是拍照（照相）。"}, "sentence_index": null, "correct_answer": "拍号"}, "level_3": {"options": [{"text": "拍号", "is_correct": true, "explanation": "正确：乐曲开头标出的是拍号，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：乐谱开头不标价格，句子不通。"}, {"text": "地址", "is_correct": false, "explanation": "语义：乐谱开头不标地址，与乐曲无关。"}, {"text": "节奏感", "is_correct": false, "explanation": "搭配：“标出”一般接具体的记号，不能接“节奏感”这样的抽象感受。"}], "explanations": {"拍号": "正确：乐曲开头标出的是拍号，符合句意。", "价格": "语义：乐谱开头不标价格，句子不通。", "地址": "语义：乐谱开头不标地址，与乐曲无关。", "节奏感": "搭配：“标出”一般接具体的记号，不能接“节奏感”这样的抽象感受。"}, "sentence_index": 0, "correct_answer": "拍号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们跟着拍号拍手。", "explanation": "这里应该用〈节拍〉。拍号是乐谱上的记号，不能让人跟着它拍手；跟着打拍子的是节拍。"}, {"text": "这架钢琴的拍号很好听。", "explanation": "这里应该用〈声音〉。拍号是乐谱上的记号，不能说好不好听。"}, {"text": "这个拍号很长。", "explanation": "这里应该用〈音符〉。音符有时值的长短，拍号只标明拍数与强弱规律，不能说长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拍号", "is_correct": true, "explanation": "正确：在小节前加上拍号，符合句意。"}, {"text": "页码", "is_correct": false, "explanation": "语义：页码标在页面上，不标在小节前面。"}, {"text": "温度", "is_correct": false, "explanation": "语义：乐谱上不标温度，与小节前的标记无关。"}, {"text": "调调", "is_correct": false, "explanation": "语域：“调调”是口语说法，不能用于记谱语境。"}], "explanations": {"拍号": "正确：在小节前加上拍号，符合句意。", "页码": "语义：页码标在页面上，不标在小节前面。", "温度": "语义：乐谱上不标温度，与小节前的标记无关。", "调调": "语域：“调调”是口语说法，不能用于记谱语境。"}, "sentence_index": 6, "correct_answer": "拍号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段音乐的拍号很大。", "explanation": "这里应该用〈音量〉。拍号不表示声音的大小，不能说“很大”。"}, {"text": "这首曲子的拍号是D大调。", "explanation": "这里应该用〈调号〉。调号标明曲子的调性（如D大调），拍号标明每小节的拍数，二者不能互换。"}, {"text": "这首歌的拍号很快。", "explanation": "这里应该用〈速度〉。拍号只标明拍数与强弱规律，不表示快慢；快慢要用速度或节奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份乐谱上的拍号写很清楚。", "corrected_sentence": "这份乐谱上的拍号写得很清楚。", "error_description": "补语错误：动词“写”后带程度补语“很清楚”，中间必须用“得”连接，应说“写得很清楚”，不能说“写很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "曲子中间标了两拍号。", "corrected_sentence": "曲子中间标了两个拍号。", "error_description": "量词缺失：数词“两”后面要带量词，拍号应用量词“个”，应说“两个拍号”，不能说“两拍号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
