INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几条不同的旋律同时一起唱或演奏的音乐。", "primary_collocate": null, "pronunciation": "fù diào yīn yuè", "ipa": "fu˥˩ tjɑʊ˥˩ in˥ ɥe˥˩", "syllable_count": 4, "sentences": [{"text": "复调音乐是好几种声音一起唱的音乐。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合唱团今晚要唱一首复调音乐。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢听教堂里的复调音乐。", "target_word": "复调音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "复调音乐里，每个人唱的旋律都不一样。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三个人一起唱复调音乐，很好听。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说复调音乐比一般的歌难唱。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首复调音乐有四个声部。", "target_word": "复调音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妹妹在学校学过复调音乐。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着复调音乐，她慢慢睡着了。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复调音乐听起来像好几个人在聊天。", "target_word": "复调音乐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复调音乐作品", "label": "复合"}], "register": "中性", "sense_fingerprint": "几条不同旋律同时进行的音乐；多个声部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ea6cd0-2927-4045-bed6-9cd5a0064201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复调音乐", "is_correct": true, "explanation": "正确答案：复调音乐即好几种声音一起唱的音乐，此句是定义"}, {"text": "单声部", "is_correct": false, "explanation": "语义：“单声部”只有一条声音线，与“好几种声音一起唱”相反"}, {"text": "独唱", "is_correct": false, "explanation": "语义：“独唱”是一个人唱，与“好几种声音一起唱”相反"}, {"text": "小提琴", "is_correct": false, "explanation": "搭配：“小提琴”是乐器，不能作为“好几种声音一起唱的音乐”的主语来下定义"}], "explanations": {"复调音乐": "正确答案：复调音乐即好几种声音一起唱的音乐，此句是定义", "单声部": "语义：“单声部”只有一条声音线，与“好几种声音一起唱”相反", "独唱": "语义：“独唱”是一个人唱，与“好几种声音一起唱”相反", "小提琴": "搭配：“小提琴”是乐器，不能作为“好几种声音一起唱的音乐”的主语来下定义"}, "sentence_index": 0, "correct_answer": "复调音乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首复调音乐是两个人轮流唱的，一人一段。", "explanation": "这里应该用〈对唱〉。两人轮流唱是对唱，复调音乐要求几条独立旋律同时进行"}, {"text": "这首复调音乐只有一个人唱，很好听。", "explanation": "这里应该用〈独唱〉。独唱只有一个人唱，复调音乐要求几个声部同时进行"}, {"text": "这首复调音乐里，只有鼓在敲，没有人唱。", "explanation": "这里应该用〈打击乐〉。只有鼓点、没有旋律的是打击乐，复调音乐要求好几条旋律同时进行"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复调音乐", "is_correct": true, "explanation": "正确答案：复调音乐有好几个声部，句中说的是它有四个声部"}, {"text": "诗", "is_correct": false, "explanation": "语义：诗是文字作品，没有“声部”"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说不是乐曲，不能说它有“声部”"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“首”用于歌曲等，不能说“这首钢琴”"}], "explanations": {"复调音乐": "正确答案：复调音乐有好几个声部，句中说的是它有四个声部", "诗": "语义：诗是文字作品，没有“声部”", "小说": "语义：小说不是乐曲，不能说它有“声部”", "钢琴": "搭配：“首”用于歌曲等，不能说“这首钢琴”"}, "sentence_index": 6, "correct_answer": "复调音乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首复调音乐很简单，只有一个声音。", "explanation": "这里应该用〈单声部〉。它只有一个声音线，复调音乐需要几个独立声部"}, {"text": "复调音乐只是为歌声配和音，不抢旋律。", "explanation": "这里应该用〈伴奏〉。伴奏只为主旋律配和音，复调音乐中各声部旋律同等重要"}, {"text": "这首复调音乐里，大家齐声唱同一条旋律。", "explanation": "这里应该用〈齐唱〉。大家唱同一条旋律是齐唱，不是好几种声音一起唱的复调"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹弹钢琴，常常练习一把复调音乐。", "corrected_sentence": "我妹妹弹钢琴，常常练习一首复调音乐。", "error_description": "错误：“一把复调音乐”；正确：“一首复调音乐”。乐曲用量词“首”，“把”用于有柄的器具，不能用于音乐", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈喜欢在晚上听复调音乐们。", "corrected_sentence": "妈妈喜欢在晚上听复调音乐。", "error_description": "错误：“复调音乐们”多了“们”；“们”只用于指人的名词，“音乐”不能加“们”，删去即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
