INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "音乐里，很多声音在一起的样子，就像布上有很多线交叉。", "primary_collocate": null, "pronunciation": "zhī tǐ", "ipa": "ʈʂʅ˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "织体就是音乐里很多声音在一起的样子。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的织体很厚，有很多声音。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，织体像布上交叉的线。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "独奏的织体比较薄，只有一个声音。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听一听，这段织体里有几个声音？", "target_word": "织体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢这首曲子丰富的织体。", "target_word": "织体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "换了乐器，织体听起来也不一样了。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合唱的织体比一个人唱的复杂。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把这段织体写得更简单。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种织体让音乐听起来很温暖。", "target_word": "织体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复调织体", "label": "复合"}, {"form": "音乐织体", "label": "复合"}], "register": "中性", "sense_fingerprint": "音乐里很多声音在一起的样子，像交叉的线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ea6cd0-2927-4045-bed6-9cd5a0064201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "织体", "is_correct": true, "explanation": "正确：织体（zhī tǐ）指很多声音在一起的样子。"}, {"text": "尸体", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh/zh），声调相同，意思是尸体。"}, {"text": "直体", "is_correct": false, "explanation": "声调混淆：zhí 与 zhī 只差声调，意思是身体挺直的姿势。"}, {"text": "知底", "is_correct": false, "explanation": "dǐ 与 tǐ 声母不同（d/t），第一个音节相同，意思是知道底细。"}, {"text": "质体", "is_correct": false, "explanation": "声调混淆：zhì 与 zhī 声母韵母相同、只差声调，意思是植物细胞里的质体。"}], "explanations": {"织体": "正确：织体（zhī tǐ）指很多声音在一起的样子。", "尸体": "shī 与 zhī 声母不同（sh/zh），声调相同，意思是尸体。", "直体": "声调混淆：zhí 与 zhī 只差声调，意思是身体挺直的姿势。", "知底": "dǐ 与 tǐ 声母不同（d/t），第一个音节相同，意思是知道底细。", "质体": "声调混淆：zhì 与 zhī 声母韵母相同、只差声调，意思是植物细胞里的质体。"}, "sentence_index": null, "correct_answer": "织体"}, "level_3": {"options": [{"text": "节奏", "is_correct": false, "explanation": "语义：节奏是快慢的规律，不是很多声音在一起的样子，这个定义说的是织体。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“音量”说的是声音大小，不能用“就是……的样子”来解释。"}, {"text": "织体", "is_correct": true, "explanation": "正确：〈织体〉的定义就是音乐里很多声音在一起的样子，符合句意。"}, {"text": "花纹", "is_correct": false, "explanation": "语义：花纹是图案，与音乐里声音的组合无关，句子不成立。"}], "explanations": {"节奏": "语义：节奏是快慢的规律，不是很多声音在一起的样子，这个定义说的是织体。", "音量": "搭配：“音量”说的是声音大小，不能用“就是……的样子”来解释。", "织体": "正确：〈织体〉的定义就是音乐里很多声音在一起的样子，符合句意。", "花纹": "语义：花纹是图案，与音乐里声音的组合无关，句子不成立。"}, "sentence_index": 0, "correct_answer": "织体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座楼的织体很坚固。", "explanation": "这里应该用〈结构〉。织体指很多声音一起的样子，楼房的构造要用结构。"}, {"text": "他的织体比我高很多。", "explanation": "这里应该用〈身高〉。织体指声音组合的样子，人的身高不能用织体来说。"}, {"text": "这段舞曲的织体很快。", "explanation": "这里应该用〈节奏〉。织体指很多声音一起的样子，不指拍子的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体温", "is_correct": false, "explanation": "搭配：“听起来”只能用于声音，“体温”不能被听，也不能“换了乐器”。"}, {"text": "墙纸", "is_correct": false, "explanation": "语义：墙纸与乐器和声音无关，“换了乐器”后墙纸不会听起来不一样。"}, {"text": "织体", "is_correct": true, "explanation": "正确：〈织体〉指声部的组合，换了乐器后听起来会不一样，符合句意。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：字迹是文字的笔画，不是声音，换乐器不会改变字迹的听感。"}], "explanations": {"体温": "搭配：“听起来”只能用于声音，“体温”不能被听，也不能“换了乐器”。", "墙纸": "语义：墙纸与乐器和声音无关，“换了乐器”后墙纸不会听起来不一样。", "织体": "正确：〈织体〉指声部的组合，换了乐器后听起来会不一样，符合句意。", "字迹": "语义：字迹是文字的笔画，不是声音，换乐器不会改变字迹的听感。"}, "sentence_index": 6, "correct_answer": "织体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的织体很硬，是石头组成的。", "explanation": "这里应该用〈岩层〉。织体指声音组合的样子，山石的组成要用岩层来说。"}, {"text": "妈妈的织体比去年重了五公斤。", "explanation": "这里应该用〈体重〉。织体指声音组合的样子，人的重量要用体重来说。"}, {"text": "这间屋子的织体很大，能放下一张床。", "explanation": "这里应该用〈面积〉。织体指声音组合的样子，房间的大小要用面积来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首合唱有一条很厚的织体。", "corrected_sentence": "这首合唱有一种很厚的织体。", "error_description": "量词错了：“织体”前面应该用“种”。“条”用于细长的东西，不能用来数织体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段重唱有一把织体，声部很多。", "corrected_sentence": "这段重唱有一种织体，声部很多。", "error_description": "量词错了：“织体”前面应该用“种”。“把”用于有柄的东西，不能用来数织体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97c1d7b-d205-4aae-b0e3-d96f26d96040') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
