INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22086, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很准确，很细致。", "primary_collocate": null, "pronunciation": "jīng mì", "ipa": "tɕiŋ˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "这台机器非常精密。", "target_word": "精密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手表里的零件很精密。", "target_word": "精密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用精密的仪器检查眼睛。", "target_word": "精密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种精密的机器，一点灰尘也不能有。", "target_word": "精密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们做了精密的计算，才发射火箭。", "target_word": "精密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "精密的仪器要小心放好。", "target_word": "精密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂能做精密的零件。", "target_word": "精密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块表比那块更精密。", "target_word": "精密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用精密的尺子量头发。", "target_word": "精密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的结构非常精密。", "target_word": "精密", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精密地", "label": "状语形式"}, {"form": "精密度", "label": "复合"}], "register": "书面", "sense_fingerprint": "机器、仪器、计算等又准又细致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59cd57e6-a11a-4731-b10a-b0c4705d2478') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22086, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精密", "is_correct": true, "explanation": "正确：精密（jīng mì）指仪器、计算等准确细致。"}, {"text": "精米", "is_correct": false, "explanation": "mǐ（第三声）与 mì（第四声）声调不同，意思是经过精加工的大米。"}, {"text": "机密", "is_correct": false, "explanation": "jī（无韵尾 -ng）与 jīng（韵尾 -ng）韵母不同，机密指需要保守的秘密。"}, {"text": "紧密", "is_correct": false, "explanation": "jǐn（第三声，韵尾 -n）与 jīng（第一声，韵尾 -ng）不同，意思是靠得很近、结合得紧。"}, {"text": "精明", "is_correct": false, "explanation": "míng（第二声）与 mì（第四声）韵母与声调都不同，意思是聪明能干。"}], "explanations": {"精密": "正确：精密（jīng mì）指仪器、计算等准确细致。", "精米": "mǐ（第三声）与 mì（第四声）声调不同，意思是经过精加工的大米。", "机密": "jī（无韵尾 -ng）与 jīng（韵尾 -ng）韵母不同，机密指需要保守的秘密。", "紧密": "jǐn（第三声，韵尾 -n）与 jīng（第一声，韵尾 -ng）不同，意思是靠得很近、结合得紧。", "精明": "míng（第二声）与 mì（第四声）韵母与声调都不同，意思是聪明能干。"}, "sentence_index": null, "correct_answer": "精密"}, "level_3": {"options": [{"text": "精密", "is_correct": true, "explanation": "正确：精密形容机器准确、细致，与「非常」搭配自然。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：「幽默」形容人的风趣，不能用来形容机器。"}, {"text": "英俊", "is_correct": false, "explanation": "语义：「英俊」说的是人的外貌，机器不能用它来形容。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：「悲伤」表示人的情绪，与机器的性能无关。"}], "explanations": {"精密": "正确：精密形容机器准确、细致，与「非常」搭配自然。", "幽默": "语义：「幽默」形容人的风趣，不能用来形容机器。", "英俊": "语义：「英俊」说的是人的外貌，机器不能用它来形容。", "悲伤": "语义：「悲伤」表示人的情绪，与机器的性能无关。"}, "sentence_index": 0, "correct_answer": "精密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的蛋糕做得很精密，奶油花纹像画一样。", "explanation": "这里应该用〈精致〉。精致形容工艺细巧、好看；精密用于仪器、机械的准确度，不用来形容蛋糕。"}, {"text": "这首歌的旋律很精密，听起来很温柔。", "explanation": "这里应该用〈优美〉。形容旋律好听用“优美”；“精密”指仪器、计算等的准确细致，不用来形容乐曲。"}, {"text": "她的性格很精密，大家都不敢和她开玩笑。", "explanation": "这里应该用〈严肃〉。精密指仪器、计算等的准确细致，形容人的性格不苟言笑要用严肃，不能说性格精密。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精密", "is_correct": true, "explanation": "正确：精密修饰零件，表示加工精度高，语义与语境相符。"}, {"text": "慷慨", "is_correct": false, "explanation": "语义：「慷慨」形容人的品质，不能修饰零件。"}, {"text": "香甜", "is_correct": false, "explanation": "语义：「香甜」形容食物的味道，不能用来形容零件。"}, {"text": "苗条", "is_correct": false, "explanation": "语义：「苗条」形容人的身材，不能用来形容零件。"}], "explanations": {"精密": "正确：精密修饰零件，表示加工精度高，语义与语境相符。", "慷慨": "语义：「慷慨」形容人的品质，不能修饰零件。", "香甜": "语义：「香甜」形容食物的味道，不能用来形容零件。", "苗条": "语义：「苗条」形容人的身材，不能用来形容零件。"}, "sentence_index": 6, "correct_answer": "精密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你精密地说一下这件事的经过。", "explanation": "这里应该用〈详细〉。精密多指仪器、计算的细致准确，讲述经过要用详细。"}, {"text": "这碗汤煮得很精密，每一步都很用心。", "explanation": "这里应该用〈精心〉。精密形容仪器、计算的准确程度，做饭时的用心要说精心。"}, {"text": "这首诗的意境很精密，读了让人心里很平静。", "explanation": "这里应该用〈深远〉。精密用于仪器、计算等，不用来形容诗的意境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台仪器比精密，测量很准。", "corrected_sentence": "这台仪器很精密，测量很准。", "error_description": "比较结构错误：「比」字句需要比较对象，「比精密」不完整，应用程度副词「很」，说「很精密」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台精密地仪器很贵。", "corrected_sentence": "这台精密的仪器很贵。", "error_description": "「精密地仪器」错误，应改为「精密的仪器」。「地」用于状语，修饰名词要用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f61c87a-2f96-4f96-b39a-add6d62ee4b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22088, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "残缺", "is_correct": true, "explanation": "残缺指不完整、有缺失，与“完整”相对。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、容易看懂，与“完整”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮指好看，与“完整”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音，与“完整”没有反义关系。"}], "correct_answer": "残缺", "explanations": {"残缺": "残缺指不完整、有缺失，与“完整”相对。", "清楚": "清楚指明白、容易看懂，与“完整”没有反义关系。", "漂亮": "漂亮指好看，与“完整”没有反义关系。", "安静": "安静指没有声音，与“完整”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22088, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "残缺", "is_correct": true, "explanation": "残缺指不完整、有缺失，与“完整”相对。"}, {"text": "简单", "is_correct": false, "explanation": "简单指不复杂，与“完整”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹指人多、声音大，与“完整”没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "结实指牢固、不易坏，与“完整”没有反义关系。"}], "correct_answer": "残缺", "explanations": {"残缺": "残缺指不完整、有缺失，与“完整”相对。", "简单": "简单指不复杂，与“完整”没有反义关系。", "热闹": "热闹指人多、声音大，与“完整”没有反义关系。", "结实": "结实指牢固、不易坏，与“完整”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22088, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "全部，没有缺少。", "primary_collocate": null, "pronunciation": "wán zhěng", "ipa": "wan˧˥ ʈʂəŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本书很完整，一页也不少。", "target_word": "完整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的作业不完整，还差一个问题。", "target_word": "完整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套茶具很完整，杯子和茶壶都有。", "target_word": "完整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你写一个完整的句子。", "target_word": "完整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事不完整，我没听到结尾。", "target_word": "完整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把完整的名单交给了老师。", "target_word": "完整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那张地图很完整，每条路都有。", "target_word": "完整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套西装很完整，外套、裤子和背心都有。", "target_word": "完整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看完整的电影，不要看一半。", "target_word": "完整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份材料不完整，请你再找一找。", "target_word": "完整", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "完整地", "label": "状语形式"}, {"form": "完整性", "label": "复合"}, {"form": "不完整", "label": "否定"}], "register": "中性", "sense_fingerprint": "形容事物各部分齐全、没有缺少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b61e398c-20aa-46ca-9d37-d0eb222c07e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完整", "is_correct": true, "explanation": "“很完整”形容书没有缺少，与“一页也不少”一致。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：嘈杂指声音吵闹，不用来形容一本书是否齐全，与“一页也不少”无关。"}, {"text": "零碎", "is_correct": false, "explanation": "语义：“零碎”指不成套、有缺失，与“一页也不少”相矛盾。"}, {"text": "残破", "is_correct": false, "explanation": "语义：“残破”指有损坏、有缺失，与“一页也不少”相矛盾。"}], "explanations": {"完整": "“很完整”形容书没有缺少，与“一页也不少”一致。", "嘈杂": "语义：嘈杂指声音吵闹，不用来形容一本书是否齐全，与“一页也不少”无关。", "零碎": "语义：“零碎”指不成套、有缺失，与“一页也不少”相矛盾。", "残破": "语义：“残破”指有损坏、有缺失，与“一页也不少”相矛盾。"}, "sentence_index": 0, "correct_answer": "完整"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他学习很完整，每天都复习。", "explanation": "这里应该用〈努力〉。完整指没有缺少，不用来形容学习的态度，应说“学习很努力”。"}, {"text": "他的成绩很完整，每门课都不及格。", "explanation": "这里应该用〈糟糕〉。完整指没有缺少，不用来评价成绩，说成绩差要用〈糟糕〉。"}, {"text": "他很完整，一个人去了森林。", "explanation": "这里应该用〈勇敢〉。完整指没有缺少，不用来形容人的胆量，应说“很勇敢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完整", "is_correct": true, "explanation": "“很完整”形容地图齐全，符合“每条路都有”。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”指数量少，与“每条路都有”相矛盾。"}, {"text": "简短", "is_correct": false, "explanation": "搭配：“简短”多用于话语或文章，不用来形容地图。"}, {"text": "空荡", "is_correct": false, "explanation": "语义：“空荡”指没有东西，与“每条路都有”相矛盾。"}], "explanations": {"完整": "“很完整”形容地图齐全，符合“每条路都有”。", "稀少": "语义：“稀少”指数量少，与“每条路都有”相矛盾。", "简短": "搭配：“简短”多用于话语或文章，不用来形容地图。", "空荡": "语义：“空荡”指没有东西，与“每条路都有”相矛盾。"}, "sentence_index": 6, "correct_answer": "完整"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的步伐很完整，走得很快。", "explanation": "这里应该用〈矫健〉。完整指没有缺少，不用来形容步伐，形容步伐有力要说〈矫健〉。"}, {"text": "这孩子的脾气很完整，从来不生气。", "explanation": "这里应该用〈温和〉。完整指没有缺少，不用来形容性格脾气，应说“脾气很温和”。"}, {"text": "我最近心里很完整，总是睡不好。", "explanation": "这里应该用〈紧张〉。完整指没有缺少，不用来说心里的状态，应说“心里很紧张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告很完整性，老师很满意。", "corrected_sentence": "这份报告很完整，老师很满意。", "error_description": "错误形式：“很完整性”；正确形式：“很完整”。“完整性”是名词，不能直接受“很”修饰，形容报告应说“很完整”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师要求我们把作业完整的交上来。", "corrected_sentence": "老师要求我们把作业完整地交上来。", "error_description": "错误形式：“完整的交上来”；正确形式：“完整地交上来”。“完整”修饰动词“交”时要用“地”，不用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
