INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "脑袋里想事情的方法。", "primary_collocate": null, "pronunciation": "sī wéi", "ipa": "sɿ˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他的思维和我们不一样。", "target_word": "思维", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩的思维很简单。", "target_word": "思维", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好的思维方法能帮你学得更快。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想改变一下自己的思维。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的思维有时候比较慢。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画画能让我们的思维更自由。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的思维很特别，总有新想法。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做数学题要有清楚的思维。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们用不同的思维想问题。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子思维很快，一听就懂。", "target_word": "思维", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "思维方法", "label": "复合"}, {"form": "思维方式", "label": "复合"}, {"form": "一种思维", "label": "量词"}, {"form": "思維", "label": "繁体"}], "register": "中性", "sense_fingerprint": "脑子里想事情的方法和习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d3d665-f01a-4085-b9af-4eb3bf63dee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不属于某个人，不能说“他的天气”，与“和我们不一样”的比较也不成立。"}, {"text": "思维", "is_correct": true, "explanation": "思维：指脑子里想事情的方法和习惯，句中指他想问题的方式和我们不同。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”指一年中的时段，不是人的属性，不能说“他的季节”。"}, {"text": "晚霞", "is_correct": false, "explanation": "搭配：“晚霞”是自然景象，不能说“他的晚霞”。"}], "explanations": {"天气": "语义：“天气”不属于某个人，不能说“他的天气”，与“和我们不一样”的比较也不成立。", "思维": "思维：指脑子里想事情的方法和习惯，句中指他想问题的方式和我们不同。", "季节": "语义：“季节”指一年中的时段，不是人的属性，不能说“他的季节”。", "晚霞": "搭配：“晚霞”是自然景象，不能说“他的晚霞”。"}, "sentence_index": 0, "correct_answer": "思维"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的思维是周末去看海。", "explanation": "这里应该用〈想法〉。“思维”指想事情的方法，不能表示具体的打算。"}, {"text": "我喝了一杯奇怪的思维。", "explanation": "这里应该用〈茶〉。“思维”是抽象的想事情的方法，不能喝，应改为“我喝了一杯奇怪的茶”。"}, {"text": "这个问题让我思维了很久。", "explanation": "这里应该用〈思考〉。“思维”指想事情的方法，是名词，不能带“了很久”作动词用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "语义：“身材”指身体的外形，不会“总有新想法”，句意不通。"}, {"text": "思维", "is_correct": true, "explanation": "思维：指想事情的方法，“思维很特别，总有新想法”符合句意。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”是走路的动作，不会“总有新想法”，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的温度，与“总有新想法”不搭，句意不通。"}], "explanations": {"身材": "语义：“身材”指身体的外形，不会“总有新想法”，句意不通。", "思维": "思维：指想事情的方法，“思维很特别，总有新想法”符合句意。", "脚步": "语义：“脚步”是走路的动作，不会“总有新想法”，句意不通。", "体温": "语义：“体温”是身体的温度，与“总有新想法”不搭，句意不通。"}, "sentence_index": 6, "correct_answer": "思维"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研究人员得出了思维。", "explanation": "这里应该用〈结论〉。“得出”后接结论、答案等结果，“思维”不能作“得出”的宾语。"}, {"text": "校长听取了思维。", "explanation": "这里应该用〈意见〉。“听取”接意见、建议等内容，不接“思维”。"}, {"text": "她把思维挂在衣架上。", "explanation": "这里应该用〈衣服〉。“挂”接衣服、画等具体的物品，“思维”是抽象的心理活动，不能挂在衣架上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只很特别的思维。", "corrected_sentence": "他有一种很特别的思维。", "error_description": "量词错误：“思维”应使用量词“种”（一种思维）。“只”多用于动物或成对物品中的单个，不能用于“思维”，应改为“一种很特别的思维”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子地思维很灵活，一听就懂。", "corrected_sentence": "这个孩子的思维很灵活，一听就懂。", "error_description": "结构助词错误：“思维”是名词，前面表示领属要用“的”（孩子的思维），不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
