INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22092, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想出新东西或者做出以前没有的东西。", "primary_collocate": null, "pronunciation": "chuàng zuò", "ipa": "ʈʂʰuɑŋ˥˩ tsuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们用旧纸盒创作了一个机器人。", "target_word": "创作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想创作一种新的游戏。", "target_word": "创作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明喜欢自己创作故事。", "target_word": "创作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这支舞是她自己创作的。", "target_word": "创作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "厨师创作了一道新菜。", "target_word": "创作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一起创作一幅大画吧。", "target_word": "创作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在手机上创作小视频。", "target_word": "创作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "写歌的时候，他喜欢一个人创作。", "target_word": "创作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们创作的作品挂在教室里。", "target_word": "创作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想创作什么样的东西？", "target_word": "创作", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "创作了", "label": "体标"}, {"form": "创作过", "label": "体标"}, {"form": "创作者", "label": "复合"}, {"form": "創作", "label": "繁体"}], "register": "中性", "sense_fingerprint": "想出并做出以前没有的新东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d3d665-f01a-4085-b9af-4eb3bf63dee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拆卸", "is_correct": false, "explanation": "语义：“拆卸”是把已有的东西拆开，与“做出一个机器人”的意思相反。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：“粉碎”是打碎，句中要表达的是做出新东西，句意不通。"}, {"text": "创作", "is_correct": true, "explanation": "创作：想出并做出以前没有的东西，“用旧纸盒创作了一个机器人”符合句意。"}, {"text": "涂抹", "is_correct": false, "explanation": "搭配：“涂抹”多用于颜料、膏状物，不能说“涂抹了一个机器人”。"}], "explanations": {"拆卸": "语义：“拆卸”是把已有的东西拆开，与“做出一个机器人”的意思相反。", "粉碎": "语义：“粉碎”是打碎，句中要表达的是做出新东西，句意不通。", "创作": "创作：想出并做出以前没有的东西，“用旧纸盒创作了一个机器人”符合句意。", "涂抹": "搭配：“涂抹”多用于颜料、膏状物，不能说“涂抹了一个机器人”。"}, "sentence_index": 0, "correct_answer": "创作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他创作了那台旧收音机。", "explanation": "这里应该用〈拆〉。“拆”是把已有的东西拆开，“创作”指做出以前没有的东西，旧收音机本来就存在。"}, {"text": "工人们创作了这座古城。", "explanation": "这里应该用〈复原〉。“复原”是恢复原来的样子，“创作”指做出以前没有的东西。"}, {"text": "考古队创作了一座古墓。", "explanation": "这里应该用〈发掘〉。“发掘”指挖出已经存在的东西，“创作”指做出以前没有的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”用于动物或婴幼儿，不能用于小视频，句意不通。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”多用于衣物，不能说“缝补小视频”。"}, {"text": "煎炸", "is_correct": false, "explanation": "语义：“煎炸”是烹饪方法，与小视频无关，句意不通。"}, {"text": "创作", "is_correct": true, "explanation": "创作：做出以前没有的东西，“在手机上创作小视频”符合句意。"}], "explanations": {"喂养": "语义：“喂养”用于动物或婴幼儿，不能用于小视频，句意不通。", "缝补": "搭配：“缝补”多用于衣物，不能说“缝补小视频”。", "煎炸": "语义：“煎炸”是烹饪方法，与小视频无关，句意不通。", "创作": "创作：做出以前没有的东西，“在手机上创作小视频”符合句意。"}, "sentence_index": 6, "correct_answer": "创作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他创作了老师的字。", "explanation": "这里应该用〈模仿〉。“模仿”是照着别人的样子做，“创作”指做出以前没有的东西，两者意思相反。"}, {"text": "书店创作了那本古书。", "explanation": "这里应该用〈翻印〉。“翻印”是把已有的书再印一遍，“创作”指做出以前没有的东西。"}, {"text": "他创作了同学的作品。", "explanation": "这里应该用〈抄袭〉。“抄袭”是照搬别人的成果，“创作”指做出以前没有的东西，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用旧瓶子很创作了一件艺术品。", "corrected_sentence": "她用旧瓶子创作了一件艺术品。", "error_description": "程度副词位置错误：“很”修饰形容词，不能放在动词“创作”前，应去掉“很”，说“创作了一件艺术品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们正在创作了一幅新画。", "corrected_sentence": "我们正在创作一幅新画。", "error_description": "体标错误：“正在”表示动作进行中，与“了”不能同用，应去掉“了”，说“正在创作一幅新画”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbee2ea9-d72e-4eda-885a-29aebf9727c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
