INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物或想法的范围、种类；比如动物和植物是不同的范畴。", "primary_collocate": null, "pronunciation": "fàn chóu", "ipa": "fan˥˩ ʈʂʰoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这个问题不属于数学的范畴。", "target_word": "范畴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物和植物是不同的范畴。", "target_word": "范畴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讨论的范畴很广，有历史和艺术。", "target_word": "范畴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事超出了我们课堂的范畴。", "target_word": "范畴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "颜色和形状属于两个不同的范畴。", "target_word": "范畴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哲学研究的范畴非常大。", "target_word": "范畴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是法律范畴的问题，要问律师。", "target_word": "范畴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这些词按范畴分成三类。", "target_word": "范畴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种感情不在科学研究的范畴内。", "target_word": "范畴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作范畴包括写文章和做翻译。", "target_word": "范畴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个范畴", "label": "量词"}, {"form": "範疇", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物或想法的范围、种类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早餐", "is_correct": false, "explanation": "搭配：“数学的早餐”不成词组，“早餐”与“数学”的范围无关。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不属于数学的范围，句中“数学的”后面不能接“水果”。"}, {"text": "范畴", "is_correct": true, "explanation": "正确：“范畴”指种类或范围，“数学的范畴”表示数学的范围，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机与数学的范围无关，不符合“不属于数学的……”的语境。"}], "explanations": {"早餐": "搭配：“数学的早餐”不成词组，“早餐”与“数学”的范围无关。", "水果": "语义：水果不属于数学的范围，句中“数学的”后面不能接“水果”。", "范畴": "正确：“范畴”指种类或范围，“数学的范畴”表示数学的范围，符合句意。", "手机": "语义：手机与数学的范围无关，不符合“不属于数学的……”的语境。"}, "sentence_index": 0, "correct_answer": "范畴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学习了一座范畴。", "explanation": "这里应该用〈个〉。“范畴”是抽象的概念，量词应为〈个〉；〈座〉用于山、桥、楼等大型建筑。"}, {"text": "我把书放在范畴里。", "explanation": "“范畴”指事物的种类或范围，是抽象概念，不能指具体的地方，用法不当。"}, {"text": "他的汉语范畴很高。", "explanation": "这里应该用〈水平〉。“水平”指程度的高低，“范畴”指种类或范围，不能说程度高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“法律天气”不成词组，天气与法律的问题无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与法律的问题无关，不符合“要问律师”的语境。"}, {"text": "范畴", "is_correct": true, "explanation": "正确：“法律范畴”指法律的范围，与“要问律师”的语境相符。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“法律饭菜”不成词组，“饭菜”不能与“法律”搭配。"}], "explanations": {"天气": "语义：“法律天气”不成词组，天气与法律的问题无关。", "颜色": "语义：颜色与法律的问题无关，不符合“要问律师”的语境。", "范畴": "正确：“法律范畴”指法律的范围，与“要问律师”的语境相符。", "饭菜": "搭配：“法律饭菜”不成词组，“饭菜”不能与“法律”搭配。"}, "sentence_index": 6, "correct_answer": "范畴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头的范畴很厚。", "explanation": "这里“范畴”用错了：它指种类或范围，是抽象概念，不能用来描述物体的厚薄；描述厚度应使用〈厚度〉。"}, {"text": "他的范畴很开朗。", "explanation": "这里应该用〈性格〉。“性格”描述人的特点，“范畴”指种类或范围，不能形容人。"}, {"text": "我买了一双范畴。", "explanation": "这里“范畴”用错了：它指种类或范围，是抽象概念，不是可以买的东西，也不能用〈双〉来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些内容属于同一本范畴。", "corrected_sentence": "这些内容属于同一个范畴。", "error_description": "量词错误：“范畴”是抽象概念，量词应为“个”，“本”只用于书籍，应说“同一个范畴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些词属于同一范畴的。", "corrected_sentence": "这些词属于同一范畴。", "error_description": "句末多了“的”：“属于同一范畴”已是完整谓语，直接陈述即可；若要用“的”，须写成“这些词是属于同一范畴的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
