INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22100, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一件事情或一个事物变得固定、不再改变。", "primary_collocate": null, "pronunciation": "què lì", "ipa": "tɕʰɥe˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "大家一起确立了班级的规定。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规则已经确立，不会再改了。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先确立一个基本原则。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司确立了统一的标准。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人确立了恋爱关系。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的地位在公司里已经确立了。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我确立了目标，就不会改变。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校确立了新的校规。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过讨论，大家确立了比赛的规则。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律确立了每个人的权利。", "target_word": "确立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "确立了", "label": "体标（了）"}, {"form": "确立过", "label": "体标（过）"}, {"form": "確立", "label": "繁体"}], "register": "书面", "sense_fingerprint": "使事物固定下来，不再改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b63a2c7-7b4b-4b6e-a491-5467c19626e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "确立", "is_correct": true, "explanation": "正确。“确立”指让规定固定下来，不再改变，与句意相合。"}, {"text": "擦亮", "is_correct": false, "explanation": "语义：“擦亮”指使物体发亮，不能用于“班级的规定”，句子读不通。"}, {"text": "发脾气", "is_correct": false, "explanation": "配价：“发脾气”是不及物动词，不能带“规定”作宾语。"}, {"text": "咬碎", "is_correct": false, "explanation": "语义：“咬碎”指用牙齿弄碎东西，与“规定”不相合。"}], "explanations": {"确立": "正确。“确立”指让规定固定下来，不再改变，与句意相合。", "擦亮": "语义：“擦亮”指使物体发亮，不能用于“班级的规定”，句子读不通。", "发脾气": "配价：“发脾气”是不及物动词，不能带“规定”作宾语。", "咬碎": "语义：“咬碎”指用牙齿弄碎东西，与“规定”不相合。"}, "sentence_index": 0, "correct_answer": "确立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他确立了下周的考试日期。", "explanation": "这里应该用〈确定〉。“确立”指使制度、标准等固定下来，考试日期这类具体安排应用“确定”。"}, {"text": "他确立了这份工作。", "explanation": "这里应该用〈选定〉。“确立”指使制度、目标等固定下来，从几个选项中挑出工作应用“选定”。"}, {"text": "游戏确立了三个关卡。", "explanation": "这里应该用〈设定〉。游戏中安排关卡应用“设定”，“确立”指使制度、标准等固定下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "确立", "is_correct": true, "explanation": "正确。“确立”指使目标固定下来，不再改变，与“就不会改变”相合。"}, {"text": "捡", "is_correct": false, "explanation": "语义：“捡”指拾取地上的东西，不能用于“目标”，句子读不通。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”指窃取他人财物，与“目标”不相合，句子读不通。"}, {"text": "回答", "is_correct": false, "explanation": "搭配：“回答”的宾语应是问题，不能说回答目标。"}], "explanations": {"确立": "正确。“确立”指使目标固定下来，不再改变，与“就不会改变”相合。", "捡": "语义：“捡”指拾取地上的东西，不能用于“目标”，句子读不通。", "偷": "语义：“偷”指窃取他人财物，与“目标”不相合，句子读不通。", "回答": "搭配：“回答”的宾语应是问题，不能说回答目标。"}, "sentence_index": 6, "correct_answer": "确立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她确立了妈妈的建议。", "explanation": "这里应该用〈接受〉。“确立”不用于对他人建议的认可，接受建议应用“接受”。"}, {"text": "他终于确立了作业。", "explanation": "这里应该用〈完成〉。“确立”用于制度、目标、地位，完成作业应用“完成”。"}, {"text": "他确立了自己的错误。", "explanation": "这里应该用〈承认〉。“确立”不能用于认可错误，承认错误应用“承认”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家一起把班级的规定确立。", "corrected_sentence": "大家一起把班级的规定确立下来了。", "error_description": "错误：“把”字句缺少补语。应为“确立下来了”，“把”字句中动词后要有补语或“了”，句末不能只留动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两人很快确立着恋爱关系。", "corrected_sentence": "两人很快确立了恋爱关系。", "error_description": "错误：“确立着”。“很快”表示动作迅速完成，与表示持续状态的“着”不相容，应改为“确立了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
