INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22104, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用脑子想事情，比如看书、算数。", "primary_collocate": null, "pronunciation": "zhì lì huó dòng", "ipa": "ʈʂɻ̩˥˩ li˥˩ xuɔ˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "看书是一种智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算数也是智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩拼图，也是一种智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天看书、下棋，都是智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小时的智力活动让我觉得很累。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢体育活动，还是智力活动？", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算数和猜谜都是有趣的智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，孩子每天都要有一些智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打球是体力活动，看书是智力活动。", "target_word": "智力活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师推荐我们多做一些智力活动，比如猜谜和算数。", "target_word": "智力活动", "complexity_tier": "T3", "furigana": "zhì lì huó dòng", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}], "register": "中性", "sense_fingerprint": "用脑子想事情，如看书、算数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7d3d665-f01a-4085-b9af-4eb3bf63dee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
